        const lx = Math.floor(h3(n * 17 + i, 3, 9) * 16);
        const ly = Math.floor(h3(n * 41 + i, 11, 2) * 16);
        const rad = 1.4 + h3(n * 29 + i, 5, 7) * 1.7;
        const tilt = h3(n * 37 + i, 13, 1) > 0.5 ? 1 : -1;
        const col = h3(n * 43 + i, 2, 8) > 0.5 ? light : base;
