    if (h + 1 >= WH) continue;
    if (b[idx(lx, h, lz)] !== 1) continue;                 // 脚下是草地（沙漠/雪原/恶地自然被排除）
    if (b[idx(lx, h + 1, lz)] !== 0) continue;             // 上方空着
    const r = h3(wx * 7 + 11, 3, wz * 13 + 5);
    if (r > 0.975) b[idx(lx, h + 1, lz)] = 37;             // 2.5% 红花
