        const nx = x2 + ax2, ny = y + ay2, nz = z2 + az2;
        if (nx < 0 || nx >= CH || nz < 0 || nz >= CH || ny < 0 || ny >= WH) continue;  // 出界当实心
        if (b[idx(nx, ny, nz)] === 0) free++;
