      const tx = lx + OFF[d - 1][0] * sgn, tz = lz + OFF[d - 1][1] * sgn;
      if (tx < 0 || tx >= CH || tz < 0 || tz >= CH) continue;  // 跨区块的交给对面那个区块去修
      const ti = (y * CH + tz) * CH + tx;
      if (b[ti] !== 0) continue;                               // 那里有东西 / 本来就是床：不动
      if (!solidBelow(b[((y - 1) * CH + tz) * CH + tx])) continue;
