      const ux = P_[b] - P_[a], uy = P_[b + 1] - P_[a + 1], uz = P_[b + 2] - P_[a + 2];
      const vx = P_[c] - P_[a], vy = P_[c + 1] - P_[a + 1], vz = P_[c + 2] - P_[a + 2];
      let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
      const l = Math.hypot(nx, ny, nz) || 1;
