  sfx('craft');
  renderHotbar(); refreshHeld(); renderProcessor(); saveSoon();
  toast(`Cut sticks: ${k * PLANKS_PER_BATCH} Planks → ${k * STICKS_PER_BATCH} Sticks (have ${countOf(104)})`, 1.8);
  return k * STICKS_PER_BATCH;
