  if (k === keymap.bag) { if (started) openPanel(!panelOpen); e.preventDefault(); }
  if (k === 'KeyM' && started) { mmToggleBig(); e.preventDefault(); }    // 全屏地图（小地图缩放走 +/− 按钮）
