      const id = getBlock(x, y, z);
      if (id !== 23 && id !== 24) continue;
      if (getBlock(x, y - 1, z) !== 16) continue;          // 不在农田上就不长
      if (Math.random() > 0.34) continue;
      setBlock(x, y, z, id === 23 ? 24 : 17);
