  const txt = `${def.name} · Charge ${c}/${cap}` + (c <= 0 ? ' · out of charge: put it in a Charger + Uranium' : '');
  if (txt !== lastGunHud) { gunHudEl.textContent = txt; lastGunHud = txt; }
