  if (getBlock(x, hh + 1, z) === 7) return 4;               // 树冠 → 深绿
  const id = getBlock(x, hh, z);
  if (id === 5) return 3;
  if (id === 4) return 1;
  if (id === 7) return 4;
  if (id === 50) return 5;
