  if (acc > STEP * 2) acc = STEP * 2;               // 攒下的时间封顶，恢复时不再连续追帧
  if (__p) { PROF.frames++; const t1 = performance.now(); PROF.update += t1 - __t; __t = t1; }
  // ★ 区块流式加载：每帧一次（以前放在固定步里，低帧率时一帧要跑 6 遍 → 越卡越卡）
  const __s0 = __p ? performance.now() : 0;
