/* ============================================================ 外观 / 昵称（联机形象） */
const LOOK_KEY = 'bw_look_v1';
const SKIN_COLORS = [0xf3cba6, 0xe3ab7c, 0xc98f5c, 0xa06c42, 0x7c4f2d, 0x5b3a20, 0xd8b48a, 0x9fd3a6];
const CLOTH_COLORS = [0xd9534f, 0x4a7fd9, 0x1abc9c, 0xf0ad4e, 0x9b59b6, 0x394655, 0xe67e22, 0xf2f2f2];
const HAIR_COLORS = [0x221a14, 0x33251a, 0x6b4a2a, 0xc9a227, 0xb9bcc2, 0x8f3f2a];
const HAIR_STYLES = ['Short hair', 'Long hair'];
const LOOK = { name: '', skin: SKIN_COLORS[0], cloth: CLOTH_COLORS[0], hair: HAIR_COLORS[1], hs: 0, skinSrc: 'gen' };
function randPlayerName() { return 'player' + (10000 + Math.floor(Math.random() * 90000)); }
function saveLook() {
  try {
    localStorage.setItem(LOOK_KEY, JSON.stringify(LOOK));
    if (LOOK.name) localStorage.setItem('bw_nick', LOOK.name);    // 联机层读的是这个 key
  } catch (e) {}
  if (typeof NET !== 'undefined' && NET && NET.nick !== undefined && LOOK.name) NET.nick = LOOK.name;
}
function loadLook() {
  let d = null;
  try { d = JSON.parse(localStorage.getItem(LOOK_KEY) || 'null'); } catch (e) {}
  if (d && typeof d === 'object') {
    if (typeof d.name === 'string' && d.name.trim()) LOOK.name = d.name.trim().slice(0, 14);
    if (typeof d.skin === 'number') LOOK.skin = d.skin;
    if (typeof d.cloth === 'number') LOOK.cloth = d.cloth;
    if (typeof d.hair === 'number') LOOK.hair = d.hair;
    if (d.hs === 0 || d.hs === 1) LOOK.hs = d.hs;
    if (typeof d.skinSrc === 'string') LOOK.skinSrc = d.skinSrc;
  }
  if (!LOOK.name) LOOK.name = randPlayerName();                   // 没设过昵称 → player + 5 位随机数
  saveLook();
  return LOOK;
}
loadLook();

let lookRenderer = null, lookScene = null, lookCam = null, lookAv = null, lookRAF = 0, lookTorches = [];
/* ── MC 标准 64×64 皮肤 ───────────────────────────────────────────────
   玩家形象改成「贴图」模型：几何体照 MC 的 8×8×8 / 8×12×4 / 4×12×4 比例建，
   每个面的 UV 都按 MC 官方皮肤的坐标布局取图（64×64，1 像素 = 1/16 方块）。
   皮肤可以①由肤色/衣服/发色程序化生成，②上传玩家自己的 64×64 PNG。 */
const SKIN_SIZE = 64;
const SKIN_PX = MOB_PX;
// 每个部位每个面在 64×64 皮肤图里的矩形：[u, v, w, h]（v 从上往下）
const SKIN_UV = {
  head: { w: 8, h: 8, d: 8, top: [8, 0, 8, 8], bottom: [16, 0, 8, 8], right: [0, 8, 8, 8], front: [8, 8, 8, 8], left: [16, 8, 8, 8], back: [24, 8, 8, 8] },
  body: { w: 8, h: 12, d: 4, top: [20, 16, 8, 4], bottom: [28, 16, 8, 4], right: [16, 20, 4, 12], front: [20, 20, 8, 12], left: [28, 20, 4, 12], back: [32, 20, 8, 12] },
  armR: { w: 4, h: 12, d: 4, top: [44, 16, 4, 4], bottom: [48, 16, 4, 4], right: [40, 20, 4, 12], front: [44, 20, 4, 12], left: [48, 20, 4, 12], back: [52, 20, 4, 12] },
  armL: { w: 4, h: 12, d: 4, top: [36, 48, 4, 4], bottom: [40, 48, 4, 4], right: [32, 52, 4, 12], front: [36, 52, 4, 12], left: [40, 52, 4, 12], back: [44, 52, 4, 12] },
  legR: { w: 4, h: 12, d: 4, top: [4, 16, 4, 4], bottom: [8, 16, 4, 4], right: [0, 20, 4, 12], front: [4, 20, 4, 12], left: [8, 20, 4, 12], back: [12, 20, 4, 12] },
  legL: { w: 4, h: 12, d: 4, top: [20, 48, 4, 4], bottom: [24, 48, 4, 4], right: [16, 52, 4, 12], front: [20, 52, 4, 12], left: [24, 52, 4, 12], back: [28, 52, 4, 12] },
};

/* MC 64×64 第二层 UV（帽子 / 外套 / 袖子 / 裤腿） */
const SKIN_UV2 = {
  head: { top: [40, 0, 8, 8], bottom: [48, 0, 8, 8], right: [32, 8, 8, 8], front: [40, 8, 8, 8], left: [48, 8, 8, 8], back: [56, 8, 8, 8] },
  body: { top: [20, 32, 8, 4], bottom: [28, 32, 8, 4], right: [16, 36, 4, 12], front: [20, 36, 8, 12], left: [28, 36, 4, 12], back: [32, 36, 8, 12] },
  armR: { top: [44, 32, 4, 4], bottom: [48, 32, 4, 4], right: [40, 36, 4, 12], front: [44, 36, 4, 12], left: [48, 36, 4, 12], back: [52, 36, 4, 12] },
  armL: { top: [52, 48, 4, 4], bottom: [56, 48, 4, 4], right: [48, 52, 4, 12], front: [52, 52, 4, 12], left: [56, 52, 4, 12], back: [60, 52, 4, 12] },
  legR: { top: [4, 32, 4, 4], bottom: [8, 32, 4, 4], right: [0, 36, 4, 12], front: [4, 36, 4, 12], left: [8, 36, 4, 12], back: [12, 36, 4, 12] },
  legL: { top: [4, 48, 4, 4], bottom: [8, 48, 4, 4], right: [0, 52, 4, 12], front: [4, 52, 4, 12], left: [8, 52, 4, 12], back: [12, 52, 4, 12] },
};
const skinOverlayCache = new Map();
/* 这张皮肤的外层有没有内容？（程序化皮肤没有 → 直接跳过 36 个面，省性能） */
/* 缓存键要带「是哪张图」，否则换了皮肤还会用上一次的结论（这就是二层有时不出来的根因） */
function skinOverlayKey(src) {
  if (src === 'custom') return 'custom|' + (skinCustom ? (skinCustom.naturalWidth || skinCustom.width) + 'x' + (skinCustom.src || '').length + '|' + String(skinCustom.src || '').slice(-40) : 'none');
  return String(src);
}
function skinHasOverlay(src) {
  const ok = skinOverlayKey(src);
  if (skinOverlayCache.has(ok)) return skinOverlayCache.get(ok);
  if (src === 'custom' && !skinCustom) return false;     // 图还没到：先按没有二层处理，不缓存
  let has = false;
  try {
    const tex = skinTexture(src);
    const img = tex && tex.image;
    if (!img || (img.width !== 64 && img.naturalWidth !== 64)) return false;   // 还没解码 → 不缓存
    const cv = document.createElement('canvas'); cv.width = cv.height = 64;
    const g = cv.getContext('2d');
    g.drawImage(img, 0, 0, 64, 64);
    for (const part of Object.keys(SKIN_UV2)) {            // 外层 36 个矩形逐个扫
      for (const f of Object.keys(SKIN_UV2[part])) {
        const [x, y, w, h] = SKIN_UV2[part][f];
        if (x + w > 64 || y + h > 64) continue;
        const d = g.getImageData(x, y, w, h).data;
        for (let i = 3; i < d.length; i += 4) { if (d[i] > 8) { has = true; break; } }
        if (has) break;
      }
      if (has) break;
    }
  } catch (e) { has = false; }
  skinOverlayCache.set(ok, has);
  return has;
}

/* 每个部位 = 一个 BoxGeometry + 6 个材质（每面贴皮肤图里的一块矩形）
   这条路和方块贴图完全一样（blockFaceMat 同款：clone 纹理 + offset/repeat），
   在这个渲染器里百分百能画出来。 */
/* ── 皮肤图（64×64）：① 按配色程序化画 ② 直接读 PNG ───────────────── */
const SKIN_PNG_KEY = 'bw_skin_png_v1';
let skinCustom = null;          // 玩家上传的图片（HTMLImageElement）
const skinTexCache = new Map(); // 皮肤源 → THREE.Texture
const skinKeyCache = new Map(); // 皮肤源 → 短哈希（联机用）

const hex2 = c => '#' + (c >>> 0).toString(16).padStart(6, '0');
const shadeHex = (c, f) => tintHex(c, f);

/* 程序化画一张 64×64 的标准皮肤：头 8×8、身 8×12、四肢 4×12 */
function genSkinCanvas(skin, cloth, hair, hs) {
  const cv = document.createElement('canvas');
  cv.width = cv.height = 64;
  const g = cv.getContext('2d');
  g.imageSmoothingEnabled = false;
  const fill = (x, y, w, h, c) => { g.fillStyle = hex2(c); g.fillRect(x, y, w, h); };
  const H = hair || 0x33251a, long = hs === 1;
  const u = SKIN_UV;
  for (const key of ['top', 'bottom', 'right', 'front', 'left', 'back']) {
    const [x, y, w, h] = u.head[key];
    fill(x, y, w, h, skin);
  }
  const hairFace = (key, rows) => {
    const [x, y, w, h] = u.head[key];
    fill(x, y, w, Math.min(h, rows), H);
  };
  hairFace('top', 8);
  hairFace('right', long ? 8 : 3); hairFace('left', long ? 8 : 3);
  hairFace('back', long ? 8 : 5);
  hairFace('front', 2);
  const [fx, fy] = [u.head.front[0], u.head.front[1]];
  fill(fx + 1, fy + 4, 2, 1, 0xf2f2f2); fill(fx + 5, fy + 4, 2, 1, 0xf2f2f2);   // 细长眼：2×1
  fill(fx + 1, fy + 6, 3, 1, 0x2b1a12);                                           // 嘴：3×1
  for (const key of ['top', 'bottom', 'right', 'front', 'left', 'back']) {
    const [x, y, w, h] = u.body[key];
    fill(x, y, w, h, cloth);
    if (key !== 'top' && key !== 'bottom') { fill(x, y, w, 1, shadeHex(cloth, 0.82)); fill(x, y + h - 1, w, 1, shadeHex(cloth, 0.7)); }
    if (long && key === 'back') fill(x, y, w, Math.floor(h / 2), H);
  }
  for (const key of ['armR', 'armL']) {
    for (const f of ['top', 'bottom', 'right', 'front', 'left', 'back']) {
      const [x, y, w, h] = u[key][f];
      fill(x, y, w, h, skin);
      if (f === 'top') fill(x, y, w, h, cloth);
      else if (f !== 'bottom') { fill(x, y, w, 4, cloth); fill(x, y + h - 1, w, 1, shadeHex(skin, 0.86)); }
    }
  }
  const pants = shadeHex(cloth, 0.72);
  for (const key of ['legR', 'legL']) {
    for (const f of ['top', 'bottom', 'right', 'front', 'left', 'back']) {
      const [x, y, w, h] = u[key][f];
      fill(x, y, w, h, pants);
      if (f === 'top') fill(x, y, w, h, shadeHex(cloth, 0.6));
      else if (f !== 'bottom') fill(x, y + h - 1, w, 1, shadeHex(pants, 0.78));
    }
  }
  return cv;
}

const skinImgCache = new Map();      // dataURL → 已解码的 Image
function preloadSkin(dataUrl) {
  if (skinImgCache.has(dataUrl)) return Promise.resolve(skinImgCache.get(dataUrl));
  return new Promise((res, rej) => {
    const img = new Image();
    img.onload = () => { skinImgCache.set(dataUrl, img); res(img); };
    img.onerror = () => rej(new Error('skin decode'));
    img.src = dataUrl;
  });
}

/* 皮肤源 → 纹理（缓存） */
function skinTexture(src) {
  if (src === 'gen') src = 'gen:' + LOOK.skin + ':' + LOOK.cloth + ':' + LOOK.hair + ':' + LOOK.hs;
  if (skinTexCache.has(src)) return skinTexCache.get(src);
  if (skinTexCache.size > 80) skinTexCache.clear();
  let tex;
  if (src === 'custom' && skinCustom) {
    tex = new THREE.Texture(skinCustom);
    tex.needsUpdate = true;
  } else if (typeof src === 'string' && src.indexOf('data:image') === 0) {
    let img = skinImgCache.get(src);
    if (!img) { img = new Image(); img.src = src; }
    tex = new THREE.Texture(img);
    tex.needsUpdate = true;
  } else {
    let s = LOOK.skin, c = LOOK.cloth, hh = LOOK.hair, hhs = LOOK.hs;
    if (typeof src === 'string' && src.indexOf('gen:') === 0) {
      const a = src.split(':');
      s = +a[1] || s; c = +a[2] || c; hh = +a[3] || hh; hhs = +(a[4] || 0);
    }
    tex = new THREE.CanvasTexture(genSkinCanvas(s, c, hh, hhs));
  }
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  tex.generateMipmaps = false;
  tex.colorSpace = THREE.SRGBColorSpace;
  skinTexCache.set(src, tex);
  return tex;
}
function skinPngData() { try { return localStorage.getItem(SKIN_PNG_KEY) || ''; } catch (e) { return ''; } }
function skinHash(src) {
  if (src !== 'custom' && !(typeof src === 'string' && src.indexOf('data:image') === 0))
    return 'gen:' + LOOK.skin + ':' + LOOK.cloth + ':' + LOOK.hair + ':' + LOOK.hs;
  const s = (src === 'custom' && skinCustom) ? (skinCustom.src || 'custom') : String(src);
  let hh = 2166136261;
  for (let i = 0; i < s.length; i++) { hh ^= s.charCodeAt(i); hh = Math.imul(hh, 16777619); }
  return 'png:' + ((hh >>> 0).toString(36)) + ':' + s.length;
}

function buildSkinAvatar(opts) {
  const src = (opts && opts.skinSrc) ? opts.skinSrc : 'gen';
  const U = SKIN_PX;
  const key = (src === 'gen') ? ('gen:' + LOOK.skin + ':' + LOOK.cloth + ':' + LOOK.hair + ':' + LOOK.hs) : src;
  const base = skinTexture(key);
  const withOverlay = skinHasOverlay(key);
  const faceMat = (table, uvName, f, overlay) => {
    const [x, y, w, h] = table[uvName][f];
    const t = base.clone();
    t.needsUpdate = true;
    t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
    t.offset.set(x / SKIN_SIZE, 1 - (y + h) / SKIN_SIZE);
    t.repeat.set(w / SKIN_SIZE, h / SKIN_SIZE);
    t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter; t.generateMipmaps = false;
    const m = new THREE.MeshLambertMaterial({ map: t, side: THREE.DoubleSide, transparent: true });
    if (overlay) { m.alphaTest = 0.05; m.depthWrite = false; }   // 外层：半透明像素也画
    else { m.alphaTest = 0.5; }                                  // 基础层：透明像素直接丢掉（不会变黑块）
    return m;
  };
  /* 一个部位 = 6 张单面贴图（和方块同一条渲染路径）；PNG 有外层就再叠 6 张 */
  const part = (uvName, pw, ph, pd) => {
    const grp = new THREE.Group();
    const build = (table, grow, overlay) => {
      const W = pw * U + grow * 2, H = ph * U + grow * 2, D = pd * U + grow * 2;
      const mkPlane = (w, h, px2, py2, pz2, rx, ry, f) => {
        const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), faceMat(table, uvName, f, overlay));
        m.position.set(px2, py2, pz2); m.rotation.set(rx, ry, 0);
        if (!overlay) m.castShadow = true;
        grp.add(m);
      };
      mkPlane(W, H, 0, 0, -D / 2, 0, Math.PI, 'front');
      mkPlane(W, H, 0, 0, D / 2, 0, 0, 'back');
      mkPlane(D, H, -W / 2, 0, 0, 0, -Math.PI / 2, 'left');
      mkPlane(D, H, W / 2, 0, 0, 0, Math.PI / 2, 'right');
      mkPlane(W, D, 0, H / 2, 0, -Math.PI / 2, 0, 'top');
      mkPlane(W, D, 0, -H / 2, 0, Math.PI / 2, 0, 'bottom');
    };
    build(SKIN_UV, 0, false);
    if (withOverlay) build(SKIN_UV2, U * 0.5, true);            // 外层往外撑半像素
    return grp;
  };
  const g = new THREE.Group();
  const torso = part('body', 8, 12, 4); torso.position.y = 18 * U; g.add(torso);
  const headPivot = new THREE.Group(); headPivot.position.y = 24 * U; g.add(headPivot);
  const headMesh = part('head', 8, 8, 8); headMesh.position.y = 4 * U; headPivot.add(headMesh);
  const face = new THREE.Object3D(); face.position.set(0, 4 * U, -4.2 * U); headPivot.add(face);
  const mkArm = (sx, uvName) => {
    const pv = new THREE.Group(); pv.position.set(sx * 6 * U, 24 * U, 0);
    const m = part(uvName, 4, 12, 4); m.position.y = -6 * U; pv.add(m);
    g.add(pv); return pv;
  };
  const armR = mkArm(1, 'armR'), armL = mkArm(-1, 'armL');
  const mkLeg = (sx, uvName) => {
    const pv = new THREE.Group(); pv.position.set(sx * 2 * U, 12 * U, 0);
    const m = part(uvName, 4, 12, 4); m.position.y = -6 * U; pv.add(m);
    g.add(pv); return pv;
  };
  const legR = mkLeg(1, 'legR'), legL = mkLeg(-1, 'legL');
  return { g, torso, head: headPivot, face, armL, armR, foreR: armR, legL, legR };
}

/* ★ v339：远端玩家背上的氧气罐（第一人称看不到自己的 —— 那个模型只挂在别人的形象上）。
   坐标单位 = 皮肤像素（U = MOB_PX）：躯干中心 y=18px、厚 4px（背面 z=+2px），所以罐身中心 z≈4.8px。 */
function makeBackTank() {
  const U = MOB_PX;
  const g = new THREE.Group();
  const steel = new THREE.MeshLambertMaterial({ color: 0xc3ccd6 });
  const light = new THREE.MeshLambertMaterial({ color: 0xeef4fa });
  const copper = new THREE.MeshLambertMaterial({ color: 0xd98b4a });
  const dark = new THREE.MeshLambertMaterial({ color: 0x2b323b });
  const body = new THREE.Mesh(new THREE.CylinderGeometry(2.5 * U, 2.5 * U, 9 * U, 10), steel);
  body.position.y = 18 * U;
  const shine = new THREE.Mesh(new THREE.CylinderGeometry(2.55 * U, 2.55 * U, 0.7 * U, 10), light);
  shine.position.y = 18 * U;
  const b1 = new THREE.Mesh(new THREE.CylinderGeometry(2.62 * U, 2.62 * U, 0.8 * U, 10), copper);
  b1.position.y = 15 * U;
  const b2 = b1.clone(); b2.position.y = 21 * U;
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(1.0 * U, 1.3 * U, 1.4 * U, 8), copper);
  neck.position.y = 23.2 * U;
  const valve = new THREE.Mesh(new THREE.BoxGeometry(2.2 * U, 0.7 * U, 1.2 * U), dark);
  valve.position.y = 24.3 * U;
  const hose = new THREE.Mesh(new THREE.BoxGeometry(0.5 * U, 4 * U, 0.5 * U), dark);
  hose.position.set(-2.6 * U, 21 * U, 0.4 * U);
  g.add(body, shine, b1, b2, neck, valve, hose);
  g.position.z = 4.8 * U;               // 挂在躯干背面（模型正面 = -Z）
  g.traverse(o => { if (o.isMesh) o.castShadow = true; });
  return g;
}

/* 外观面板预览用的入口（保持旧签名） */
function buildAvatarMesh(skin, cloth, hair, hs, skinSrc) {
  return buildSkinAvatar({ skinSrc: skinSrc || LOOK.skinSrc }).g;
}
/* 外观预览的矿洞背景：石壁/地面/碎石 + 两支会闪的火把（只在预览里用，很便宜） */
function buildCaveBackdrop(S) {
  const rnd = mulberry32(4242);
  const darkMat = blockFaceMat(BLOCKS[50].top);        // 深板岩
  const rockMat = blockFaceMat(BLOCKS[9].top);         // 圆石
  const woodMat = new THREE.MeshLambertMaterial({ color: 0x6b4a2a });
  const flameMat = new THREE.MeshBasicMaterial({ color: 0xffb43a });
  const put = (w, h, d, x, y, z, mat) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    m.position.set(x, y, z); S.add(m); return m;
  };
  put(7, 0.6, 7, 0, -0.3, 0, darkMat);                 // 地面
  put(7, 4.2, 0.7, 0, 1.9, -2.6, darkMat);             // 后墙
  put(0.7, 4.2, 5.4, -2.9, 1.9, -0.4, rockMat);        // 左壁
  put(0.7, 4.2, 5.4, 2.9, 1.9, -0.4, rockMat);         // 右壁
  put(7, 0.7, 5.4, 0, 3.6, -0.4, darkMat);             // 洞顶
  for (let i = 0; i < 12; i++) {                       // 地上的碎石/石笋
    const x = (rnd() - 0.5) * 4.6, z = -2.3 + rnd() * 1.6, hh = 0.25 + rnd() * 1.05;
    put(0.35 + rnd() * 0.55, hh, 0.35 + rnd() * 0.55, x, hh / 2, z, rnd() < 0.5 ? darkMat : rockMat);
  }
  const torches = [];
  for (const [tx, tz, ph] of [[-1.8, -2.15, 0], [1.9, -1.95, 1.7]]) {   // 两支火把
    put(0.07, 0.55, 0.07, tx, 0.28, tz, woodMat);
    put(0.13, 0.17, 0.13, tx, 0.63, tz, flameMat);
    const l = new THREE.PointLight(0xffa240, 5.2, 7.5, 2);
    l.position.set(tx, 0.74, tz);
    l.userData.ph = ph;
    S.add(l);
    torches.push(l);
  }
  const disc = new THREE.Mesh(new THREE.CircleGeometry(0.62, 24),   // 人物脚下的暗影
    new THREE.MeshBasicMaterial({ color: 0x05070c, transparent: true, opacity: 0.55 }));
  disc.rotation.x = -Math.PI / 2; disc.position.y = 0.012;
  S.add(disc);
  return { torches };
}

function buildLookPreview() {
  const cv = $('lookCv');
  if (!cv || lookRenderer) return;
  lookRenderer = new THREE.WebGLRenderer({ canvas: cv, antialias: true, alpha: true });
  lookRenderer.setPixelRatio(Math.min(devicePixelRatio || 1, 2));
  lookRenderer.setSize(cv.width, cv.height, false);
  lookScene = new THREE.Scene();
  lookCam = new THREE.PerspectiveCamera(32, cv.width / cv.height, 0.1, 30);
  lookCam.position.set(1.0, 1.62, 3.35);
  lookCam.lookAt(0, 1.02, 0);
  lookScene.add(new THREE.HemisphereLight(0xffffff, 0x2a3346, 1.15));
  const dl = new THREE.DirectionalLight(0xffe7c4, 0.95);
  dl.position.set(1.6, 3, 2.4);
  lookScene.add(dl);
  const cave = buildCaveBackdrop(lookScene);          // 矿洞背景（含两支火把）
  lookTorches = cave.torches;
  lookAv = buildAvatarMesh(LOOK.skin, LOOK.cloth, LOOK.hair, LOOK.hs, LOOK.skinSrc);
  lookAv.rotation.y = Math.PI;                       // 模型正面朝 -Z，转 180° 才正对镜头
  lookScene.add(lookAv);
  const t0 = performance.now();
  const loop = () => {
    if ($('lookPanel').classList.contains('hide')) { lookRAF = 0; return; }
    // 小幅左右摇摆（±28°）而不是整圈转：始终能看到脸
    try {
      const tt = (performance.now() - t0) / 1000;
      lookAv.rotation.y = Math.PI + Math.sin(tt / 1.1) * 0.5;
      for (const l of lookTorches) l.intensity = 4.8 + Math.sin(tt * 7.3 + (l.userData.ph || 0)) * 0.9;   // 火把闪动
      lookRenderer.render(lookScene, lookCam);
    } catch (e) { console.error('[look] loop', e); lookRAF = 0; return; }
    lookRAF = requestAnimationFrame(loop);
  };
  lookRAF = requestAnimationFrame(loop);
}
function refreshLookAv() {
  if (!lookScene || !lookAv) return;
  lookScene.remove(lookAv);
  lookAv = buildAvatarMesh(LOOK.skin, LOOK.cloth, LOOK.hair, LOOK.hs, LOOK.skinSrc);
  lookAv.rotation.y = Math.PI;
  lookScene.add(lookAv);
}
function renderLookSwatches() {
  const mk = (row, list, key) => {
    if (!row) return;
    row.innerHTML = '';
    for (const c of list) {
      const b = document.createElement('button');
      b.className = 'sw' + (LOOK[key] === c ? ' on' : '');
      b.style.background = '#' + c.toString(16).padStart(6, '0');
      b.title = '#' + c.toString(16).padStart(6, '0');
      b.onclick = () => {
        LOOK[key] = c;
        if (LOOK.skinSrc === 'custom') { LOOK.skinSrc = 'gen'; try { localStorage.removeItem(SKIN_PNG_KEY); } catch (e) {} }
        saveLook(); renderLookSwatches(); refreshLookAv(); drawSkinThumb(); rebuildArms();
      };
      row.appendChild(b);
    }
  };
  mk($('lookSkin'), SKIN_COLORS, 'skin');
  mk($('lookCloth'), CLOTH_COLORS, 'cloth');
  mk($('lookHair'), HAIR_COLORS, 'hair');
  for (const b of document.querySelectorAll('#lookStyle .stbtn')) {     // 发型：短发 / 长发
    b.classList.toggle('on', (b.dataset.hs | 0) === LOOK.hs);
    b.onclick = () => { LOOK.hs = b.dataset.hs | 0; saveLook(); renderLookSwatches(); refreshLookAv(); };
  }
}
/* 皮肤缩略图（64×64 皮肤图本身） */
function drawSkinThumb() {
  const cv = $('skinThumb'); if (!cv) return;
  const g = cv.getContext('2d');
  g.imageSmoothingEnabled = false;
  g.clearRect(0, 0, 64, 64);
  if (LOOK.skinSrc === 'custom' && skinCustom) g.drawImage(skinCustom, 0, 0);
  else g.drawImage(genSkinCanvas(LOOK.skin, LOOK.cloth, LOOK.hair, LOOK.hs), 0, 0);
  const lb = $('skinLayers');                                    // 界面上直接显示二层有没有被认出来
  if (lb) {
    if (!skinCustom && LOOK.skinSrc === 'custom') lb.innerHTML = 'Second layer: <b style="color:#f5c451">Loading…</b>';
    else {
      const has = skinHasOverlay(LOOK.skinSrc === 'custom' ? 'custom' : 'gen');
      lb.innerHTML = has ? 'Second layer: <b style="color:#5fd18b">Yes</b> (hat/jacket/sleeves/pants)' : 'Second layer: <b style="color:#8ea3ba">No</b> (this image has no outer pixels)';
    }
  }
}
function setSkinFromFile(file) {
  if (!file) return;
  const fr = new FileReader();
  fr.onload = () => {
    const img = new Image();
    img.onload = () => {
      if (img.width !== 64 || img.height !== 64) {          // 只收 MC 标准 64×64
        toast(`Skin must be a 64×64 PNG (yours is ${img.width}×${img.height})`, 4);
        return;
      }
      skinCustom = img;
      LOOK.skinSrc = 'custom';
      skinTexCache.delete('custom'); skinOverlayCache.clear();
      try { localStorage.setItem(SKIN_PNG_KEY, String(fr.result)); } catch (e) {}
      saveLook();
      refreshLookAv();
      drawSkinThumb();
      toast('Skin applied (64×64)', 2);
    };
    img.onerror = () => toast('This PNG cannot be read, try another one', 3);
    img.src = String(fr.result);
  };
  fr.readAsDataURL(file);
}
function loadSavedSkin() {
  let d = null;
  try { d = localStorage.getItem(SKIN_PNG_KEY); } catch (e) {}
  if (!d) return;
  const img = new Image();
  img.onerror = () => { LOOK.skinSrc = 'gen'; saveLook(); refreshLookAv(); drawSkinThumb(); };
  img.onload = () => {
    skinCustom = img;
    if (LOOK.skinSrc === 'custom') { skinTexCache.delete('custom'); skinOverlayCache.clear(); refreshLookAv(); drawSkinThumb(); rebuildArms(); }
  };
  img.src = d;
}
// ⚠ 必须在 SKIN_PNG_KEY / skinCustom 这些定义之后调用：放到 loadLook() 那一行会因为 TDZ 抛错、
//    被内部的 try 吞掉，表现为「刷新后自定义皮肤丢了 / 二层识别不出来」。
loadSavedSkin();
rebuildArms();            // 手也要按皮肤上色（在皮肤模块初始化之后）
function openLook() {
  loadLook();
  $('lookPanel').classList.remove('hide');
  $('lookName').value = LOOK.name;
  $('lookAutoName').textContent = LOOK.name;
  $('lookNamePreview').textContent = LOOK.name;
  renderLookSwatches();
  drawSkinThumb();
  buildLookPreview();
}
$('btnLook').onclick = () => openLook();
$('btnSkinUp').onclick = () => $('skinFile').click();
$('skinFile').onchange = (e) => { const f = e.target.files && e.target.files[0]; setSkinFromFile(f); e.target.value = ''; };
$('btnSkinReset').onclick = () => {
  LOOK.skinSrc = 'gen';
  try { localStorage.removeItem(SKIN_PNG_KEY); } catch (e) {}
  saveLook(); refreshLookAv(); drawSkinThumb(); rebuildArms();
  toast('Switched back to the palette-generated skin', 2);
};
$('btnCloseLook').onclick = () => $('lookPanel').classList.add('hide');
$('lookName').addEventListener('input', () => {
  LOOK.name = $('lookName').value.trim().slice(0, 14);
  $('lookNamePreview').textContent = LOOK.name || '(empty = auto-generated)';
  saveLook();
});
$('lookName').addEventListener('blur', () => {
  if (!LOOK.name) LOOK.name = randPlayerName();          // 清空就自动补 player+5位
  $('lookName').value = LOOK.name;
  $('lookAutoName').textContent = LOOK.name;
  $('lookNamePreview').textContent = LOOK.name;
  saveLook();
});
$('btnBag').onclick = () => openPanel(!panelOpen);
$('btnClose').onclick = () => openPanel(false);
$('btnFurnaceClose').onclick = () => closeFurnace();
$('btnChargerClose').onclick = () => closeCharger();
$('btnProcessorClose').onclick = () => closeProcessor();
$('procOne').onclick = () => chipBatch(1);
$('procAll').onclick = () => chipBatch(Infinity);
/* ★ v367：任意木板 → 木棍 */
$('procSticks').onclick = () => stickBatch(1);
$('procSticksAll').onclick = () => stickBatch(Infinity);
$('btnPressClose').onclick = () => closePress();
$('pressOne').onclick = () => pressBatch(1);
$('pressAll').onclick = () => pressBatch(Infinity);
$('btnChestClose').onclick = () => closeChest();
$('btnRespawn').onclick = () => respawn();
addEventListener('resize', () => {
  renderer.setSize(innerWidth, innerHeight);
  camera.aspect = innerWidth / innerHeight; camera.updateProjectionMatrix();
  handCam.aspect = innerWidth / innerHeight; handCam.updateProjectionMatrix();
  if (menuCam) { menuCam.aspect = innerWidth / innerHeight; menuCam.updateProjectionMatrix(); }
  document.body.classList.toggle('portrait', innerHeight > innerWidth * 1.05);
});
document.body.classList.toggle('portrait', innerHeight > innerWidth * 1.05);
addEventListener('visibilitychange', () => { if (document.hidden && started) save(); });
addEventListener('beforeunload', () => { if (started) save(); });

/* ============================================================ 调试探针 */
window.GAME = {
  CFG, BLOCKS, ITEMS, RECIPES, MOB_DEFS, SMELT, player, chunks, edits, mobs, anim, inv: () => inv,
  get started() { return started; },
  get fps() { return fps; },
  get time() { return worldTime; },
  get light() { return lightLevel; },
  state() {
    return {
      started, fps: Math.round(fps), pos: [+player.p.x.toFixed(2), +player.p.y.toFixed(2), +player.p.z.toFixed(2)],
      yaw: +player.yaw.toFixed(3), hp: player.hp, hunger: +player.hunger.toFixed(1),
      onGround: player.onGround, chunks: chunks.size, mobs: mobs.length,
      light: +lightLevel.toFixed(2), clock: clockText(), water: player.inWater,
      held: held() ? nameOf(held().id) : null, sel: player.sel,
      armVisible: armR.visible && armR.position.length() > 0, handSceneChildren: handScene.children.length,
      objCount: scene.children.length, edits: edits.size,
    };
  },
  blockAt: (x, y, z) => getBlock(x, y, z),
  setBlock: (x, y, z, id) => setBlock(x, y, z, id),
  nameAt: (x, y, z) => nameOf(getBlock(x, y, z)),
  heightAt, n3, caveCarve,
    oreVeins,
    oreStats() {                                     // 统计已加载区块里的矿石分布
      const cnt = { 13: 0, 15: 0, 39: 0, 20: 0, 52: 0 }, ys = { 13: [99, 0], 15: [99, 0], 39: [99, 0], 20: [99, 0], 52: [99, 0] };
      for (const ch of chunks.values()) {
        const b = ch.blocks, CH = CFG.CH, WH = CFG.WH;
        for (let y = 0; y < WH; y++) for (let i = 0; i < CH * CH; i++) {
          const id = b[(y * CH * CH) + i];
          if (id !== 13 && id !== 15 && id !== 39 && id !== 20 && id !== 52) continue;
          cnt[id]++;
          if (y < ys[id][0]) ys[id][0] = y;
          if (y > ys[id][1]) ys[id][1] = y;
        }
      }
      return { chunks: chunks.size, counts: cnt, yRange: ys };
    },
  icons: { armR, armL, handScene, solidMat, waterMat, scene, camera, handCam, renderer, crackMesh, crackTex, heldGroup },
  debug: {
    start(fresh = false) {
      if (!started) {
        let w = fresh ? null : worldMeta(currentId);
        if (!w) w = createWorld({ name: fresh ? 'Debug World' : (worldMeta(currentId) ? worldMeta(currentId).name : 'Debug World'), mode: 'survival' });
        startGame(w);
      }
      return started;
    },
    startCreative() {
      if (!started) startGame(createWorld({ name: 'Debug · Creative', mode: 'creative' }));
      return started;
    },
    worlds: () => worlds.map(w => ({ id: w.id, name: w.name, mode: w.mode, seed: w.seed, seedText: w.seedText, updated: w.updated })),
    createWorld: (opts) => createWorld(opts),
    deleteWorld: (id) => deleteWorld(id),
    startWorld: (id) => { const w = worldMeta(id); if (!w) return false; startGame(w); return true; },
    currentWorld: () => ({ id: currentId, mode: MODE, seed: SEED, name: worldMeta(currentId) ? worldMeta(currentId).name : null }),
    fly: (on) => { player.fly = on === undefined ? !player.fly : !!on; return player.fly; },
    freeze: () => ({ ...FREEZE, glLost, sinceLossMs: glLost ? Math.round(performance.now() - glLostAt) : 0,
      sinceRenderMs: lastRenderAt ? Math.round(performance.now() - lastRenderAt) : null,
      mask: fzWrap ? fzWrap.style.display : null, shown: fzShown, recovering: glRecovering, shotbuf: SHOTBUF }),
    glTest: (mode) => {                       // 冻结自检：'lose' Lost GPU context / 'restore' 恢复
      try {
        // ⚠ 上下文已经丢了以后 getExtension 会返回 null（规范如此），扩展句柄必须提前缓存
        if (!window.__bwLoseExt) window.__bwLoseExt = renderer.getContext().getExtension('WEBGL_lose_context');
        const ext = window.__bwLoseExt;
        if (!ext) return 'no_ext';
        if (mode === 'restore') { ext.restoreContext(); return 'restore_called'; }
        ext.loseContext(); return 'lose_called';
      } catch (e) { return String(e); }
    },
    mode: () => MODE,
    save: () => { save(); return { err: saveErr, size: (localStorage.getItem(worldKey(currentId)) || '').length }; },
    saveError: () => ({ err: saveErr, warned: saveWarned }),
    esc: (s) => escHtml(s),
    storage: () => Object.keys(localStorage),
    steps(n = 60) { for (let i = 0; i < n; i++) { update(STEP); } },
    look(yaw, pitch) { player.yaw = yaw; player.pitch = pitch; },
    tp(x, y, z) { player.p.set(x, y, z); player.v.set(0, 0, 0); },
    give(id, n = 1) { addItem(id, n); renderHotbar(); refreshHeld(); },
    clearInv() { inv = new Array(SLOTS).fill(null); renderHotbar(); refreshHeld(); },
    select(i) { player.sel = i; refreshHeld(); renderHotbar(); },
    setTime(t) { worldTime = t; updateSky(); },
    /* 探针：喂一条「房间时间」进来，看是渐进追上还是直接对齐（联机昼夜的验收用） */
    netTime(t) { netTimeApply(t); return { time: +worldTime.toFixed(3), off: +netTimeOff.toFixed(3) }; },
    netTimeTick(dt) { netTimeStep(dt); return { time: +worldTime.toFixed(3), off: +netTimeOff.toFixed(3) }; },
    setHp(v) { player.hp = v; },
    hurt: (n = 1) => damagePlayer(n),
    armor: () => ({ ...player.armor, ap: armorPoints() }),
    equip: (id) => { addItem(id, 1); return equipArmor(id); },
    nearTable: () => nearCraftingTable(),
    craftIdx: (i) => craft(RECIPES[i]),
    recipes: () => RECIPES.map((r, i) => ({ i, out: r.out, name: nameOf(r.out), tier: r.tier || 0, need: Object.keys(r.need).map(Number) })),
    respawn: () => respawn(),
    setHunger(v) { player.hunger = v; },
    sprintState: () => ({ latch: sprintLatch, touch: sprintTouch, fwdHeld: keyDown('fwd'), shift: keyDown('sprint'), gap: lastFwdGap, ui: uiOpen(), alive: player.alive }),
    mine(on) { mineHeld = !!on; if (on) creativeArmed = true; },        // 探针模拟一次按下（创造模式也要上膛）
    mineOnce() { const t = raycastVoxel(eyePos(), cameraDir(), CFG.REACH); if (t) breakBlock(t); return !!t; },
    mineTo() {
      const t = raycastVoxel(eyePos(), cameraDir(), CFG.REACH);
      if (!t) return null;
      player.mining = 0;
      let broke = false, i = 0;
      while (!broke && i++ < 900) { creativeArmed = true; broke = doMine(STEP, t); }
      return { x: t.x, y: t.y, z: t.z, id: t.id, broke };
    },
    place() { return placeBlock(); },
    craft: (idx) => craft(RECIPES[idx]),
    craftAll() { const out = []; RECIPES.forEach((r, i) => { if (craft(r)) out.push(i); }); return out; },
    spawnMob: (dx, dz) => { const m = spawnMob(dx === undefined ? undefined : [dx, dz]); return m ? [+m.p.x.toFixed(1), +m.p.y.toFixed(1), +m.p.z.toFixed(1)] : null; },
    attack: () => attack(),
    aimAt: (i = 0) => {
      const m = mobs[i]; if (!m) return null;
      const eye = eyePos();
      const c = m.p.clone(); c.y += 0.55;
      const d = c.sub(eye).normalize();
      player.yaw = Math.atan2(-d.x, -d.z);
      player.pitch = Math.asin(Math.max(-1, Math.min(1, d.y)));
      return { yaw: +player.yaw.toFixed(3), pitch: +player.pitch.toFixed(3) };
    },
    handPose: () => ({
      arm: armR.position.toArray().map(v => +v.toFixed(4)).concat(armR.rotation.toArray().slice(0, 3).map(v => +(+v).toFixed(4))),
      item: heldGroup.position.toArray().map(v => +v.toFixed(4)).concat(heldGroup.rotation.toArray().slice(0, 3).map(v => +(+v).toFixed(4))),
      kind: heldKindNow, visible: heldGroup.visible, heldId: heldFor,
      swing: +anim.swing.toFixed(3), mineW: +anim.mineW.toFixed(3), mineT: +anim.mineT.toFixed(3),
      equip: +anim.equip.toFixed(3), sway: [+anim.swayX.toFixed(4), +anim.swayY.toFixed(4)],
      // 动画调参用的探针：这些数字直接说明「哪段动作在生效、多强」
      sprintK: +anim.sprintK.toFixed(3), airK: +anim.airK.toFixed(3), waterK: +anim.waterK.toFixed(3),
      hurtK: +anim.hurtK.toFixed(3), swingN: anim.swingN, fov: +camera.fov.toFixed(2),
      camRoll: +camRoll.toFixed(4),
    }),
    // 朝向/动作方向探针：脸朝哪、手往哪甩、头抬还是低（怀疑符号反了时先看这些数）
    remoteFacing: () => Array.from(NET ? (NET.remotes || new Map()) : new Map()).map(([id, r]) => {
      const u = r.obj.userData || {};
      const nose = new THREE.Vector3();
      if (u.face) u.face.getWorldPosition(nose); else nose.copy(r.obj.position);
      const nd = nose.clone().sub(r.obj.position).normalize();
      const hand = new THREE.Vector3();
      if (u.foreR) u.foreR.getWorldPosition(hand);
      const hd = hand.clone().sub(r.obj.position).normalize();
      const up = new THREE.Vector3(0, 0, -1).applyQuaternion(r.obj.quaternion);
      return {
        name: r.name || id, rotY: +r.obj.rotation.y.toFixed(2),
        fwd: [+up.x.toFixed(2), +up.z.toFixed(2)],
        nose: [+nd.x.toFixed(2), +nd.y.toFixed(2), +nd.z.toFixed(2)],
        hand: [+hd.x.toFixed(2), +hd.y.toFixed(2), +hd.z.toFixed(2)],
        headX: +(u.head ? u.head.rotation.x : 0).toFixed(2),
        pitch: +(u.pitch || 0).toFixed(2), swing: +(u.swing || 0).toFixed(2),
      };
    }),
    // 直接量「符号对不对」：脸在旋转后朝上还是朝下、手在 armR 正/负角时朝前还是朝后
    remoteAxes: () => {
      const arr = Array.from(NET ? (NET.remotes || new Map()) : new Map());
      if (!arr.length) return null;
      const [, rr] = arr[0];
      const u = rr.obj.userData;
      const rel = (o) => { o.updateWorldMatrix(true, true); return new THREE.Vector3().setFromMatrixPosition(o.matrixWorld).sub(rr.obj.position); };
      u.head.rotation.x = 0; u.head.updateWorldMatrix(true, true);
      const faceRel = rel(u.face).sub(rel(u.head)).normalize();
      u.head.rotation.x = 0.4; u.head.updateWorldMatrix(true, true);
      const faceUp = rel(u.face).sub(rel(u.head)).normalize().y;
      u.head.rotation.x = 0;
      const handAt = (ax) => { u.armR.rotation.x = ax; u.foreR.updateWorldMatrix(true, true); return rel(u.foreR).normalize(); };
      const hb = handAt(0), hp = handAt(0.8), hn = handAt(-0.8);
      u.armR.rotation.x = 0; u.foreR.updateWorldMatrix(true, true);
      return {
        faceDirAt0: [+faceRel.x.toFixed(2), +faceRel.y.toFixed(2), +faceRel.z.toFixed(2)],
        faceUpAtRotX_pos: +faceUp.toFixed(3),
        handZ_armX0: +hb.z.toFixed(2), handZ_armX_pos: +hp.z.toFixed(2), handZ_armX_neg: +hn.z.toFixed(2),
      };
    },
    remoteAnim: () => Array.from(NET ? (NET.remotes || new Map()) : new Map()).map(([id, r]) => {
      const u = r.obj.userData || {};
      return {
        id, buf: (u.buf || []).length, spd: +(u.spd || 0).toFixed(2),
        gap: Math.round(u.gap || 0), lag: Math.round(u.lag || 0),
        since: Math.round(performance.now() - (u.lastSnapT || 0)),
        walk: +(u.walk || 0).toFixed(2), sprintK: +(u.sprintK || 0).toFixed(2),
        airK: +(u.airK || 0).toFixed(2), mineK: +(u.mineK || 0).toFixed(2), landK: +(u.landK || 0).toFixed(2),
        armR: +(u.armR ? u.armR.rotation.x : 0).toFixed(3), armL: +(u.armL ? u.armL.rotation.x : 0).toFixed(3),
        foreR: +(u.foreR ? u.foreR.rotation.x : 0).toFixed(3), legL: +(u.legL ? u.legL.rotation.x : 0).toFixed(3),
        pos: [+r.obj.position.x.toFixed(2), +r.obj.position.y.toFixed(2), +r.obj.position.z.toFixed(2)],
        roll: +r.obj.rotation.z.toFixed(3),
      };
    }),
    // 远端人形「骨架对齐」探针：头底 / 躯干顶 / 肩点应该是同一个高度（差值 0.000）。
    // 头悬空、肩不齐这类 bug 不用截图猜 —— 直接看这三个数字。
    remoteModel: () => Array.from(NET ? (NET.remotes || new Map()) : new Map()).map(([id, r]) => {
      const u = r.obj.userData || {};
      const U = MOB_PX, px = v => +(v / U).toFixed(2);        // 顺便换算成模型像素（1 px = 1/32 身高）
      const torsoTop = (u.torso ? u.torso.position.y : 0) + 6 * U;
      const headBottom = u.head ? u.head.position.y : 0;      // 头的 pivot 就在头底（颈部）
      const armTop = u.armR ? u.armR.position.y : 0;          // 胳膊 pivot 就在肩上
      return {
        name: r.name || id,
        torsoTop: +torsoTop.toFixed(4), headBottom: +headBottom.toFixed(4), armTop: +armTop.toFixed(4),
        gapHeadPx: px(headBottom - torsoTop), gapArmPx: px(armTop - torsoTop),
        base: u.base ? { torso: +u.base.torso.toFixed(4), head: +u.base.head.toFixed(4) } : null,
      };
    }),
    // 客人端「幽灵怪」探针：动作/受伤/血条这三样以前客人全看不到，用数字一眼判定。
    //   legX 在变 = 腿在迈；flash>0 = 正在红闪；barFill = 血条填充比例；barFaces≈1 = 血条正对镜头。
    ghostMobs: () => Array.from(NET ? (NET.ghosts || new Map()) : new Map()).map(([id, g]) => {
      const P = g.parts || {}, bar = P.bar;
      let faceDot = null;
      if (bar && bar.matrixWorld) {
        const e = bar.matrixWorld.elements;                 // 血条局部 +Z 的世界方向 = 第 3 列
        const cx = camera.position.x - e[12], cy = camera.position.y - e[13], cz = camera.position.z - e[14];
        const cl = Math.hypot(cx, cy, cz) || 1;
        faceDot = +(((e[8] * cx + e[9] * cy + e[10] * cz) / cl)).toFixed(3);
      }
      return {
        id, kind: g.kind, hp: g.hp, maxHp: g.maxHp, spd: +(g.spd || 0).toFixed(2),
        flash: +(g.flash || 0).toFixed(2),
        legX: +(P.legs && P.legs[0] ? P.legs[0].rotation.x : 0).toFixed(3),
        armX: +(P.arm1 ? P.arm1.rotation.x : 0).toFixed(3),
        headYaw: +(g.headYaw || 0).toFixed(2),
        dying: !!g.dying, dieT: +(g.dieT || 0).toFixed(2),
        fallX: +(P.core ? P.core.rotation.x : 0).toFixed(2),      // -1.42 附近 = 已经躺平
        scale: +g.obj.scale.x.toFixed(2),
        lunge: +(g.lunge || 0).toFixed(2), coresZ: +(P.core ? P.core.position.z : 0).toFixed(3),
        barVisible: bar ? bar.visible : null,
        barFill: P.barFg ? +P.barFg.scale.x.toFixed(2) : null,
        barFacesCam: faceDot,
      };
    }),
    swing: (type = 'attack', dur = 0.5) => startSwing(type, dur),
    pinMining: (v) => { MINE_PIN = v; },
    noiseTest(n = 4000) {
      const ch = [], rg = [];
      let carve = 0, surf = 0;
      for (let i = 0; i < n; i++) {
        const x = (Math.random() * 400 - 200) | 0, z = (Math.random() * 400 - 200) | 0;
        const h = heightAt(x, z);
        const y = 3 + Math.floor(Math.random() * Math.max(1, h - 5));
        ch.push(n3(x * 0.026, y * 0.05, z * 0.026));
        rg.push(1 - Math.abs(n3(x * 0.043 + 31.7, y * 0.019, z * 0.043 + 11.3) - 0.5) * 2);
        if (caveCarve(x, y, z, h)) carve++;
        const ys = h; if (caveCarve(x, ys, z, ys)) surf++;
      }
      const q = (arr, p) => { const a = arr.slice().sort((m, n) => m - n); return +a[Math.floor(p * (a.length - 1))].toFixed(3); };
      return { cheese: { q50: q(ch, .5), q90: q(ch, .9), q99: q(ch, .99), max: +Math.max(...ch).toFixed(3) },
               ridge: { q90: q(rg, .9), q99: q(rg, .99), max: +Math.max(...rg).toFixed(3) },
               carveFrac: +(carve / n).toFixed(3), surfaceHoleFrac: +(surf / n).toFixed(3) };
    },
    env: () => ({ underground, wet: wetGain ? +wetGain.gain.value.toFixed(3) : null, dripTimer: +dripTimer.toFixed(1) }),
    mineshafts: (r = 2) => {
      const pcx = Math.floor(player.p.x / MS_CELL), pcz = Math.floor(player.p.z / MS_CELL);
      const out = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const ms = mineshaftFor(pcx + dx, pcz + dz);
        if (ms) out.push({ ox: ms.ox, oz: ms.oz, baseY: ms.baseY, kind: ms.kind, corridors: ms.corridors, ops: ms.ops, entrance: ms.entrance });
      }
      return out;
    },
    enterMineshaft() {
      const pcx = Math.floor(player.p.x / MS_CELL), pcz = Math.floor(player.p.z / MS_CELL);
      for (let r = 0; r <= 3; r++) for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const ms = mineshaftFor(pcx + dx, pcz + dz);
        if (!ms) continue;
        // 从结构里挑一个真正被挖空的点站进去（方向随机，不能假设 ox+6 一定在巷道里）
        const airs = [];
        for (const arr of ms.byChunk.values()) for (const o of arr) if (o.t === 0 && o.y === ms.baseY + 1) airs.push(o);
        if (!airs.length) continue;
        const pick = airs[Math.floor(airs.length / 2)];
        const x = pick.x, z = pick.z, y = ms.baseY + 1;
        const cx = Math.floor(x / CFG.CH), cz = Math.floor(z / CFG.CH);
        for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) buildChunk(getChunk(cx + a, cz + b));
        player.p.set(x + 0.5, y, z + 0.5); player.v.set(0, 0, 0);
        camSmoothY = null;
        return { x: x + 0.5, y, z: z + 0.5, baseY: ms.baseY, kind: ms.kind, corridors: ms.corridors, entrance: ms.entrance };
      }
      return null;
    },
    caveStats(n = 24) {
      const px = Math.floor(player.p.x), pz = Math.floor(player.p.z);
      let air = 0, tot = 0, mouths = 0, cols = 0;
      for (let x = px - n; x <= px + n; x += 2) for (let z = pz - n; z <= pz + n; z += 2) {
        const h = heightAt(x, z); cols++;
        if (h < CFG.WH - 2 && getBlock(x, h, z) === 0) mouths++;
        for (let y = 3; y < h - 1; y++) { tot++; if (getBlock(x, y, z) === 0) air++; }
      }
      return { caveAirFrac: +(air / Math.max(1, tot)).toFixed(3), surfaceHoles: mouths, columns: cols };
    },
    chunkBuildMs() {
      const c = getChunk(Math.floor(player.p.x / CFG.CH) + 3, Math.floor(player.p.z / CFG.CH));
      const t0 = performance.now(); buildChunk(c); return +(performance.now() - t0).toFixed(1);
    },
    mobKinds: () => { const o = {}; for (const m of mobs) if (!m.dying) o[m.kind] = (o[m.kind] || 0) + 1; return o; },
    spawnAt: (kind, dx, dz) => { const x = Math.floor(player.p.x + dx), z = Math.floor(player.p.z + dz); const m = spawnMobAt(kind, x, surfaceY(x, z) + 1, z); return m ? [kind, +m.p.x.toFixed(1), +m.p.y.toFixed(1)] : null; },
    villages: (r = 2) => {
      const pcx = Math.floor(player.p.x / VS_CELL), pcz = Math.floor(player.p.z / VS_CELL);
      const out = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const v = villageFor(pcx + dx, pcz + dz);
        if (v) out.push({ cx: v.cx, cz: v.cz, gy: v.gy, houses: v.houses, ops: v.ops,
          kinds: (v.builds || []).map(b => b.name), at: (v.builds || []).map(b => [b.name, b.x, b.z]) });
      }
      return out;
    },
    skin: (dataUrl) => {                       // 验收用：把一张 64×64 的 data URL 皮肤套上去
      return new Promise((res) => {
        const img = new Image();
        img.onload = () => {
          if (img.width !== 64 || img.height !== 64) { res({ ok: false, w: img.width, h: img.height }); return; }
          skinCustom = img; LOOK.skinSrc = 'custom'; skinTexCache.delete('custom'); skinOverlayCache.clear();
          try { localStorage.setItem(SKIN_PNG_KEY, String(dataUrl)); } catch (e) {}
          saveLook(); refreshLookAv(); drawSkinThumb(); rebuildArms();
          res({ ok: true, w: 64, h: 64 });
        };
        img.onerror = () => res({ ok: false, err: 'decode' });
        img.src = dataUrl;
      });
    },
    skinInfo: () => ({ src: LOOK.skinSrc, hasPng: !!skinCustom, key: skinHash(LOOK.skinSrc) }),
    aimAt: (x, y, z) => {                     // 把镜头对准某个世界坐标（自动求 yaw/pitch）
      const eyeY = player.p.y + CFG.EYE;
      const dx = x - player.p.x, dy = y - eyeY, dz = z - player.p.z;
      const horiz = Math.hypot(dx, dz) || 0.001;
      const wantYaw = Math.atan2(-dx, -dz);
      const wantPitch = Math.atan2(dy, horiz);
      player.yaw = wantYaw; player.pitch = wantPitch;
      const v = new THREE.Vector3(); v.set(0, 0, -1).applyEuler(new THREE.Euler(wantPitch, wantYaw, 0, 'YXZ'));
      return { yaw: +wantYaw.toFixed(2), pitch: +wantPitch.toFixed(2), fwd: [+v.x.toFixed(2), +v.y.toFixed(2), +v.z.toFixed(2)], dist: +horiz.toFixed(1) };
    },
    spawnAvatar: () => {                       // 验收：在玩家前方 4 格放一个皮肤人形（主场景）
      const A = buildSkinAvatar({ skinSrc: LOOK.skinSrc });
      const fy = Math.floor(player.p.y);
      const dx = -Math.sin(player.yaw) * 4, dz = -Math.cos(player.yaw) * 4;
      A.g.position.set(player.p.x + dx, fy + 1, player.p.z + dz);
      A.g.rotation.y = player.yaw;
      scene.add(A.g);
      return { at: [+A.g.position.x.toFixed(1), A.g.position.y, +A.g.position.z.toFixed(1)], kids: A.g.children.length, meshes: (() => { let n = 0; A.g.traverse(o => { if (o.isMesh) n++; }); return n; })() };
    },
    avatarProbe: () => {
      try {
        const A = buildSkinAvatar({ skinSrc: LOOK.skinSrc });
        let meshes = 0, mats = 0, mapOk = 0;
        A.g.traverse(o => {
          if (o.isMesh) {
            meshes++;
            const ms = Array.isArray(o.material) ? o.material : [o.material];
            mats += ms.length;
            ms.forEach(m => { if (m.map && m.map.image && m.map.image.width === 64) mapOk++; });
          }
        });
        return { kids: A.g.children.length, meshes, mats, mapOk };
      } catch (e) { return { err: String((e && e.stack) || e) }; }
    },
    abyss: (r = 3) => {                         // 附近的深渊迷宫（每座 10% 挂在村庄下面）
      const cx = Math.floor(player.p.x / ABYSS_CELL), cz = Math.floor(player.p.z / ABYSS_CELL);
      const out = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const a = abyssFor(cx + dx, cz + dz);
        if (!a) continue;
        out.push({ x: a.cx, z: a.cz, y0: a.y0, rooms: a.rooms, ops: a.ops,
          hall: a.hall, shaft: a.shaft, dist: Math.round(Math.hypot(a.cx - player.p.x, a.cz - player.p.z)) });
      }
      out.sort((p, q) => p.dist - q.dist);
      return out.slice(0, 6);
    },
    gotoAbyss(mode) {                           // 'hall' Altar hall / 'shaft' 地表井口
      const list = this.abyss(6);
      const a = list[0];
      if (!a) { toast('No Abyss Maze within 3 village cells nearby', 2.6); return null; }
      const cx = Math.floor(a.x / CFG.CH), cz = Math.floor(a.z / CFG.CH);
      for (let i = -2; i <= 2; i++) for (let j = -2; j <= 2; j++) buildChunk(getChunk(cx + i, cz + j));
      if (mode === 'shaft') player.p.set(a.shaft.x + 0.5, a.shaft.y + 1.2, a.shaft.z + 0.5);
      else player.p.set(a.hall.x + 0.5, a.hall.y + 1.2, a.hall.z + 5.5);
      player.v.set(0, 0, 0);
      camSmoothY = null;
      return a;
    },
    forests: (r = 2) => {                       // 附近有哪些森林（名字/半径/距离）
      const out = [];
      const cx = Math.floor(player.p.x / FOREST_CELL), cz = Math.floor(player.p.z / FOREST_CELL);
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const f = forestFor(cx + dx, cz + dz);
        if (f) out.push({ name: f.name, kind: f.kind, x: f.x, z: f.z, r: f.r, dist: Math.round(Math.hypot(f.x - player.p.x, f.z - player.p.z)) });
      }
      return out.sort((a, b) => a.dist - b.dist);
    },
    gotoForest: (kind) => {                     // 传送到指定种类的森林中心附近
      const cx = Math.floor(player.p.x / FOREST_CELL), cz = Math.floor(player.p.z / FOREST_CELL);
      for (let r = 0; r <= 6; r++) for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const f = forestFor(cx + dx, cz + dz);
        if (!f || (kind && f.kind !== kind)) continue;
        let px2 = f.x + 6, pz2 = f.z + 6;
        if (heightAt(px2, pz2) <= CFG.SEA + 2) {          // 别把玩家扔到海里：往圈内找一块陆地
          let found = false;
          for (let rr = 0; rr < f.r && !found; rr += 8) {
            for (let a = 0; a < 12 && !found; a++) {
              const tx = Math.round(f.x + Math.cos(a * 0.52) * rr), tz = Math.round(f.z + Math.sin(a * 0.52) * rr);
              if (heightAt(tx, tz) > CFG.SEA + 3) { px2 = tx; pz2 = tz; found = true; }
            }
          }
        }
        player.p.set(px2 + 0.5, heightAt(px2, pz2) + 10, pz2 + 0.5);
        player.v.set(0, 0, 0);
        camSmoothY = null;
        return { name: f.name, kind: f.kind, at: [px2, pz2], r: f.r, y: heightAt(px2, pz2) + 16 };
      }
      return null;
    },
    treeStats: (n = 300) => {                   // 抽样看树冠：叶子数 min/avg/max + 树种分布
      const kinds = {}, leaves = [];
      const x0 = Math.floor(player.p.x), z0 = Math.floor(player.p.z);
      for (let i = 0; i < n; i++) {
        const wx = x0 + ((i * 37) % 200) - 100, wz = z0 + ((i * 71) % 200) - 100;
        const t = treeParams(wx, wz);
        if (!t) continue;
        kinds[t.kind] = (kinds[t.kind] || 0) + 1;
        // 数一下这棵树的叶子块数（同一套几何，不含其它方块）
        let cnt = 0;
        const save = [];
        const counter = (lx2, y, lz2) => { cnt++; };
        putTree((lx2, y, lz2, id, air) => { if (id === t.leaf) cnt++; }, 0, 0, wx, wz, t);
        leaves.push(cnt);
      }
      leaves.sort((a, b) => a - b);
      return { trees: leaves.length, kinds, min: leaves[0] || 0, p10: leaves[Math.floor(leaves.length * 0.1)] || 0,
        avg: Math.round(leaves.reduce((a, b) => a + b, 0) / Math.max(1, leaves.length)), max: leaves[leaves.length - 1] || 0 };
    },
    terrainStats: (n = 400) => {                // 地形高度分布（用来校准树的生成高度上限）
      const hs = [];
      const x0 = Math.floor(player.p.x), z0 = Math.floor(player.p.z);
      for (let i = 0; i < n; i++) {
        const wx = x0 + ((i * 37) % 400) - 200, wz = z0 + ((i * 71) % 400) - 200;
        hs.push(heightAt(wx, wz));
      }
      hs.sort((a, b) => a - b);
      return { min: hs[0], p10: hs[(hs.length * 0.1) | 0], med: hs[(hs.length * 0.5) | 0],
        p90: hs[(hs.length * 0.9) | 0], max: hs[hs.length - 1], SEA: CFG.SEA, WH: CFG.WH };
    },
    treeDebug: (wx, wz) => {                     // 单点：为什么这里没有树
      const F = forestAt(wx, wz);
      const g = heightAt(wx, wz);
      const steps = {
        village: inVillage(wx, wz), haunted: inHaunted(wx, wz),
        extra: inExtraStruct(wx, wz), ravine: inRavine(wx, wz),
        g, tooLow: g <= CFG.SEA + 1, tooHigh: g >= MOUNT_Y,
        cave: caveCarve(wx, g, wz, g), forest: F ? F.kind : null,
        gate: h2(wx * 3.77 + 13.1, wz * 2.91 - 7.7),
      };
      steps.params = treeParams(wx, wz);
      return steps;
    },
    gotoVillage: () => {
      const v = nearestVillage(400);
      if (!v) return null;
      player.p.set(v.cx + 0.5, v.gy + 2, v.cz + 0.5);
      player.v.set(0, 0, 0);
      camSmoothY = null;
      return v;
    },
    chestAt: (x, y, z) => openChest(x, y, z),
    /* ★ v368：扫种子用的「出生点 → 最近陨石坑」精确版（含 structNear 的 48 格互斥）。
       纯 node 脚本没有复制其它 11 种结构的门槛，所以候选会被村庄/塔挤掉 —— 这个是在引擎里跑的，
       结果就是最终结果。用完会把 SEED 和所有结构缓存复原。 */
    seedMeteor: (seed) => {
      const oldSeed = SEED;
      const caches = [hsCache, villageCache, veinCache, ravineCache, towerCache, wellCache, circleCache,
                      campCache, portalCache, ruinsCache, arenaCache, pyrCache, mtCache, forestCache, lsCache, msCache];
      const clearAll = () => { for (const m of caches) if (m && m.clear) m.clear(); };
      SEED = seed | 0;
      clearAll();
      const sp = findSpawn();
      const ccx = Math.floor(sp.x / MT_CELL), ccz = Math.floor(sp.z / MT_CELL);
      let best = null;
      for (let dx = -2; dx <= 2; dx++) for (let dz = -2; dz <= 2; dz++) {
        const o = mtFor(ccx + dx, ccz + dz);
        if (!o) continue;
        const d = Math.round(Math.hypot(sp.x - o.cx, sp.z - o.cz));
        if (!best || d < best.dist) {
          /* 视线：从出生点眼高看到坑唇（gy+2），中间地形不得高于这条线 */
          let vis = true;
          const eye = sp.h + 2, top = o.gy + 2;
          for (let i = 1; i < 18 && vis; i++) {
            const t = i / 18;
            const hx = Math.round(sp.x + (o.cx - sp.x) * t), hz = Math.round(sp.z + (o.cz - sp.z) * t);
            if (heightAt(hx, hz) > eye + (top - eye) * t - 1) vis = false;
          }
          best = { dist: d, cx: o.cx, cz: o.cz, gy: o.gy, ry: o.ry, ops: o.ops, visible: vis };
        }
      }
      SEED = oldSeed;
      clearAll();
      return best ? { seed: seed | 0, spawn: [sp.x, sp.z, sp.h], ...best } : { seed: seed | 0, spawn: [sp.x, sp.z, sp.h], dist: -1 };
    },
    seedMeteorScan: (from, to, maxD = 90) => {
      const out = [];
      for (let s = from; s <= to; s++) {
        const r = GAME.debug.seedMeteor(s);
        if (r && r.dist >= 0 && r.dist <= maxD) out.push(r);
      }
      out.sort((a, b) => a.dist - b.dist);
      return out.slice(0, 8);
    },
    seedHouse: (seed) => {              // 扫种子：出生点 → 最近鬼屋
      SEED = seed | 0;
      hsCache.clear(); villageCache.clear(); veinCache.clear();
      if (typeof ravineCache !== 'undefined' && ravineCache.clear) ravineCache.clear();
      const sp = findSpawn();
      const cx = Math.floor(sp.x / HS_CELL), cz = Math.floor(sp.z / HS_CELL);
      let best = null;
      for (let dx = -2; dx <= 2; dx++) for (let dz = -2; dz <= 2; dz++) {
        const hs = hauntedFor(cx + dx, cz + dz);
        if (!hs) continue;
        const d = Math.round(Math.hypot(sp.x - hs.cx, sp.z - hs.cz));
        if (!best || d < best.d) best = { d, hx: hs.cx, hz: hs.cz, y0: hs.y0, floors: hs.floors };
      }
      return { seed: SEED, spawn: sp, house: best };
    },
    structs: (r = 3) => {
      const px = player.p.x, pz = player.p.z, out = [];
      for (const t of STRUCT_TYPES) {
        const cx = Math.floor(px / t.cell), cz = Math.floor(pz / t.cell);
        for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
          const o = t.get(cx + dx, cz + dz);
          if (o) out.push({ type: t.name, label: o.label || t.name, cx: o.cx, cz: o.cz, gy: o.gy, ops: o.ops, dist: Math.round(Math.hypot(o.cx - px, o.cz - pz)) });
        }
      }
      return out.sort((a, b) => a.dist - b.dist);
    },
    ruinsDbg: () => arDbg,
    /* 宝珠守护地探针 */
    arena: (r = 2) => {
      const pcx = Math.floor(player.p.x / ARENA_CELL), pcz = Math.floor(player.p.z / ARENA_CELL);
      const out = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const o = arenaFor(pcx + dx, pcz + dz);
        if (!o) continue;
        out.push({ cx: o.cx, cz: o.cz, gy: o.gy, ops: o.ops, dist: Math.round(Math.hypot(o.cx - player.p.x, o.cz - player.p.z)),
          altar: getBlock(o.cx, o.gy + 3, o.cz), floor: getBlock(o.cx + 3, o.gy + 1, o.cz) });
      }
      return out.sort((a, b) => a.dist - b.dist);
    },
    arenaState: () => ({ active: ARENA.active, wave: ARENA.wave, cool: +ARENA.cool.toFixed(1), mobs: arenaMobs().map(m => m.kind), lost: ARENA.lost, won: ARENA.won, r: ARENA.r, center: [ARENA.cx, ARENA.cy, ARENA.cz] }),
    gotoArena: () => {
      const pcx = Math.floor(player.p.x / ARENA_CELL), pcz = Math.floor(player.p.z / ARENA_CELL);
      let best = null;
      for (let r = 0; r <= 6; r++) for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
        const o = arenaFor(pcx + dx, pcz + dz);
        if (!o) continue;
        const d = Math.hypot(o.cx - player.p.x, o.cz - player.p.z);
        if (!best || d < best.d) best = { o, d };
      }
      if (!best) return null;
      const o = best.o, ccx = Math.floor(o.cx / CFG.CH), ccz = Math.floor(o.cz / CFG.CH);
      for (let a = -3; a <= 3; a++) for (let b = -3; b <= 3; b++) buildChunk(getChunk(ccx + a, ccz + b));
      player.p.set(o.cx + 0.5, o.gy + 3, o.cz + 9.5);
      player.v.set(0, 0, 0);
      toast(`Orb Sanctum: (${o.cx}, ${o.cz}) central orb pedestal y=${o.gy + 3}`, 3.2);
      return { cx: o.cx, cz: o.cz, gy: o.gy, ops: o.ops };
    },
    trialStart: (altar) => {                    // 传 {x,y,z} = 直接在该祭坛开试炼（深渊/宝珠台都能用）
      if (altar) return trialStart(altar);
      const pcx = Math.floor(player.p.x / ARENA_CELL), pcz = Math.floor(player.p.z / ARENA_CELL);
      for (let r = 0; r <= 2; r++) for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const o = arenaFor(pcx + dx, pcz + dz);
        if (o && Math.abs(o.cx - player.p.x) < 40 && Math.abs(o.cz - player.p.z) < 40) return trialStart({ x: o.cx, y: o.gy + 3, z: o.cz });
      }
      return false;
    },
    /* 远古废墟探针：列出附近废墟，并给出发电机/激活器的世界坐标（验收用） */
    ruins: (r = 2) => {
      const pcx = Math.floor(player.p.x / AR_CELL), pcz = Math.floor(player.p.z / AR_CELL);
      const out = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const o = ruinsFor(pcx + dx, pcz + dz);
        if (!o) continue;
        out.push({
          cx: o.cx, cz: o.cz, gy: o.gy, ops: o.ops, dist: Math.round(Math.hypot(o.cx - player.p.x, o.cz - player.p.z)),
          frameY: o.gy + 3, activators: [[9, 0, 1], [0, 9, 2], [-9, 0, 3], [0, -9, 4]]
            .map(([ax, az, m]) => ({ x: o.cx + ax, y: o.gy + 4, z: o.cz + az, orb: AR_ORBS[m - 1], block: getBlock(o.cx + ax, o.gy + 4, o.cz + az) })),
          frame: [getBlock(o.cx - 2, o.gy + 3, o.cz), getBlock(o.cx + 2, o.gy + 3, o.cz), getBlock(o.cx, o.gy + 3, o.cz - 2)],
        });
      }
      return out.sort((a, b) => a.dist - b.dist);
    },
    /* 激活器测试钩子：直接触发一次「对着激活器右键」（不加这个就没法验收，因为要 raycast） */
    activator: (x, y, z) => {
      const t = { x, y, z, id: getBlock(x, y, z) };
      if (!BLOCKS[t.id] || !BLOCKS[t.id].activator) return { ok: false, block: t.id, name: nameOf(t.id) };
      return { ok: useActivator(t), block: t.id, meta: getMeta(x, y, z) };
    },
    gotoStruct: (type) => {
      const t = STRUCT_TYPES.find(x => x.name === type);
      if (!t) return null;
      const cx = Math.floor(player.p.x / t.cell), cz = Math.floor(player.p.z / t.cell);
      for (let r = 0; r <= 4; r++) for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const o = t.get(cx + dx, cz + dz);
        if (!o) continue;
        player.p.set(o.cx + 0.5, (o.gy || 40) + 2, o.cz + 12.5);
        player.v.set(0, 0, 0);
        const ccx = Math.floor(o.cx / CFG.CH), ccz = Math.floor(o.cz / CFG.CH);
        for (let a = -2; a <= 2; a++) for (let bb = -2; bb <= 2; bb++) buildChunk(getChunk(ccx + a, ccz + bb));
        return { type: t.name, cx: o.cx, cz: o.cz, gy: o.gy, ops: o.ops };
      }
      return null;
    },
    haunted: (r = 2) => {
      const pcx = Math.floor(player.p.x / HS_CELL), pcz = Math.floor(player.p.z / HS_CELL);
      const out = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const hs = hauntedFor(pcx + dx, pcz + dz);
        if (hs) out.push({ cx: hs.cx, cz: hs.cz, y0: hs.y0, floors: hs.floors, ops: hs.ops });
      }
      return out;
    },
    gotoHaunted: () => {
      const pcx = Math.floor(player.p.x / HS_CELL), pcz = Math.floor(player.p.z / HS_CELL);
      for (let rr = 0; rr <= 3; rr++) for (let dx = -rr; dx <= rr; dx++) for (let dz = -rr; dz <= rr; dz++) {
        const hs = hauntedFor(pcx + dx, pcz + dz);
        if (!hs) continue;
        player.p.set(hs.cx + 0.5, hs.y0 + 2, hs.cz + hs.D + 6.5);
        player.v.set(0, 0, 0); camSmoothY = null;
        const ccx = Math.floor(hs.cx / CFG.CH), ccz = Math.floor(hs.cz / CFG.CH);
        for (let a = -2; a <= 2; a++) for (let b = -2; b <= 2; b++) buildChunk(getChunk(ccx + a, ccz + b));
        return { cx: hs.cx, cz: hs.cz, y0: hs.y0, floors: hs.floors };
      }
      return null;
    },
    ravines: (r = 2) => {
      const pcx = Math.floor(player.p.x / RV_CELL), pcz = Math.floor(player.p.z / RV_CELL);
      const out = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const rv = ravineFor(pcx + dx, pcz + dz);
        if (rv) out.push({ x0: rv.minX, x1: rv.maxX, z0: rv.minZ, z1: rv.maxZ, pts: rv.n, water: rv.water,
                           depth: Math.round(rv.points.reduce((a, p) => a + (p.top - p.bot), 0) / rv.n) });
      }
      return out;
    },
    gotoRavine: () => {
      const pcx = Math.floor(player.p.x / RV_CELL), pcz = Math.floor(player.p.z / RV_CELL);
      for (let rr = 0; rr <= 3; rr++) for (let dx = -rr; dx <= rr; dx++) for (let dz = -rr; dz <= rr; dz++) {
        const rv = ravineFor(pcx + dx, pcz + dz);
        if (!rv) continue;
        const pt = rv.points[Math.floor(rv.n / 2)];
        player.p.set(pt.x + 4.5, pt.top + 2, pt.z + 0.5); player.v.set(0, 0, 0); camSmoothY = null;
        const ccx = Math.floor(pt.x / CFG.CH), ccz = Math.floor(pt.z / CFG.CH);
        for (let a = -1; a <= 1; a++) for (let bb = -1; bb <= 1; bb++) buildChunk(getChunk(ccx + a, ccz + bb));
        return { x: pt.x, z: pt.z, top: pt.top, bot: pt.bot, w: pt.w, water: rv.water, span: pt.top - pt.bot };
      }
      return null;
    },
    water: (x, y, z, lvl) => { if (lvl === undefined) { setBlock(x, y, z, 5); } else setWater(x, y, z, lvl); wakeWater(x, y, z); },
    benchChunk: (n, ddx, ddz) => {
      const pcx = Math.floor(player.p.x / CFG.CH) + (ddx || 8), pcz = Math.floor(player.p.z / CFG.CH) + (ddz || 0);
      const t = [];
      for (let i = 0; i < (n || 5); i++) {
        const c = getChunk(pcx + i, pcz);
        const t0 = performance.now();
        buildChunk(c);
        t.push(+(performance.now() - t0).toFixed(1));
      }
      return t;
    },
    dirtySize: () => dirty.size,
    /* ★ v368 陨石坑验收出口 */
    meteorFind: (r = 1) => {
      const pcx = Math.floor(player.p.x / MT_CELL), pcz = Math.floor(player.p.z / MT_CELL), out = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const o = mtFor(pcx + dx, pcz + dz);
        if (o) out.push({ cx: o.cx, cz: o.cz, gy: o.gy, ry: o.ry, ops: o.ops,
                          sensors: o.sensors.length, chests: o.chests.length,
                          dist: Math.round(Math.hypot(o.cx - player.p.x, o.cz - player.p.z)) });
      }
      return out.sort((a, b) => a.dist - b.dist);
    },
    meteorGo: () => {
      const r0 = GAME.debug.meteorFind(2);
      const list = r0.found || r0;
      if (!list.length) return null;
      const t = list[0];
      const o = mtFor(Math.floor(t.cx / MT_CELL), Math.floor(t.cz / MT_CELL));
      const cx = Math.floor(o.altar.x / CFG.CH), cz = Math.floor(o.altar.z / CFG.CH);
      for (let ddx = -1; ddx <= 1; ddx++) for (let ddz = -1; ddz <= 1; ddz++) buildChunk(getChunk(cx + ddx, cz + ddz));
      player.p.set(o.altar.x + 0.5, o.altar.y + 1.05, o.altar.z + 6.5);
      player.v.set(0, 0, 0); camSmoothY = null;
      return { at: [o.altar.x, o.altar.y, o.altar.z], ry: o.ry, sensors: o.sensors.length };
    },
    /* ★ v372 验收口：脚步噪声 / 红波动 / 补刷 */
    mtStepTest: (n = 20) => {
      const before = mtNoise.length;
      player.v.x = CFG.WALK; player.v.z = 0; player.onGround = true;
      for (let i = 0; i < n; i++) mtFootstep(0.05);
      return { noiseBefore: before, noiseAfter: mtNoise.length, near: mtNearAnyCrater() };
    },
    mtRipples: () => mtRipples.length,
    pid: () => (typeof NET !== 'undefined' && NET ? NET.id : null),
    mtRemoteDbg: () => ({ size: mtRemoteAcc.size, isHost: !!(typeof NET !== 'undefined' && NET && NET.isHost),
                          entries: Array.from(mtRemoteAcc.entries()).slice(0, 3) }),
    mtRippleDemo: (dur = 6) => {                       // 截图用：放一个慢速红波
      const ccx = Math.floor(player.p.x / MT_CELL), ccz = Math.floor(player.p.z / MT_CELL);
      for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) {
        const o = mtCache.get((ccx + dx) + ',' + (ccz + dz));
        if (!o) continue;
        const sp = o.sensors[0];
        mtRippleTo(sp[0], sp[1], sp[2], dur);
        return { dur, from: [+player.p.x.toFixed(1), +player.p.y.toFixed(1), +player.p.z.toFixed(1)], to: sp };
      }
      return null;
    },
    mtRespawnNow: () => { mtRespawnAcc = 99; meteorTick(0.016); return mobs.filter(m => m.kind === MT_STALKER).length; },
    meteorState: () => {
      const o = mtFor(Math.floor(player.p.x / MT_CELL), Math.floor(player.p.z / MT_CELL));
      if (!o) return null;
      const st = mtStateFor(mtKeyOf(o));
      let alive = 0;
      for (const sp of o.sensors) if (peekBlock(sp[0], sp[1], sp[2]) === MT_SENSOR) alive++;
      const m = mobs.find(x => x.kind === MT_STALKER && !x.dying);
      const g = (!m && NET && NET.active && NET.ghosts) ? Array.from(NET.ghosts.values()).find(x => x.kind === MT_STALKER) : null;
      return { key: mtKeyOf(o), warn: st.warn, summoned: st.summoned, sensors: o.sensors.length,
               sensorsAlive: alive,
               stalker: m ? { hp: Math.round(m.hp), seen: !!m.seen, ghost: false,
                              dist: Math.round(Math.hypot(m.p.x - player.p.x, m.p.z - player.p.z)) }
                        : (g ? { hp: g.hp, seen: !!g.seen, ghost: true,
                                 dist: Math.round(Math.hypot(g.p.x - player.p.x, g.p.z - player.p.z)) } : null) };
    },
    meteorNoise: (n = 1) => {
      const o = mtFor(Math.floor(player.p.x / MT_CELL), Math.floor(player.p.z / MT_CELL));
      if (!o) return null;
      const sp = o.sensors.find(x => peekBlock(x[0], x[1], x[2]) === MT_SENSOR) || o.sensors[0];
      for (let i = 0; i < n; i++) { mtStateFor(mtKeyOf(o)).cd = 0; mtNoteNoise(sp[0], sp[1], sp[2]); meteorTick(typeof dt === 'number' ? dt : 0.016); }
      return GAME.debug.meteorState();
    },
    meteorSummon: () => {
      const o = mtFor(Math.floor(player.p.x / MT_CELL), Math.floor(player.p.z / MT_CELL));
      if (!o) return null;
      const st = mtStateFor(mtKeyOf(o));
      st.summoned = true; st.warn = MT_WARN_MAX;
      return !!mtSummon(o, mtKeyOf(o));
    },
    /* ★ v367 木质分组 / 加工器 / 燃料 验收出口 */
    ing: () => ({ planks: PLANK_IDS.map(k => [nameOf(k), countOf(k)]), plankTotal: ingCount(ANY_PLANK),
                  logs: LOG_IDS.map(k => [nameOf(k), countOf(k)]), logTotal: ingCount(ANY_LOG),
                  chips: countOf(170), sticks: countOf(104) }),
    processorChips: (n = 1) => chipBatch(n),
    processorSticks: (n = 1) => stickBatch(n),
    fuelList: () => FUEL_DEFS.map(f => ({ name: f.name, units: f.units, time: f.time, have: ingCount(f.id) })),
    smeltByInput: (inId) => { const r = SMELT.find(x => x.in === inId); return r ? smelt(r) : false; },
    furnaceJobInfo: () => furnaceJob ? { out: nameOf(furnaceJob.r.out), left: furnaceJob.left, fuel: furnaceJob.fuelName, dur: +jobDur(furnaceJob).toFixed(2), t: +furnaceJob.t.toFixed(2) } : null,
    meshStats: () => meshRate(),
    meshStatsReset: () => { meshRateReset(); return meshRate(); },
    cosCoalesce: (ms) => { if (typeof ms === 'number') COS_COALESCE = Math.max(0, ms | 0); return COS_COALESCE; },
    chunkOf: (x, z) => { const c = chunks.get((x >> 4) + ',' + (z >> 4)); return c ? { ready: c.ready, job: !!c.job, jobY: c.job ? c.job.y : null, verts: c.mesh ? c.mesh.geometry.attributes.position.count : 0, inDirty: dirty.has(c) } : null; },
    streamOnce: () => { const t = performance.now(); streamChunks(); return +(performance.now() - t).toFixed(2); },
    meshState: () => ({ jobs: [...chunks.values()].filter(c => c.job).length, ready: [...chunks.values()].filter(c => c.ready).length, chunks: chunks.size }),
    perf: () => ({
      frameMs: +frameMsAvg.toFixed(1), budgetMs: +perfBudget.toFixed(1),
      stale: [...chunks.values()].filter(c => c.stale).length,
      ready: [...chunks.values()].filter(c => c.ready).length,
      chunks: chunks.size, edits: edits.size,
      waterQueued: waterQueue.length - waterHead, flowing: waterFlow.size,
      mobs: mobs.length, drops: drops.length, arrows: arrows.length,
      torch: torchCells.size, genMeta: genMeta.size, doorObjs: doorObjs.size,
      guard: structGuard.size, chestInv: chestInv.size, mmCells: MM.cells.size,
      caches: msCache.size + ravineCache.size + veinCache.size + lsCache.size + hsCache.size + villageCache.size,
      scene: scene.children.length,
      geoms: renderer.info.memory.geometries, textures: renderer.info.memory.textures,
      calls: renderer.info.render.calls, tris: renderer.info.render.triangles,
      heapMB: performance.memory ? +(performance.memory.usedJSHeapSize / 1048576).toFixed(1) : null,
    }),
    prof: () => ({ frames: PROF.frames, steps: PROF.steps, secs: +((performance.now() - PROF.from) / 1000).toFixed(1), ...profFrame(), ...profText() }),
    profReset: () => { profReset(); return true; },
    waterInfo: () => ({ flowing: waterFlow.size, queued: waterQueue.length - waterHead }),
    cfg: () => ({ sens: userCfg.sens, touchUI: userCfg.touchUI, keys: { ...keymap } }),
    setKey: (act, code) => { if (!DEFAULT_KEYS[act]) return false; keymap[act] = code; saveCfg(); renderKeyRows(); return true; },
    press: (code) => { keys.add(code); return true; },
    release: (code) => { keys.delete(code); if (code === keymap.mine) mineHeld = false; },
    useHeld: () => {                            // 等价于右键（探针用，绕开 pointer lock）
      const h = held(), t = raycastVoxel(eyePos(), cameraDir(), CFG.REACH);
      if (h && h.id === 153) return firePlayerArrow();
      if (h && h.id === 161) return useBoneMeal(t);
      if (h && ITEMS[h.id] && ITEMS[h.id].kind === 'hoe') return useHoe(t);
      if (h && h.id === 156) return plantSeed(t);
      if (h && h.id === 157) return useFertilizer(t);
      if (h && t && BLOCKS[t.id] && BLOCKS[t.id].compost) return useCompost(t);
      if (h && h.id === 152) return useBucket(true, t);
      if (h && h.id === 151) return useBucket(false, t);
      return null;
    },
    waterLevel: (x, y, z) => flowLvl(x, y, z),
    waterTop: (x, y, z) => waterTopH(x, y, z),
    /* 水面「看得穿的竖缝」验收（v351）：
       相邻两格都是水、但水面高度不同时，水与水之间不画内面 → 那道 0.14~0.58 高的竖面
       （riser）是**空的**，从低角度看就是一圈能看穿的水环。这里数出这种开口。
       返回 { cells, risers, byDelta } —— risers 是「高度差>0.02 且没有竖面」的相邻对。 */
    waterGapProbe(r = 12) {
      const px = Math.floor(player.p.x), pz = Math.floor(player.p.z);
      const out = { cells: 0, risers: 0, byDelta: {}, samples: [], holes: 0 };
      for (let x = px - r; x <= px + r; x++) for (let z = pz - r; z <= pz + r; z++) for (let y = 1; y < CFG.WH; y++) {
        if (getBlock(x, y, z) !== 5) continue;
        out.cells++;
        const own = waterTopH(x, y, z);
        // 水柱内部（上方也是水）不算
        if (getBlock(x, y + 1, z) === 5) continue;
        for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          if (getBlock(x + dx, y, z + dz) !== 5) continue;
          const nt = waterTopH(x + dx, y, z + dz);
          const d = Math.abs(nt - own);
          if (d < 0.02) continue;
          out.risers++;
          const k = d.toFixed(2);
          out.byDelta[k] = (out.byDelta[k] || 0) + 1;
          if (out.samples.length < 5) out.samples.push({ x, y, z, own: +own.toFixed(2), nb: +nt.toFixed(2), lvl: flowLvl(x, y, z), nbl: flowLvl(x + dx, y, z + dz) });
        }
      }
      return out;
    },
    scrub: () => { scrubWaterNear(9); return true; },
    waterCells: (r = 6) => {
      const px = Math.floor(player.p.x), py = Math.floor(player.p.y), pz = Math.floor(player.p.z);
      let n = 0, list = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) for (let y = py - r; y <= py + r; y++) {
        if (getBlock(px + dx, y, pz + dz) === 5) { n++; if (list.length < 6) list.push([px + dx, y, pz + dz]); }
      }
      return { count: n, list };
    },
    stepWater: (n = 40) => { for (let i = 0; i < n; i++) updateWater(96); return waterFlow.size; },
    drops: () => drops.map(d => ({ id: d.id, name: nameOf(d.id), n: d.n, t: +d.t.toFixed(2), y: +d.p.y.toFixed(2), dist: +d.p.distanceTo(player.p).toFixed(2) })),
    map: () => ({ cells: MM.cells.size, marks: MM.marks.size, zoom: MM.zoom, acrossCells: MM_ZOOM[MM.zoom], acrossBlocks: MM_ZOOM[MM.zoom] * MM_CELL,
                  info: MM.info ? MM.info.textContent : null, visible: MM.wrap ? MM.wrap.style.display !== 'none' : null,
                  markList: Array.from(MM.marks.values()) }),
    mapZoom: (d) => { mmZoom(d || 0); mmDraw(); return { zoom: MM.zoom, acrossBlocks: MM_ZOOM[MM.zoom] * MM_CELL }; },
    mapReveal: () => { mmReveal(); mmDraw(); return { cells: MM.cells.size }; },
    mapScan: () => { mmScanStructs(); mmDraw(); return { marks: MM.marks.size, list: Array.from(MM.marks.values()) }; },
    mapClear: () => { MM.cells.clear(); MM.marks.clear(); mmDraw(); return true; },
    villagerAI: () => mobs.filter(m => m.kind === 'villager').map(m => ({
      pos: [+m.p.x.toFixed(1), +m.p.y.toFixed(1), +m.p.z.toFixed(1)],
      state: m.ai ? m.ai.state : null, sleeping: !!m.sleeping,
      bed: m.bed ? [m.bed.x, m.bed.y, m.bed.z] : null,
      door: m.ai && m.ai.door ? [m.ai.door.x, m.ai.door.y, m.ai.door.z] : null,
      doorOpen: m.ai && m.ai.door ? !!((getMeta(m.ai.door.x, m.ai.door.y, m.ai.door.z)) & 4) : null,
      give: m.give ? nameOf(m.give.id) : null, jumps: m.jumps || 0,
      stuckT: m.ai ? +(m.ai.stuckT || 0).toFixed(1) : 0,
      giftScale: m.gift ? +m.gift.scale.x.toFixed(2) : null,
      giftY: m.gift ? +m.gift.position.y.toFixed(2) : null,
    })),
    mobJumps: () => mobs.map(m => ({ kind: m.kind, jumps: m.jumps || 0, vy: +m.v.y.toFixed(2), onGround: !!m.onGround })),
    heldTorch: () => ({ on: heldTorchLight.visible, pos: heldTorchLight.position.toArray().map(v => +v.toFixed(1)), intensity: +heldTorchLight.intensity.toFixed(1) }),
    giveVillager: (id) => { const v = mobs.find(m => m.kind === 'villager'); if (!v) return null; v.give = { id, n: 1 }; showVillagerGift(v); return { id, giftY: +v.gift.position.y.toFixed(2), scale: +v.gift.scale.x.toFixed(2), meshes: v.gift.children.length }; },
    mapOpenBig: (x, z) => { mmOpenBig(x, z); return { open: MM_BIG.open, zoom: MM_BIG.zoom, acrossBlocks: MM_BIGZOOM[MM_BIG.zoom] * MM_CELL, marks: MM.marks.size }; },
    mapCloseBig: () => { mmCloseBig(); return MM_BIG.open; },
    mapAddMark: (x, z, label) => { const ok = mmAddMark(x === undefined ? Math.round(MM_BIG.x) : x, z === undefined ? Math.round(MM_BIG.z) : z, label); return { ok, marks: Array.from(MM.marks.values()) }; },
    mapDelMark: (x, z) => mmDelMark('custom:' + x + ',' + z),
    mapBig: () => ({ open: MM_BIG.open, zoom: MM_BIG.zoom, acrossBlocks: MM_BIGZOOM[MM_BIG.zoom] * MM_CELL, cx: Math.round(MM_BIG.x), cz: Math.round(MM_BIG.z),
                     rows: $('mapMarks') ? $('mapMarks').children.length : -1, canvas: $('mapCv') ? [$('mapCv').width, $('mapCv').height] : null }),
    openBag: () => { openPanel(true); return $('creativeGrid').children.length; },
    cur: () => (cursor ? { id: cursor.id, name: nameOf(cursor.id), n: cursor.n } : null),
    pickCreative: (id) => { const sec = $('creativeGrid'); if (!sec) return null; const cells = sec.children; const ids = [...Object.keys(BLOCKS).map(Number), ...Object.keys(ITEMS).map(Number)].filter(i => isItem(i)); const k = ids.indexOf(+id); if (k < 0) return null; cells[k].click(); return { cursor: cursor ? { id: cursor.id, n: cursor.n } : null }; },
    invCount: () => inv.filter(Boolean).length,
    dropCursor: () => dropCursorToWorld(),
    slotShift: (i) => { slotClick(inv, i, { shiftKey: true }); return { slot: inv[i], used: inv.filter(Boolean).length }; },
    dropsInfo: () => drops.map(d => ({ id: d.id, n: d.n, p: [+d.p.x.toFixed(1), +d.p.y.toFixed(1), +d.p.z.toFixed(1)], dist: +Math.hypot(d.p.x - player.p.x, d.p.z - player.p.z).toFixed(1) })),
    mapDim: () => ({ dim: DIM, off: mmOff(), cells: MM.cells.size, marks: MM.marks.size, coords: [+(player.p.x - mmOff()).toFixed(0), +(player.p.z - mmOff()).toFixed(0)] }),
    mapPan: (dx, dz) => { MM_BIG.x += dx || 0; MM_BIG.z += dz || 0; mmBigDraw(); return { cx: Math.round(MM_BIG.x), cz: Math.round(MM_BIG.z) }; },
    mapBigZoom: (d) => { mmBigZoom(d || 0); return { zoom: MM_BIG.zoom, acrossBlocks: MM_BIGZOOM[MM_BIG.zoom] * MM_CELL }; },
    /* 洞穴底部验收：基岩顶面高度分布 + 有多少洞底是直接坐在基岩上（越少越不平） */
    bedrockProbe(n = 3000) {
      const px = Math.floor(player.p.x), pz = Math.floor(player.p.z);
      const hist = {}, openAt = {};
      let samples = 0;
      for (let k = 0; k < n; k++) {
        const x = px + Math.floor(Math.random() * 190 - 95), z = pz + Math.floor(Math.random() * 190 - 95);
        if (!chunks.has((x >> 4) + ',' + (z >> 4))) continue;
        let bedT = -1;
        for (let y = 12; y >= 0; y--) if (getBlock(x, y, z) === 51) { bedT = y; break; }
        if (bedT < 0) continue;
        samples++;
        hist[bedT] = (hist[bedT] || 0) + 1;
        if (getBlock(x, bedT + 1, z) === 0) openAt[bedT] = (openAt[bedT] || 0) + 1;
      }
      return { samples, bedrockTop: hist, openFloorOnBedrock: openAt };
    },
    /* 洞底材质验收：低处洞底铺了多少碎石/煤（按 y 分层统计） */
    rubbleProbe(n = 1800) {
      const px = Math.floor(player.p.x), pz = Math.floor(player.p.z);
      const byY = {};
      let cols = 0, floors = 0, gravel = 0, coal = 0;
      for (let k = 0; k < n; k++) {
        const x = px + Math.floor(Math.random() * 150 - 75), z = pz + Math.floor(Math.random() * 150 - 75);
        if (!chunks.has((x >> 4) + ',' + (z >> 4))) continue;
        cols++;
        for (let y = 3; y <= 13; y++) {
          if (getBlock(x, y, z) !== 0) continue;
          const below = getBlock(x, y - 1, z);
          if (below !== 3 && below !== 50 && below !== 78 && below !== 13) continue;
          if (getBlock(x, y + 1, z) !== 0) continue;
          floors++;
          const row = byY[y] || (byY[y] = { floor: 0, gravel: 0, coal: 0 });
          row.floor++;
          if (below === 78) { gravel++; row.gravel++; }
          if (below === 13) { coal++; row.coal++; }
          break;
        }
      }
      return { columns: cols, lowFloors: floors, gravel, coal,
               gravelShare: floors ? +(gravel / floors).toFixed(3) : 0, byY };
    },
    /* 悬空岩块验收（v350）：玩家周围 rad 格内找「size ≤ maxN 且不与主岩体连通」的固体分量。
       这是「石头和矿悬在半空」唯一靠谱的量化指标。
       ⚠ 别用「六面全空的单块」判悬空：碎屑是 2×2×2 / 2×2×4 的块，每块只有 3 面空，
         那个指标恒等于 0 —— v321~v349 一直是这么「验过」的，结果玩家满眼浮石。
       返回 comps（分量数）/ blocks（格数）/ byId（按方块名）/ samples（前 6 个位置）。 */
    floatProbe(rad = 24, maxN = 64) {
      const px = Math.floor(player.p.x), pz = Math.floor(player.p.z);
      const W = rad * 2 + 1, H = CFG.WH, x0 = px - rad, z0 = pz - rad;
      const at = (x, y, z) => ((y * W) + (z - z0)) * W + (x - x0);
      /* vol: 0 未加载/出界, 1 实心, 2 空气, 3 液体/植物（算「有附着」，但不报）
         —— 判「悬空」只看**四周是不是空气**：岩浆海/地下湖里贴着流体不算悬空（MC 也一样），
            否则井底岩浆层会被统计成上千个假悬空。
         ⚠ v350 第一版这里用「分量超过 maxN 就 break」提前退出，结果主岩体被切成 65 格的碎片，
           后续碎片变成新的「分量」，报出 2000+ 个假悬空。现在**全量标记**（O(体积)），不再中途退出。 */
      const vol = new Uint8Array(W * H * W);
      let loadedCols = 0;
      for (let z = z0; z < z0 + W; z++) for (let x = x0; x < x0 + W; x++) {
        if (!chunks.has((x >> 4) + ',' + (z >> 4))) continue;
        loadedCols++;
        for (let y = 0; y < H; y++) {
          const v = getBlock(x, y, z);
          const bl = BLOCKS[v];
          vol[at(x, y, z)] = !v ? 2 : (v === 5 || v === 44 || (bl && (bl.cross || bl.plant))) ? 3 : 1;
        }
      }
      const comp = new Int32Array(vol.length);          // 0 = 未访问，>0 = 分量号
      const stack = new Int32Array(vol.length);
      const comps = [0];                                // comps[id] = 体积
      const floatIds = [];
      let id = 0, main = 0;
      for (let i = 0; i < vol.length; i++) {
        if (vol[i] !== 1 || comp[i]) continue;
        id++;
        let sp = 0, n = 0, edge = false;
        stack[sp++] = i; comp[i] = id;
        while (sp > 0) {
          const j = stack[--sp]; n++;
          const y = Math.floor(j / (W * W)), r2 = j - y * W * W, z = Math.floor(r2 / W), x = r2 - z * W;
          for (let d = 0; d < 6; d++) {
            const nx = x + (d === 0 ? 1 : d === 1 ? -1 : 0);
            const ny = y + (d === 2 ? 1 : d === 3 ? -1 : 0);
            const nz = z + (d === 4 ? 1 : d === 5 ? -1 : 0);
            if (nx < 0 || nx >= W || nz < 0 || nz >= W || ny < 0 || ny >= H) { edge = true; continue; }
            const k = at(x0 + nx, ny, z0 + nz);
            if (vol[k] === 0) { edge = true; continue; }               // 未加载：当主岩体（保守）
            if (vol[k] === 3) { edge = true; continue; }               // 贴着水/岩浆/植物：不算悬空
            if (vol[k] !== 1 || comp[k]) continue;
            comp[k] = id; stack[sp++] = k;
          }
        }
        comps[id] = n;
        if (n > main) main = n;
        if (!edge && n <= maxN) floatIds.push(id);
      }
      // 统计浮空块
      let blocks = 0;
      const byId = {}, samples = [];
      const want = new Set(floatIds);
      const seenSample = new Set();
      if (floatIds.length) for (let i = 0; i < vol.length; i++) {
        const c = comp[i];
        if (!c || !want.has(c)) continue;
        blocks++;
        const y = Math.floor(i / (W * W)), r2 = i - y * W * W, z = Math.floor(r2 / W), x = r2 - z * W;
        const bx = x0 + x, bz = z0 + z, bid = getBlock(bx, y, bz);
        const nm = (BLOCKS[bid] && BLOCKS[bid].name) || ('id' + bid);
        byId[nm] = (byId[nm] || 0) + 1;
        if (!seenSample.has(c) && samples.length < 6) {
          seenSample.add(c);
          samples.push({ x: bx, y, z: bz, n: comps[c], id: nm, surf: heightAt(bx, bz) });
        }
      }
      return { radius: rad, loaded: [...chunks.keys()].length, loadedCols,
               comps: floatIds.length, blocks, mainBody: main, byId, samples };
    },
    /* 生成成本验收（v350）：悬空碎屑清理 / 洞穴抖动各吃多少 ms */
    sweepCost(n = 6) {
      const c = [...chunks.values()].find(x => x.blocks);
      if (!c) return null;
      const out = { sweep: [], carve: [] };
      for (let i = 0; i < n; i++) {
        const b = c.blocks.slice();
        let t0 = performance.now();
        sweepFloatDebris(b, c.cx * CFG.CH, c.cz * CFG.CH);
        out.sweep.push(+(performance.now() - t0).toFixed(2));
      }
      // 洞穴函数单块成本（同一批坐标跑两遍取小值）
      const pts = [];
      for (let i = 0; i < 20000; i++) pts.push([(Math.random() * 600 - 300) | 0, 20 + (Math.random() * 90) | 0, (Math.random() * 600 - 300) | 0]);
      for (let rep = 0; rep < 2; rep++) {
        const t0 = performance.now();
        for (const [x, y, z] of pts) caveCarve(x, y, z, y + 30);
        out.carve.push(+((performance.now() - t0) * 1000 / pts.length).toFixed(3));
      }
      return out;
    },
    /* 地形形状验收：坡度分布 / 起伏 / 山地覆盖率 / 河流覆盖率
       ⚠ 采样必须用伪随机（LCG），不能 `(i*61)%800` 那种格点 —— 格点只扫一条斜带，
       曾经把「相邻列 80% 等高」报成 68%。 */
    terrainProbe(n = 40000) {
      const H = heightAt, SEA = CFG.SEA;
      let slope = 0, k = 0, min = 1e9, max = -1e9, below = 0, river = 0;
      let flat = 0, cliff = 0, maxDiff = 0, a130 = 0, a150 = 0;
      const dh = {};                       // 相邻列高差分布（0/1/2/3/4/5+）
      let s = 987654321;
      const rnd = () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; };
      for (let i = 0; i < n; i++) {
        const x = Math.floor(rnd() * 1200) - 600, z = Math.floor(rnd() * 1200) - 600;
        const h = H(x, z), hx = H(x + 1, z), hz = H(x, z + 1);
        const d = Math.abs(h - hx);
        slope += d; k++;
        dh[d] = (dh[d] || 0) + 1;
        if (d > maxDiff) maxDiff = d;
        if (d >= 3) cliff++;
        if (h === hx && h === hz) flat++;
        if (h < min) min = h; if (h > max) max = h;
        if (h > 130) a130++;
        if (h > 150) a150++;
        if (h <= SEA) below++;
        if (h <= SEA - 1 && riverMask(x, z) > 0.35) river++;
      }
      const pct = v => +(100 * v / k).toFixed(1);
      return { samples: k, meanAbsSlope: +(slope / k).toFixed(3), minH: min, maxH: max,
               relief: max - min, belowSeaFrac: +(below / k).toFixed(3), riverFrac: +(river / k).toFixed(4),
               flatFrac: pct(flat), cliffFrac: pct(cliff), maxDiff,
               above130Frac: pct(a130), above150Frac: pct(a150),
               diffHist: Object.fromEntries(Object.entries(dh).map(([d2, c]) => [d2, +(100 * c / k).toFixed(1)])) };
    },
    riverMask: (x, z) => +riverMask(x, z).toFixed(3),
    /* 高山湖验收：附近格子里的 tarn（位置/水位/水量），以及「水有没有漏到碗沿外」 */
    tarnProbe(n = 3) {
      const pcx = Math.floor(player.p.x / TARN_CELL), pcz = Math.floor(player.p.z / TARN_CELL);
      const out = [];
      for (let dx = -n; dx <= n; dx++) for (let dz = -n; dz <= n; dz++) {
        const t = tarnFor(pcx + dx, pcz + dz);
        if (!t) continue;
        const R = t.r - 1;                                  // 实际灌水半径（tarnAt 用的）
        const loaded = [];
        let rimMin = 999;
        for (let ax = -t.r - 3; ax <= t.r + 3; ax++) for (let az = -t.r - 3; az <= t.r + 3; az++) {
          const x = t.x + ax, z = t.z + az, d = Math.hypot(ax, az);
          const h = heightAt(x, z);
          if (d > R && d <= R + 2 && h < rimMin) rimMin = h;   // 只看湖沿那两圈
          if (chunks.has((x >> 4) + ',' + (z >> 4))) loaded.push([x, z, h, d]);
        }
        let water = 0;
        for (const [x, z, h, d] of loaded) if (d <= R) for (let y = h + 1; y <= t.level; y++) if (getBlock(x, y, z) === 5) water++;
        out.push({ x: t.x, z: t.z, r: R, level: t.level, loadedCols: loaded.length, water,
                   rimMin, leak: rimMin < t.level });
      }
      return out;
    },
    /* 群系验收：气候带分布 + 地表方块统计 */
    biomeProbe(n = 3000) {
      const px = Math.floor(player.p.x), pz = Math.floor(player.p.z);
      const cnt = { desert: 0, snow: 0, badlands: 0, none: 0 };
      let s1 = 12345;
      const rnd = () => { s1 = (s1 * 1103515245 + 12345) & 0x7fffffff; return s1 / 0x7fffffff; };
      for (let k = 0; k < n; k++) {
        const x = Math.floor(rnd() * 1600) - 800, z = Math.floor(rnd() * 1600) - 800;
        const b = biomeAt(x, z);
        cnt[b || 'none']++;
      }
      return { sample: n, counts: cnt, at: { x: px, z: pz, biome: biomeAt(px, pz) } };
    },
    biomeAt: (x, z) => biomeAt(x, z),
    /* 地下水和悬垂验收：低处洞穴里的水/岩浆格数、以及"头顶悬空"的石檐块数 */
    depthProbe(n = 1200) {
      const px = Math.floor(player.p.x), pz = Math.floor(player.p.z);
      let water = 0, lava = 0, lips = 0, cols = 0, cliffs = 0;
      let s2 = 99991;
      const rnd = () => { s2 = (s2 * 1103515245 + 12345) & 0x7fffffff; return s2 / 0x7fffffff; };
      for (let k = 0; k < n; k++) {
        const x = px + Math.floor(rnd() * 120 - 60), z = pz + Math.floor(rnd() * 120 - 60);
        if (!chunks.has((x >> 4) + ',' + (z >> 4))) continue;
        cols++;
        const h = heightAt(x, z);
        // 低处洞穴里的水/岩浆
        for (let y = 4; y <= 8; y++) {
          const id = getBlock(x, y, z);
          if (id === 5) water++;
          if (id === 44) lava++;
        }
        // 石檐：地面高度以上、下面悬空的**石头/深板岩**（2D 地形本身不可能有；树叶不算）
        for (let y = h + 1; y <= h + 5; y++) {
          const id = getBlock(x, y, z);
          if ((id === 3 || id === 50) && getBlock(x, y - 1, z) === 0) { lips++; break; }
        }
        if (heightAt(x, z) + 5 <= Math.max(heightAt(x + 1, z), heightAt(x - 1, z), heightAt(x, z + 1), heightAt(x, z - 1))) cliffs++;
      }
      return { columns: cols, caveWaterBlocks: water, caveLavaBlocks: lava,
               overhangBlocks: lips, cliffColumns: cliffs };
    },
    /* 友好动物验收：把 9 种各刷一只排在面前，返回它们的名字/血量/身高/是否落地 */
    animals() {
      const out = [];
      const base = Math.floor(player.p.x), bz = Math.floor(player.p.z);
      let i = 0;
      for (const k of ANIMAL_POOL) {
        const x = base - 8 + i * 2, z = bz + 4;
        const y = surfaceY(x, z) + 1;
        const m = spawnMobAt(k, x, y, z, { force: true });
        i++;
        if (m) out.push({ kind: k, name: MOB_DEFS[k].name, hp: m.hp, rad: +m.rad.toFixed(2),
                          top: +(def => def)(m.parts.barY || 0), onGround: m.onGround });
      }
      return { spawned: out.length, list: out, caps: ANIMAL_CAP, habitats: ANIMAL_HABITAT };
    },
    animalSpot: (kind) => findAnimalSpot(kind),
    iconOne: (id) => iconURL(id),        // ★ 单个图标的 data URL（验收自定义形状：门/船/罐）
    /* 图标总览：把所有方块 + 物品的图标铺成一张图（用来肉眼验收图标是否整齐） */
    iconSheet() {
      const old = document.getElementById('iconSheet');
      if (old) old.remove();
      const d = document.createElement('div');
      d.id = 'iconSheet';
      d.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#0e1216;padding:8px;overflow:auto;'
        + 'display:grid;grid-template-columns:repeat(12,1fr);gap:3px;font:8px monospace;color:#9fb3c8';
      const ids = [...Object.keys(BLOCKS).map(Number), ...Object.keys(ITEMS).map(Number)];
      for (const id of ids) {
        const w = document.createElement('div');
        w.style.cssText = 'text-align:center;line-height:1.1';
        const img = document.createElement('img');
        img.src = iconURL(id);
        img.style.cssText = 'width:44px;height:44px;image-rendering:pixelated;background:#181d24;border-radius:3px;display:block;margin:0 auto 1px';
        const lbl = document.createElement('div');
        lbl.style.cssText = 'overflow:hidden;white-space:nowrap;text-overflow:ellipsis';
        lbl.textContent = BLOCKS[id] ? BLOCKS[id].name : ITEMS[id].name;
        w.appendChild(img); w.appendChild(lbl);
        d.appendChild(w);
      }
      document.body.appendChild(d);
      return ids.length;
    },
    /* 村民工作令验收：下命令 / 看目标 / 看进度 */
    villagerTask(kind) {
      const v = mobs.find(m => m.kind === 'villager' && m.recruit && m.recruit.hired);
      if (!v) return { err: 'no hired villager' };
      if (kind !== undefined) setVillagerTask(v, kind);
      return { task: v.task, give: v.give ? nameOf(v.give.id) : null,
               tgt: v.mineTgt || null, prog: +(v.mineProg || 0).toFixed(2),
               distToPlayer: +Math.hypot(v.p.x - player.p.x, v.p.z - player.p.z).toFixed(1) };
    },
    /* 某格的状态：方块 id + 是否在 edits（玩家改动）里 —— 验「村民不挖玩家摆放方块」用 */
    editInfo: (x, y, z) => ({ block: getBlock(x, y, z), inEdits: edits.has(x + ',' + y + ',' + z), editsTotal: edits.size }),
    /* v322：门开合/床朝向这类 meta 的验收探针（meta 现在会随编辑上行联机） */
    metaAt: (x, y, z) => getMeta(x, y, z) | 0,
    collides: (x, y, z) => collides(x + 0.5, y, z + 0.5),   // 门开着的格子应该 false（能走过去）
    setMetaAt: (x, y, z, m) => { setMeta(x, y, z, m | 0, false); return getMeta(x, y, z) | 0; },
    netStats: () => (window.NET ? { active: NET.active, mode: NET.mode, pending: NET.pending.size, pendingKey: NET.pendingKey ? NET.pendingKey.size : -1, editOut: NET.editOut, rej: NET.rejCount, rejLast: NET.rejLast || '', connected: NET.connected } : null),
    /* 村民尸体验收：谁在背包里、谁躺在地上、复活结果 */
    corpseState() {
      const inBag = inv.filter(s => s && s.id === 207).map(s => ({ n: s.n,
        hp: s.corpse && s.corpse.maxHp, equip: s.corpse && s.corpse.equip, task: s.corpse && s.corpse.task }));
      const onGround = mobs.filter(m => m.corpse).map(m => ({
        pos: [+m.p.x.toFixed(1), +m.p.y.toFixed(1), +m.p.z.toFixed(1)],
        hp: m.corpseData && m.corpseData.maxHp, equip: m.corpseData && m.corpseData.equip }));
      const hired = squadList().map(m => ({ hp: +m.hp.toFixed(0), maxHp: m.maxHp,
        give: m.give ? nameOf(m.give.id) : null, dmg: m.give && ITEMS[m.give.id] ? ITEMS[m.give.id].dmg || 0 : 0 }));
      return { inBag, onGround, hired, diamondApples: inv.filter(s => s && s.id === 206).reduce((a, s) => a + s.n, 0) };
    },
    /* 尸体全流程自检：背包里的尸体 → 放地上 → 喂钻石苹果复活（走的是正式代码路径） */
    corpseDemo() {
      const out = { steps: [] };
      const slot = inv.find(s => s && s.id === 207);
      out.bagBefore = slot ? { n: slot.n, equip: slot.corpse && slot.corpse.equip, task: slot.corpse && slot.corpse.task } : null;
      if (!slot) return out;
      const x = Math.floor(player.p.x) + 2, z = Math.floor(player.p.z);
      const y = surfaceY(x, z) + 1;
      out.steps.push(['place', placeCorpseAt(x, y, z, slot)]);
      const cm = mobs.find(m => m.corpse);
      out.steps.push(['onGround', !!cm]);
      if (!cm) return out;
      addItem(206, 1);                                        // 给一个钻石苹果并拿在手上
      const ai = inv.findIndex(s2 => s2 && s2.id === 206);
      if (ai >= 0) { player.sel = ai; refreshHeld(); renderHotbar(); }
      out.steps.push(['revived', reviveCorpse(cm)]);
      const sm = squadList()[0];
      out.after = sm ? { maxHp: sm.maxHp, hp: +sm.hp.toFixed(0), equip: sm.equip,
                         give: sm.give ? nameOf(sm.give.id) : null, task: sm.task } : null;
      out.corpsesLeft = mobs.filter(m => m.corpse).length;
      return out;
    },
    dropCount: () => drops.length,
    spawnDrop: (id, n) => spawnDrop(id, n, player.p.x + 1.2, player.p.y + 1.2, player.p.z),
    /* 掉落物状态：位置 / 网格有没有挂进场景（排查"物品掉了看不见"用） */
    dropList(n = 8) {
      return drops.slice(-n).map(d => ({ id: d.id, n: d.n, p: [+d.p.x.toFixed(2), +d.p.y.toFixed(2), +d.p.z.toFixed(2)],
        meshAt: [+d.obj.position.x.toFixed(2), +d.obj.position.y.toFixed(2), +d.obj.position.z.toFixed(2)],
        inScene: !!d.obj.parent, visible: d.obj.visible, thin: !!d.thin }));
    },
    /* 按绝对坐标掉一个（原来的封装只能掉在脚下，验货时会被自动捡走） */
    dropAt: (id, x, y, z) => { const d = spawnDrop(id, 1, x, y, z); return !!d; },
    /* 掉落物贴图检查：方块必须用平贴图（四角不透明），物品用像素图标 */
    dropTexInfo(id) {
      const tex = dropTexture(id);
      const src = tex.image && (tex.image.src || '');
      const cv = document.createElement('canvas'); cv.width = cv.height = 32;
      const g2 = cv.getContext('2d');
      g2.drawImage(tex.image, 0, 0, 32, 32);
      const corner = g2.getImageData(1, 1, 1, 1).data[3];
      const center = g2.getImageData(16, 16, 1, 1).data[3];
      return { id, isBlock: !!BLOCKS[id], cornerAlpha: corner, centerAlpha: center, bytes: src.length };
    },
    stepDrops: (n = 1) => { for (let i = 0; i < n; i++) updateDrops(1 / 60); },
    smeltIdx: (i) => smelt(SMELT[i]),
    fuel: () => fuelCount(),
    inVillage: (x, z) => inVillage(x, z),
    leavesInVillages: (r = 1) => {
      const pcx = Math.floor(player.p.x / VS_CELL), pcz = Math.floor(player.p.z / VS_CELL);
      let total = 0, perVillage = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const v = villageFor(pcx + dx, pcz + dz);
        if (!v) continue;
        let n = 0;
        for (let x = v.minX; x <= v.maxX; x++) for (let z = v.minZ; z <= v.maxZ; z++)
          for (let y = v.gy - 2; y < v.gy + 14; y++) if (getBlock(x, y, z) === 7) n++;
        perVillage.push({ cx: v.cx, cz: v.cz, leaves: n });
        total += n;
      }
      return { total, perVillage };
    },
    furnaceOpen: () => !$('furnace').classList.contains('hide'),
    furnaceJob: () => furnaceJob ? { out: nameOf(furnaceJob.r.out), t: +furnaceJob.t.toFixed(2), dur: jobDur(furnaceJob), left: furnaceJob.left, fuel: furnaceJob.fuelName } : null,
    furnaceTick: (dt) => { updateFurnaceJob(dt); return furnaceJob ? { out: nameOf(furnaceJob.r.out), t: +furnaceJob.t.toFixed(2), dur: jobDur(furnaceJob), left: furnaceJob.left, fuel: furnaceJob.fuelName } : null; },
    fuelDefs: () => FUEL_DEFS.map(f => ({ ...f })),
    fuelNow: () => furnaceFuel,
    setFuel: (id) => { furnaceFuel = id; renderFurnace(); return furnaceFuel; },
    // ── 电路系统探针（本地 UI 验收用；联机模式下会被 stub 掉）──
    gun: () => {
      const h = held();
      if (!h || !ITEMS[h.id] || ITEMS[h.id].kind !== 'gun') return null;
      return { slot: player.sel, id: h.id, name: nameOf(h.id), charge: gunCharge(h), cap: gunCap(h.id), hud: gunHudEl ? gunHudEl.textContent : null, hudShown: !!(gunHudEl && gunHudEl.style.display === 'block') };
    },
    setCharge: (v) => { const h = held(); if (!h || !ITEMS[h.id] || ITEMS[h.id].kind !== 'gun') return null; h.c = Math.max(0, Math.min(gunCap(h.id), v | 0)); renderHotbar(); refreshGunHud(); return gunCharge(h); },
    fireGun: () => fireEnergyBolt(),
    bolts: () => arrows.filter(a => a.bolt).map(a => ({ dmg: a.dmg, p: [+a.p.x.toFixed(2), +a.p.y.toFixed(2), +a.p.z.toFixed(2)], t: +a.t.toFixed(2) })),
    chargerOpen: () => !$('charger').classList.contains('hide'),
    chargerJobs: () => (chargerJob ? [{ slot: chargerJob.slot, name: nameOf(chargerJob.id), t: +chargerJob.t.toFixed(2), dur: chargerJob.dur }] : []),
    chargerTargets: () => chargerTargets().map(x => ({ slot: x.i, name: nameOf(x.s.id), charge: gunCharge(x.s), cap: gunCap(x.s.id) })),
    chargeStart: (slot) => startCharge(slot === undefined ? chargerTargets()[0] && chargerTargets()[0].i : slot),
    /* ★ v339 氧气 / 左手栏探针 */
    oxygen: () => ({
      air: +(player.air === undefined ? OXY_MAX : player.air).toFixed(2), airMax: OXY_MAX,
      eyeUnder: eyeUnderwater(), drownT: +(player.drownT || 0).toFixed(2),
      off: player.off ? { id: player.off.id, name: nameOf(player.off.id), charge: +tankCharge(player.off).toFixed(2) } : null,
      activeTank: offhandTank() ? { id: offhandTank().id, charge: +tankCharge(offhandTank()).toFixed(2), cap: tankCap(offhandTank().id) } : null,
      hud: { oxyShown: !!($('oxyrow') && $('oxyrow').style.display !== 'none'),
             tankShown: !!($('tankrow') && $('tankrow').style.display !== 'none'),
             oxyText: $('oxyTxt') ? $('oxyTxt').textContent : null,
             tankText: $('tankTxt') ? $('tankTxt').textContent : null },
      offSlotText: $('offSlot') ? $('offSlot').title : null,
    }),
    setAir: (v) => { player.air = clamp(+v || 0, 0, OXY_MAX); renderOxygen(); return player.air; },
    setTankCharge: (v) => { const t = offhandTank(); if (!t) return null; t.c = clamp(+v || 0, 0, tankCap(t.id)); renderHotbar(); renderOxygen(); return tankCharge(t); },
    giveTank: (charge) => {
      addItem(OXY_TANK_ID, 1);
      const slot = inv.findIndex(x => x && x.id === OXY_TANK_ID);
      if (slot >= 0) inv[slot].c = clamp(charge === undefined ? OXY_TANK_CAP : +charge, 0, OXY_TANK_CAP);
      renderHotbar();
      return slot >= 0 ? { slot, charge: tankCharge(inv[slot]) } : null;
    },
    swapOffhand: () => swapOffhand(),
    remoteTanks: () => [...((typeof NET !== 'undefined' && NET && NET.remotes) ? NET.remotes.entries() : [])]
      .map(([id, r]) => ({ id, oh: r.oh | 0, visible: !!(r.obj && r.obj.userData && r.obj.userData.tank && r.obj.userData.tank.visible) })),
    chargerTick: (dt) => { updateChargerJob(dt); return chargerJob ? { t: +chargerJob.t.toFixed(2), dur: chargerJob.dur } : null; },
    chargerHtml: () => ({ hasPanel: !!$('charger'), rows: $('chgList') ? $('chgList').children.length : -1, info: $('chgInfo') ? $('chgInfo').textContent : null }),
    chests: () => [...chestObjs.entries()].map(([k, o]) => ({ k, lid: +(o.lidPivot.rotation.x).toFixed(2), targetP: o.targetP })),
    doors: () => [...doorObjs.entries()].map(([k, o]) => ({ k, dir: o.dir, p: +o.p.toFixed(3), targetP: o.targetP, rotY: +o.group.rotation.y.toFixed(3) })),
    /* ★ 门状态（准）：root = 下半格 y，open 只看下半格；pass 表示这格现在能不能穿过去。
       验收「门开着却过不去」「上下半格不一致」时直接读这个，别自己拼 meta。 */
    doorStateAt: (x, y, z) => {
      const id = getBlock(x, y, z);
      const root = doorRootY(x, y, z);
      const gate = root === null ? null : getMeta(x, root, z) | 0;
      return { id, root, mLo: gate, mHi: getMeta(x, y + 1, z) | 0, open: doorOpenAt(x, y, z),
               pass: !(BLOCKS[id] && BLOCKS[id].door) || doorOpenAt(x, y, z) };
    },
    doorBox: (dir, open) => {          // 关/开门时门板在世界格内的包围盒（必须落在 0..1，否则穿模邻居）
      const geo = doorGeometry(dir), d = DOOR_DEF[dir];
      const pos = geo.attributes.position.array, a = open ? d.a : 0;
      const cos = Math.cos(a), sin = Math.sin(a);
      let mnx = 9, mxx = -9, mnz = 9, mxz = -9, mny = 9, mxy = -9;
      for (let i = 0; i < pos.length; i += 3) {
        const X = pos[i] * cos + pos[i + 2] * sin, Z = -pos[i] * sin + pos[i + 2] * cos;
        mnx = Math.min(mnx, X + d.hx); mxx = Math.max(mxx, X + d.hx);
        mnz = Math.min(mnz, Z + d.hz); mxz = Math.max(mxz, Z + d.hz);
        mny = Math.min(mny, pos[i + 1]); mxy = Math.max(mxy, pos[i + 1]);
      }
      return { dir, open, x: [+mnx.toFixed(3), +mxx.toFixed(3)], y: [+mny.toFixed(3), +mxy.toFixed(3)],
               z: [+mnz.toFixed(3), +mxz.toFixed(3)] };
    },
    villagers: () => mobs.filter(m => m.recruit).map(m => ({
      hp: m.hp, hired: m.recruit.hired, follow: m.recruit.follow,
      want: { name: nameOf(m.recruit.want.id), need: m.recruit.want.need, got: m.recruit.want.got },
      give: m.give ? nameOf(m.give.id) : null, hasMark: !!m.mark, hasGift: !!m.gift,
      pos: [+m.p.x.toFixed(1), +m.p.y.toFixed(1), +m.p.z.toFixed(1)],
    })),
    restoreSquad: (l) => restoreSquad(l),
    squadSave: () => squadData(),
    /* ★ v353 金字塔：看进度 / 直接传送进去（验收用） */
    pyrInfo() {
      const p = pyrAt(player.p.x, player.p.y, player.p.z);
      if (!p || !p.rooms) return { inPyramid: false };
      const key = pyrKeyOf(p), st = pyrState(key);
      return { inPyramid: true, key, gy: p.gy, y1: p.y1, stage: st.stage, cleared: st.cleared, chosen: st.chosen,
               boss: st.bossSpawned, done: st.done,
               rooms: p.rooms.map((r, i) => ({ i, x: r.cx, z: r.cz, w: r.w, d: r.d, y: r.y,
                 doors: (r.doors || []).length, chests: (r.chests || []).map(c => [c.x, c.y, c.z]) })),
               bossAt: [p.boss.cx, p.boss.y + 1, p.boss.cz] };
    },
    pyrGo(i = 0) {                                 // 传送到最近的/当前金字塔第 i 间房
      let p = pyrAt(player.p.x, player.p.y, player.p.z);
      if (!p) {
        const cx = Math.floor(player.p.x / PYR_CELL), cz = Math.floor(player.p.z / PYR_CELL);
        for (let r = 0; r <= 10 && !p; r++) for (let dx = -r; dx <= r && !p; dx++) for (let dz = -r; dz <= r && !p; dz++) p = pyrFor(cx + dx, cz + dz);
      }
      if (!p || !p.rooms) return null;
      const t = i >= PYR_TRIALS ? p.boss : p.rooms[Math.max(0, Math.min(PYR_TRIALS - 1, i))];
      player.p.set(t.cx + 0.5, t.y + 1.01, t.cz + 0.5);
      player.v.set(0, 0, 0);
      return { at: [t.cx, t.y + 1, t.cz], key: pyrKeyOf(p) };
    },
    pyrKillTrial() {                               // 秒掉当前试炼波（验收用）
      let n = 0;
      for (const m of mobs) if (m.pyr) { m.hp = 0; n++; }
      return n;
    },
    pyrOpen(i = 0) {                               // 打开当前房间第 i 个箱子：看战利品 + 另外两个是否消失
      const p = pyrAt(player.p.x, player.p.y, player.p.z);
      if (!p || !p.rooms) return null;
      const key = pyrKeyOf(p), st = pyrState(key);
      const r = p.rooms[st.stage];
      if (!r || !r.chests || !r.chests.length) return null;
      const c = r.chests[Math.min(i, r.chests.length - 1)];
      const arr = chestSlots(c.x, c.y, c.z);
      const loot = arr.filter(Boolean).map(s => [s.id, s.n]);
      pyrOnChestOpened(c.x, c.y, c.z);
      const now = r.chests.map(cc => getBlock(cc.x, cc.y, cc.z));
      return { opened: [c.x, c.y, c.z], loot, chestBlocks: now, stage: st.stage, chosen: st.chosen };
    },
    pyrBossKill() {
      let n = 0;
      for (const m of mobs) if (m.pyrBoss) { m.hp = 0; n++; }
      return n;
    },
    pyrCells(span = 3) {                           // 附近有几座金字塔（密度体检）
      const cx = Math.floor(player.p.x / PYR_CELL), cz = Math.floor(player.p.z / PYR_CELL);
      const out = [];
      for (let dx = -span; dx <= span; dx++) for (let dz = -span; dz <= span; dz++) {
        const p = pyrFor(cx + dx, cz + dz);
        if (p) out.push({ key: pyrKeyOf(p), cx: p.cx, cz: p.cz, gy: p.gy });
      }
      return out;
    },
    /* ★ v359：把玩家从方块里拔出来（进房/重生用的是同一套），验收用 */
    unstick() {
      const before = [+player.p.x.toFixed(2), +player.p.y.toFixed(2), +player.p.z.toFixed(2)];
      const moved = unstickPlayer(player.p.x, player.p.y, player.p.z);
      return { before, after: [+player.p.x.toFixed(2), +player.p.y.toFixed(2), +player.p.z.toFixed(2)],
               moved, free: playerBoxFree(player.p.x, player.p.y, player.p.z) };
    },
    structDensity: (cells = 10) => {             // 各结构在 (n2+1)² 个格子里出现的比例（频率体检）
      const out = {};
      for (const t of STRUCT_TYPES) {
        let found = 0, tot = 0;
        for (let cx = -cells; cx <= cells; cx++) for (let cz = -cells; cz <= cells; cz++) {
          tot++;
          if (t.get(cx, cz)) found++;
        }
        out[t.name] = { cell: t.cell, found, tot, pct: +(100 * found / tot).toFixed(1) };
      }
      return out;
    },
    struct: { sel: structSel, export: exportStructure, upload: uploadStructure, list: listStructures, place: placeStructureAt,
      setCorner: setStructCorner, hud: structHud },
    sleep: () => GAME.mobs.filter(m => m.kind === 'villager').map(m => ({
      sleeping: !!m.sleeping, bed: m.bed ? [m.bed.x, m.bed.y, m.bed.z] : null,
      pos: [+m.p.x.toFixed(1), +m.p.y.toFixed(1), +m.p.z.toFixed(1)], rotX: +m.parts.core.rotation.x.toFixed(2) })),
    setNight: (v) => { worldTime = CFG.DAY * (v ? 0.62 : 0.25); updateSky(); return isNight(); },
    sight: (kind) => { const t = mobs.find(m => m.kind === kind); return t ? sightClear(player.p, t.p) : null; },
    limbs: () => { const m = GAME.mobs.find(x => x.recruit); return m ? { limbs: m.parts.limbs.length, arms: [!!m.parts.arm1, !!m.parts.arm2] } : null; },
    squad: () => squadList().map(m => ({ name: MOB_DEFS[m.kind].name, follow: m.recruit.follow,
      equip: m.equip, armorMeshes: m.armorMeshes ? m.armorMeshes.length : 0,
      pos: [+m.p.x.toFixed(1), +m.p.y.toFixed(1), +m.p.z.toFixed(1)] })),
    openPanel: () => { const l = squadList(); if (!l.length) return false; openVillagerPanel(l[0]); return document.getElementById('vpanel').style.display === 'block'; },
    panelText: () => (document.getElementById('vpanel') || {}).innerText || null,
    gear: (slot) => { const l = squadList(); if (!l.length) return false; return equipVillager(l[0], slot); },
    spawnVillager: () => { const p = spawnMobAt('villager', Math.floor(player.p.x) + 2, Math.floor(player.p.y) + 1, Math.floor(player.p.z));
      return p ? { ok: true, want: nameOf(p.recruit.want.id), need: p.recruit.want.need } : { ok: false }; },
    /* 矿工验收：spawnMiner() 直接在身边放一只；minerInfo() 看它在干什么（有没有镐子/是否敌对/掉落表） */
    /* 验收：同一区块连刷 5 只僵尸，只应该成功 HOSTILE_PER_CHUNK 只 */
    /* 验收（多人）：本地玩家剩余保护秒数 + 每个客人的保护/死亡状态 */
    /* 验收：水下视野 —— 眼睛是否在水里、雾距、叠加层是否打开 */
    /* 验收：游泳动画 —— 本地状态、第一人称手部、联机状态位 */
    /* 验收：船与水花 —— 放船/上船/浪高，一条命令看全部 */
    boatTest: () => {
      const b = boats[0];
      return { boats: boats.length, splash: splashes.length,
        riding: !!player.riding,
        boat: b ? { wood: BOAT_WOOD[b.wi].name, at: [+b.x.toFixed(2), +b.y.toFixed(3), +b.z.toFixed(2)],
          surf: +(boatSurfaceY(b.x, b.z) || 0).toFixed(3), vy: +b.vy.toFixed(2),
          tiltX: +b.obj.rotation.x.toFixed(3), tiltZ: +b.obj.rotation.z.toFixed(3) } : null,
        waveNow: +waveAt(player.p.x, player.p.z, performance.now() * 0.001).toFixed(4) };
    },
    /* 验收：把 6 种船全摆出来看一眼 */
    /* 验收：联机船 —— 房主有多少条、客人收到几条、客人在哪条船上 */
    /* 验收：手里有什么 / 直接调用放船逻辑（绕过按键，用来区分「判定坏了」还是「按键没触发」） */
    heldNow: () => { const h = held(); return h ? { id: h.id, n: h.n, name: (ITEMS[h.id] || {}).name } : null; },
    boatPlaceNow: () => {
      const h = held();
      if (!h) return { err: 'nothing held' };
      const before = boats.length;
      const ok = useBoat(h, null);
      return { heldId: h.id, ok, before, after: boats.length, sel: player.sel };
    },
    /* 验收：准星对着水面放船（走真实 rayWater 判定，返回 null 表示这个视角放不了） */
    boatAimTest: () => {
      const src = rayWater(CFG.REACH);
      return { aimedAtWater: !!src, src, underFeet: getBlock(Math.floor(player.p.x), Math.floor(player.p.y), Math.floor(player.p.z)) };
    },
    boatNet: () => ({
      hostBoats: boats.length,
      guestSeen: (typeof NET !== 'undefined' && NET && NET.gBoats) ? NET.gBoats.size : null,
      riding: !!player.riding,
      ridingGhost: !!(player.riding && player.riding.__ghost),
      ids: boats.map(b => b.id),
    }),
    boatAll: (dz = 2.2) => {
      for (const b of boats.slice()) { scene.remove(b.obj); }
      boats.length = 0;
      const bx = player.p.x, bz = player.p.z - 6;
      const out = [];
      for (let i = 0; i < 6; i++) {
        const x = bx + (i - 2.5) * dz;
        const y = boatSurfaceY(x, bz) || (player.p.y + 0.2);
        const b = spawnBoat(x, bz, i, y);
        out.push({ wood: BOAT_WOOD[i].name, at: [+x.toFixed(1), +b.y.toFixed(2)] });
      }
      return out;
    },
    swimTest: () => ({
      swimming: !!player.swimming, inWater: !!player.inWater,
      swimK: +anim.swimK.toFixed(2), waterK: +anim.waterK.toFixed(2),
      flag: (typeof window.NET !== 'undefined' && window.NET && window.NET.myFlags) ? window.NET.myFlags() : null,
      armR: { pos: armR.position.toArray().map(v => +v.toFixed(3)), rot: [+armR.rotation.x.toFixed(3), +armR.rotation.y.toFixed(3), +armR.rotation.z.toFixed(3)] },
    }),
    underFx: () => {
      const ex = Math.floor(player.p.x), ey = Math.floor(player.p.y + 1.55), ez = Math.floor(player.p.z);
      return { eyeBlock: getBlock(ex, ey, ez), eyeInWater: getBlock(ex, ey, ez) === 5,
        fog: { near: +scene.fog.near.toFixed(2), far: +scene.fog.far.toFixed(1), color: '#' + scene.fog.color.getHexString() },
        overlay: !!uwFxEl && uwFxEl.classList.contains('on'),
        hasBlur: !!uwFxEl && getComputedStyle(uwFxEl).backdropFilter !== 'none' };
    },
    guardState: () => ({ playerGuard: +playerGuard.toFixed(1),
      guests: [...((typeof NET !== 'undefined' && NET && NET.remotes) ? NET.remotes.keys() : [])].map(pid => ({
        pid, guard: +(guestGuard.get(pid) || 0).toFixed(1), dead: guestDead.has(pid) })) }),
    chunkCapTest: () => {
      const x = Math.floor(player.p.x) + 6, z = Math.floor(player.p.z);
      let y = surfaceY(x, z) + 1;
      for (let i = 0; i < 4 && getBlock(x, y, z) !== 0; i++) y++;
      const ok = [];
      for (let i = 0; i < 5; i++) ok.push(!!spawnMobAt('grunt', x + i, y, z));
      return { tried: 5, spawned: ok.filter(Boolean).length, cap: HOSTILE_PER_CHUNK,
               inChunk: hostilesInChunk(x >> 4, z >> 4), playerGuard: +playerGuard.toFixed(1) };
    },
    /* 验收：刷怪距离（走 findSpawnSpot 的自然刷怪路径） */
    spawnDistTest: (n = 8) => {
      const before = mobs.length;
      for (let i = 0; i < n; i++) spawnMob('grunt');
      const d = mobs.slice(before).filter(m => m.kind === 'grunt')
        .map(m => +Math.hypot(m.p.x - player.p.x, m.p.z - player.p.z).toFixed(1)).sort((a, b) => a - b);
      return { spawned: d.length, minDist: d.length ? d[0] : null, dists: d };
    },
    spawnMiner: () => {
      /* 放在玩家旁边**空着**的格子上（+1 层）：直接塞在地里的话它会被方块卡住不动，
         看起来像「AI 坏了」，其实是探针把它埋在石头里了。 */
      const bx = Math.floor(player.p.x) + 2, bz = Math.floor(player.p.z);
      let by = Math.floor(player.p.y) + 1;
      for (let i = 0; i < 4 && getBlock(bx, by, bz) !== 0; i++) by++;
      const p = spawnMobAt('miner', bx, by, bz, { force: true });
      return p ? { ok: true, hp: p.hp, hasPick: !!p.pick, dmg: MOB_DEFS.miner.dmg, drop: MOB_DEFS.miner.drop, at: [bx, by, bz] } : { ok: false };
    },
    minerInfo: () => mobs.filter(m => m.kind === 'miner').map(m => ({
      hp: m.hp, hasPick: !!m.pick, dmg: MOB_DEFS.miner.dmg,
      dist: +Math.hypot(m.p.x - player.p.x, m.p.z - player.p.z).toFixed(2),
      pos: [+m.p.x.toFixed(1), +m.p.y.toFixed(1), +m.p.z.toFixed(1)], aggro: +m.aggro.toFixed(1),
    })),
    /* 矿洞结构验收：附近矿洞的种类 / 箱子数 / 火把数 / 是否通地表 / 构件数 */
    mineInfo: (r = 1) => {
      const pcx = Math.floor(player.p.x / MS_CELL), pcz = Math.floor(player.p.z / MS_CELL);
      const out = [];
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        const ms = mineshaftFor(pcx + dx, pcz + dz);
        if (!ms) continue;
        out.push({ cell: [pcx + dx, pcz + dz], kind: ms.kind, at: [ms.ox, ms.baseY, ms.oz],
                   chests: ms.chests, torches: ms.torches, ops: ms.ops, entrance: ms.entrance,
                   dist: +Math.hypot(ms.ox - player.p.x, ms.oz - player.p.z).toFixed(0) });
      }
      return out;
    },
    dropCount: () => drops.length,          // 验收用：打死矿工前后该值不变（矿工不掉任何东西）
    plants: () => { let n36 = 0, n37 = 0, meshes = 0, verts = 0;
      for (const ch of chunks.values()) {
        meshes += ch.plant ? 1 : 0;
        if (ch.plant) verts += ch.plant.geometry.attributes.position.count;
        const b = ch.blocks;
        for (let i = 0; i < b.length; i++) { if (b[i] === 36) n36++; else if (b[i] === 37) n37++; }
      }
      return { grass: n36, flowers: n37, plantMeshes: meshes, plantVerts: verts }; },
    eat: () => ({ on: eatState.on, t: +eatState.t.toFixed(2), bites: eatState.bites, id: eatState.id, hunger: +player.hunger.toFixed(1) }),
    openFurnace: () => openFurnace(),
    openProcessor: () => openProcessor(),
    closeProcessor: () => closeProcessor(),
    processorOpen: () => processorOpen,
    chipCount: () => countOf(170),
    logCount: () => countOf(6),
    processN: (n) => chipBatch(n),
    openPress: () => openPress(),
    closePress: () => closePress(),
    pressOpen: () => pressOpen,
    pressInfo: () => ({ carbon: countOf(177), iron: countOf(106), steel: countOf(178), can: pressCan() }),
    pressN: (n) => pressBatch(n),
    netherOre: () => {                            // 冥界矿脉体检：数一下已加载区块里的冥界碳
      let c = 0, chunksN = 0;
      for (const ch of chunks.values()) {
        chunksN++;
        const bl = ch.blocks, CH = CFG.CH, WH = CFG.WH;
        for (let y = NETHER_LAVA_Y; y < WH; y++) for (let i = 0; i < CH * CH; i++) if (bl[(y * CH * CH) + i] === 46) c++;
      }
      return { chunks: chunksN, carbon: c, perChunk: chunksN ? +(c / chunksN).toFixed(1) : 0 };
    },
    dim: () => DIM,
    goNether: () => travelDimension(null),
    spawnHere: (kind, dx, dz) => spawnMobAt(kind, Math.round(player.p.x + (dx || 0)), Math.round(player.p.y), Math.round(player.p.z + (dz || 0))),
    mobBox: (kind) => { const m = mobs.find(x => x.kind === kind); if (!m) return null; let mn = [1e9, 1e9, 1e9], mx = [-1e9, -1e9, -1e9];
      m.obj.updateMatrixWorld(true);
      m.obj.traverse(o => { if (!o.isMesh || !o.geometry) return; const g = o.geometry; if (!g.boundingBox) g.computeBoundingBox();
        const b = g.boundingBox; for (const cx of [b.min.x, b.max.x]) for (const cy of [b.min.y, b.max.y]) for (const cz of [b.min.z, b.max.z]) {
          const v = new THREE.Vector3(cx, cy, cz).applyMatrix4(o.matrixWorld);
          mn = [Math.min(mn[0], v.x), Math.min(mn[1], v.y), Math.min(mn[2], v.z)];
          mx = [Math.max(mx[0], v.x), Math.max(mx[1], v.y), Math.max(mx[2], v.z)]; } });
      return { size: [+(mx[0] - mn[0]).toFixed(2), +(mx[1] - mn[1]).toFixed(2), +(mx[2] - mn[2]).toFixed(2)], feetGap: +(mn[1] - m.p.y).toFixed(2) }; },
    goOver: () => (DIM === 'nether' ? travelDimension(null) : false),
    loadErr: () => loadErr,
    savedInfo: () => { try { const d = JSON.parse(localStorage.getItem(worldKey(currentId)) || 'null'); return d ? { y: d.player && d.player.y, dim: d.dim, edits: (d.edits || []).length } : null; } catch (e) { return String(e); } },
    burnState: () => ({ playerBurn: +(player.burn || 0).toFixed(2),
                        burnFx: ($('burnFx') || {}).className || '',
                        playerFlames: playerFlames.filter(s => s.visible).length,
                        mobs: mobs.filter(m => m.burn > 0).map(m => ({
                          kind: m.kind, burn: +m.burn.toFixed(2),
                          sprites: (m.fx || []).filter(s => s.visible).length,
                          emissive: m.parts.bodyMat.emissive.getHex().toString(16),
                        })) }),
    setMobBurn: (i, sec = 3) => { const m = mobs[i]; if (!m) return null; m.burn = sec; return m.kind; },
    fromPortal: () => player.fromPortal ? { ...player.fromPortal } : null,
    portalActiveAny: (wx, wz) => {                    // 当前维度里找这座门的核心并读激活状态
      const o = portalFor(Math.floor(wx / PT_CELL), Math.floor(wz / PT_CELL));
      if (!o) return null;
      return isPortalActive({ x: o.cx, y: o.gy + 2, z: o.cz });
    },
    travel: () => travelDimension(),
    usePortal: (x, y, z) => usePortal(x, y, z),
    portalAt: (wx, wz) => { const o = portalFor(Math.floor(wx / PT_CELL), Math.floor(wz / PT_CELL)); return o ? { cx: o.cx, cz: o.cz, gy: o.gy } : null; },
    portalNear: (cells = 6) => {                     // 找离玩家最近的传送门（无头测试/自检用）
      const pcx = Math.floor(player.p.x / PT_CELL), pcz = Math.floor(player.p.z / PT_CELL);
      let best = null;
      for (let dx = -cells; dx <= cells; dx++) for (let dz = -cells; dz <= cells; dz++) {
        const o = portalFor(pcx + dx, pcz + dz);
        if (!o) continue;
        const d = Math.hypot(o.cx - player.p.x, o.cz - player.p.z);
        if (!best || d < best.d) best = { cx: o.cx, cz: o.cz, gy: o.gy, d: Math.round(d) };
      }
      return best;
    },
    portalActive: (x, y, z) => { const c = findPortalCore(x, y, z); return c ? isPortalActive(c) : null; },
    netherMobs: () => GAME.mobs.filter(m => MOB_DEFS[m.kind] && MOB_DEFS[m.kind].dim === 'nether').map(m => m.kind),
    swamps: (r) => { const out = []; const cx = Math.floor(player.p.x / LS_CELL), cz = Math.floor(player.p.z / LS_CELL); for (let dx = -(r || 1); dx <= (r || 1); dx++) for (let dz = -(r || 1); dz <= (r || 1); dz++) { const s = lavaSwamp(cx + dx, cz + dz); if (s) out.push({ x: s.x, z: s.z, trees: s.trees.length, dist: Math.round(Math.hypot(s.x - player.p.x, s.z - player.p.z)) }); } return out; },
    tangle: () => ({ t: +(player.tangle || 0).toFixed(2), near: vineNearPlayer(), bossCd: Math.round(crocBossCd), kings: GAME.mobs.filter(m => m.kind === 'crocKing').length }),
    nearSwamp: () => { const cx = Math.floor(player.p.x / LS_CELL), cz = Math.floor(player.p.z / LS_CELL); for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) { const s = lavaSwamp(cx + dx, cz + dz); if (s && Math.hypot(s.x - player.p.x, s.z - player.p.z) < 60) return s; } return null; },
    spawnKind: (kind, dx = 3, dz = 0) => {           // 指定种类刷一只（自检/截图用）
      const x = Math.floor(player.p.x + dx), z = Math.floor(player.p.z + dz);
      let y = Math.floor(player.p.y);
      for (let k = 0; k < 8; k++) { const id = getBlock(x, y - 1, z); if (id !== 0 && id !== 44) break; y--; }
      const m = spawnMobAt(kind, x, y, z, { force: true });
      return m ? { kind: m.kind, p: [+m.p.x.toFixed(1), +m.p.y.toFixed(1), +m.p.z.toFixed(1)], hp: m.hp } : null;
    },
    openedChestCount: () => chestInv.size,
    chestContents: () => openChestPos ? chestSlots(openChestPos.x, openChestPos.y, openChestPos.z).map(s => s ? s.id + ':' + s.n : null) : null,
    cursor: () => cursor,
    clickChestSlot: (i) => { if (!openChestPos) return null; slotClick(chestSlots(openChestPos.x, openChestPos.y, openChestPos.z), i); return cursor; },
    clickInvSlot: (i) => { slotClick(inv, i); return cursor; },
    clickArmorSlot: (s) => { const el = $('armorGrid').children[ARMOR_SLOTS.indexOf(s)]; if (el) el.click(); return cursor; },
    closeChest: () => closeChest(),
    chestOpen: () => !!openChestPos,
    findBlockAny: (id, r = 40) => {
      const px = Math.floor(player.p.x), pz = Math.floor(player.p.z);
      for (let d = 0; d < r; d++) for (let dx = -d; dx <= d; dx++) for (let dz = -d; dz <= d; dz++) {
        if (Math.max(Math.abs(dx), Math.abs(dz)) !== d) continue;
        for (let y = CFG.WH - 1; y > 0; y--) if (getBlock(px + dx, y, pz + dz) === id) return [px + dx, y, pz + dz];
      }
      return null;
    },
    /* ★ v347：群系专属怪 + 巨像新家的验收探针（一只都不用自己找） */
    biomeMobs: () => {
      const kinds = ['frostWisp', 'cactusBrute', 'thornsniper', 'ancientColossus'];
      const out = {};
      for (const k of kinds) {
        const list = mobs.filter(m => m.kind === k && m.hp > 0);
        out[k] = {
          n: list.length,
          near: list.length ? +Math.min(...list.map(m => Math.hypot(m.p.x - player.p.x, m.p.z - player.p.z))).toFixed(1) : null,
          y: list.map(m => Math.round(m.p.y)),
          burst: list.map(m => m.burstN | 0),
          knockable: !(MOB_DEFS[k] && MOB_DEFS[k].noKnock),
        };
      }
      const col = mobs.find(m => m.kind === 'ancientColossus');
      out.chillT = +(player.chillT || 0).toFixed(2);
      out.colossusInDeepslate = col ? (getBlock(Math.floor(col.p.x), Math.floor(col.p.y) - 1, Math.floor(col.p.z)) === 50) : null;
      out.spots = {
        snow: findBiomeMobSpot('frostWisp'), badlands: findBiomeMobSpot('cactusBrute'),
        savanna: findBiomeMobSpot('thornsniper'), deepCave: findDeepCaveSpot(),
      };
      out.caps = { frostWisp: 2, cactusBrute: 2, thornsniper: 2, ancientColossus: 1 };
      return out;
    },
    mobsInfo: () => mobs.map(m => ({
      kind: m.kind, hp: m.hp, dying: m.dying, dieT: +m.dieT.toFixed(2), scale: +m.obj.scale.x.toFixed(3),
      tilt: +m.parts.core.rotation.x.toFixed(2), dist: +m.p.distanceTo(player.p).toFixed(2),
      aggro: +m.aggro.toFixed(1), flash: +m.flash.toFixed(2),
      barVisible: m.parts.bar.visible, barScale: +m.parts.barFg.scale.x.toFixed(2),
    })),
    treeSample(n = 400, x0 = 0, z0 = 0) {
      const kinds = { oak: 0, pine: 0, bush: 0, none: 0 };
      const heights = [], radii = [];
      for (let i = 0; i < n; i++) {
        for (let j = 0; j < 40; j++) {
          const t = treeParams(x0 + i * 7 + j * 13, z0 + j * 17 - i * 5);
          if (t) { kinds[t.kind]++; heights.push(t.trunkH); radii.push(t.r); break; }
          kinds.none++;
        }
      }
      const uniqH = [...new Set(heights)].sort();
      const uniqR = [...new Set(radii)].sort();
      return { kinds, trunkHeights: uniqH, radii: uniqR, samples: heights.length };
    },
    killMobs() { for (const m of mobs) killMob(m); mobs.length = 0; },
    seek(x, z) { player.p.x = x + 0.5; player.p.z = z + 0.5; player.p.y = surfaceY(x, z) + 1.2; player.v.set(0, 0, 0); },
    scanColumn(x, z) { const out = []; for (let y = CFG.WH - 1; y >= 0; y--) { const id = getBlock(x, y, z); if (id) out.push([y, nameOf(id)]); } return out; },
    findBlock(id, r = 24) {
      const px = Math.floor(player.p.x), pz = Math.floor(player.p.z);
      for (let d = 0; d < r; d++) for (let dx = -d; dx <= d; dx++) for (let dz = -d; dz <= d; dz++) {
        if (Math.max(Math.abs(dx), Math.abs(dz)) !== d) continue;
        for (let y = CFG.WH - 1; y > 0; y--) if (getBlock(px + dx, y, pz + dz) === id) return [px + dx, y, pz + dz];
      }
      return null;
    },
    counts() {
      const c = {};
      for (const ch of chunks.values()) for (const id of ch.blocks) if (id) c[nameOf(id)] = (c[nameOf(id)] || 0) + 1;
      return c;
    },
    // 截图用：WebGL 缓冲在合成后会被清空，必须同步重绘一次再取 toDataURL
    snapshot() {
      renderer.clear();
      renderer.render(scene, camera);
      renderer.clearDepth();
      renderer.render(handScene, handCam);
      return renderer.domElement.toDataURL();
    },
    save: () => save(),
    newWorld: () => newWorld(),
  },
};

/* ============================================================ 账号 + 多人游戏（MC 式入口）
 * 为什么要账号：好友、房间列表、跨设备的世界都需要一个稳定身份。
 *   · 登录后：昵称 = 账号昵称，pid = 账号 pid → 换设备还是同一个人，好友/世界都在
 *   · 不登录：照样单机玩，但【进不了联机】，世界只在这台机器的 localStorage 里（换设备就没了）
 * 界面结构（照 MC 的「多人游戏」）：服务器列表 / 直连 / 好友 三个页签 + 顶上一行账号状态。
 */
const ACCT_KEY = 'bw_acct_v1';
const ACCT = { user: '', tok: '', pid: '', nick: '', worlds: [], on: false };
/* 账号接口地址：**加载时算一次就固定**。
   ★ 不能每次现算：联机层进服后会 history.replaceState 把 ?net=/?mp= 洗掉，
     之后再算就只剩默认值（局域网试的时候会打到没开的 9203 端口上 → Failed to fetch）。 */
const ACCT_EP = (() => {
  let base = new URLSearchParams(location.search).get('net');
  if (!base) {
    const h = location.hostname;
    const LAN = /^(localhost|127\.|192\.168\.|10\.|172\.(1[6-9]|2\d|3[01])\.)/.test(h);
    base = (location.protocol === 'https:' || !LAN)
      ? (location.pathname.replace(/[^/]*$/, '') + 'bwmp.php')
      : ('http://' + h + ':9203');
  }
  return /\.php(\?|$)/.test(base) ? base : base.replace(/\/+$/, '') + '/api';
})();
function acctEP() { return ACCT_EP; }
function acctApi(obj) {
  return fetch(acctEP(), { method: 'POST', headers: { 'content-type': 'text/plain' }, body: JSON.stringify(obj) })
    .then(r => r.json());
}
function acctSave() {
  try { localStorage.setItem(ACCT_KEY, JSON.stringify({ user: ACCT.user, tok: ACCT.tok, pid: ACCT.pid, nick: ACCT.nick })); } catch (e) {}
}
function acctLoad() {
  try {
    const d = JSON.parse(localStorage.getItem(ACCT_KEY) || 'null');
    if (d && d.tok) { ACCT.user = d.user || ''; ACCT.tok = d.tok; ACCT.pid = d.pid || ''; ACCT.nick = d.nick || ''; ACCT.on = true; }
  } catch (e) {}
}
function acctApply(d) {
  if (!d || !d.ok) return false;
  ACCT.user = d.user || ACCT.user; ACCT.pid = d.pid || ACCT.pid;
  ACCT.tok = d.tok || ACCT.tok; ACCT.nick = d.nick || ACCT.nick;
  ACCT.worlds = Array.isArray(d.worlds) ? d.worlds : ACCT.worlds;
  ACCT.on = !!ACCT.tok;
  if (ACCT.nick) { LOOK.name = ACCT.nick; saveLook(); }     // 联机昵称跟账号走，好友才能按昵称找到你
  acctSave();
  if (PENDING_JOIN) { const c = PENDING_JOIN; PENDING_JOIN = ''; setTimeout(() => mpJoinRoom(c), 400); }
  return true;
}
function acctLogout() {
  ACCT.user = ''; ACCT.tok = ''; ACCT.pid = ''; ACCT.worlds = []; ACCT.on = false;
  try { localStorage.removeItem(ACCT_KEY); } catch (e) {}
  if (window.NET && window.NET.leave) { try { window.NET.leave(false); } catch (e) {} }
}
const acctTok = () => ACCT.tok;

/* ?join=房间码：别人发的「一键加入」链接。已登录就直接进；没登录先记住，登录成功后自动继续。 */
let PENDING_JOIN = (new URLSearchParams(location.search).get('join') || '').replace(/[^\w-]/g, '').toUpperCase().slice(0, 12);
/* 一次性：把 ?join= 从地址栏摘掉（值已经存进变量），刷新/恢复标签页不会重复发申请或重复进房 */
if (PENDING_JOIN) {
  try {
    const u = new URL(location.href); u.searchParams.delete('join');
    history.replaceState(null, '', u.pathname + (u.search || ''));
  } catch (e) {}
}
acctLoad();
if (ACCT.on) {                                    // 带着令牌回来 → 静默校验一次，顺便刷新账号世界
  setTimeout(() => {
    acctApi({ a: 'whoami', tok: ACCT.tok }).then(d => {
      if (d && d.ok) { ACCT.worlds = d.worlds || []; if (d.nick) { ACCT.nick = d.nick; LOOK.name = d.nick; saveLook(); } acctSave(); if (MPUI.ready) MPUI.render(); }
      else { ACCT.on = false; try { localStorage.removeItem(ACCT_KEY); } catch (e) {} if (MPUI.ready) MPUI.render(); }
    }).catch(() => {});
  }, 600);
}

const MPUI = {
  root: null, tab: 'friend', rooms: [], friends: [], req: [], inv: [], msg: '', busy: false, ready: false,
  _seenReq: new Set(), _acctMode: null, _reqN: 0,
  /* ★ 我发出去的加入申请（本地记住，刷新页面也还在 —— 好友可能在十几秒后才点同意） */
  waiting: (() => { try { return JSON.parse(sessionStorage.getItem('bw_joinwait_v1') || 'null'); } catch (e) { return null; } })(),
  setWait(w) {
    this.waiting = w && w.pid ? w : null;
    try { w && w.pid ? sessionStorage.setItem('bw_joinwait_v1', JSON.stringify(w)) : sessionStorage.removeItem('bw_joinwait_v1'); } catch (e) {}
  },
  ensure() {
    if (this.root) return this.root;
    const d = document.createElement('div');
    d.className = 'overlay hide'; d.id = 'mpPanel';
    d.style.zIndex = '60';
    d.innerHTML =
      '<div class="card" style="max-width:660px;width:min(94vw,660px)">'
      + '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px">'
      +   '<div class="sec" style="border:0;margin:0">Multiplayer</div>'
      +   '<div style="display:flex;gap:8px;align-items:center"><span id="mpAcctLine" style="font-size:12px;color:#9fb3c8"></span>'
      +   '<button class="btn" id="mpClose">Back</button></div>'
      + '</div>'
      + '<div id="mpAcctBox" style="background:rgba(120,200,255,.07);border:1px solid rgba(120,200,255,.22);border-radius:9px;padding:8px 10px;margin-bottom:10px"></div>'
      + '<div style="display:flex;gap:6px;margin-bottom:10px;align-items:center">'
      +   '<button class="btn" data-mp="tab:friend">Friends</button>'
      +   '<button class="btn" data-mp="tab:mine">My Worlds</button>'
      +   '<span id="mpWait" style="font-size:12px;color:#ffcf6b"></span>'
      +   '<span style="flex:1"></span><span id="mpPing" style="font-size:11px;color:#7a8b9c;align-self:center"></span>'
      + '</div>'
      + '<div id="mpBody" style="min-height:230px"></div>'
      + '<div id="mpMsg" style="color:#ffcf6b;font-size:12px;min-height:16px;margin-top:8px"></div>'
      + '</div>';
    document.body.appendChild(d);
    d.querySelector('#mpClose').onclick = () => MPUI.hide();
    d.addEventListener('click', ev => {
      const b = ev.target.closest('button[data-mp]');
      if (!b) return;
      const [k, v] = String(b.dataset.mp).split(':');
      MPUI.act(k, v, b);
    });
    this.root = d; this.ready = true;
    return d;
  },
  show(tab) {
    this.ensure();
    /* 老入口（世界列表里的「联机」、?mp=1 链接、旧的服务器列表/直连页签）一律汇到「好友」页：
       联机现在只有一条路 —— 加好友 → 申请加入 → 好友同意 → 房间自动开好。 */
    const t = (tab === 'list' || tab === 'direct') ? 'friend' : tab;
    if (t) this.tab = t;
    this.root.classList.remove('hide');
    this.root.style.display = '';
    this.render();
    if (this.tab === 'friend') this.pullFriends();
    else this.pullRooms();
    if (window.__bwMPSync) window.__bwMPSync(true);
  },
  hide() {
    if (!this.root) return;
    this.root.classList.add('hide');
    /* ★ 必须同时写内联 display:none。以前只加 class —— 而旧的联机面板代码
       （renderFriends / onSocial('inv')）会直接 `frPanel.style.display='block'`，
       内联样式优先级高于 class → 之后再点「返回」根本关不掉（收到加入申请时必现）。
       现在两处都堵：hide 写内联 none，旧代码也改成走 MPUI.show()。 */
    this.root.style.display = 'none';
    this.closedAt = Date.now();                 // 记一下「用户刚关掉」：60 秒内不自动弹回来
    if (window.__bwMPSync) window.__bwMPSync(false);
  },
  /* 「收到加入申请」时的自动弹出：用户刚关过面板就先不弹（toast 提示 + 好友按钮上有个数字），
     免得关掉→又弹→关掉→又弹，看起来像「关不掉」。 */
  autoShow() {
    if (Date.now() - (this.closedAt || 0) < 60000) return false;
    this.show('friend');
    return true;
  },
  msg2(t) { this.msg = t || ''; const el = this.root && this.root.querySelector('#mpMsg'); if (el) el.textContent = this.msg; },
  setFriends(d) {
    if (!d) return;
    if (Array.isArray(d.friends)) this.friends = d.friends;
    if (Array.isArray(d.inv)) this.inv = d.inv;
    if (Array.isArray(d.req) && d.req.length) this.req = d.req;
    if (Array.isArray(d.worlds)) ACCT.worlds = d.worlds;
    /* ★ 被拒绝：服务端会带一条 den（取走即清）。收到就把「等待同意」撤掉——
       以前只靠 ws 推 deny，走轮询/没连上的时候这条永远收不到，界面就卡在等待上。 */
    if (Array.isArray(d.den) && d.den.length) {
      const w = this.waiting;
      const hit = d.den.find(x => w && x.from === w.pid) || d.den[0];
      if (hit && (!w || hit.from === w.pid)) { this.setWait(null); this.render(); }
      if (hit) toast((hit.nick || 'They') + ' declined your join request', 4);
    }
  },
  pullRooms() {
    /* 延迟别用 performance.now() 前后差：无头/卡顿的页面里量到的是「事件循环 + 渲染帧」，
       实测把局域网量成 987ms、把北京时间差量成 1492ms。取 Resource Timing 的 duration 才是真耗时。 */
    acctApi({ a: 'rooms' }).then(d => {
      let ms = null;
      try {
        const es = performance.getEntriesByType('resource').filter(e => e.name.indexOf('bwmp.php') >= 0 || e.name.indexOf(':9203') >= 0);
        const last = es[es.length - 1];
        if (last && last.duration > 0) ms = Math.round(last.duration);
      } catch (e) {}
      if (!d || !d.ok) { this.rooms = []; }
      else { this.rooms = d.rooms || []; }
      const el = this.root && this.root.querySelector('#mpPing');
      if (el) el.textContent = ms ? ('Server ' + ms + 'ms') : 'Server online';
      this.render();
    }).catch(() => { this.rooms = []; const el = this.root && this.root.querySelector('#mpPing'); if (el) el.textContent = 'Cannot reach the server'; this.render(); });
  },
  pullFriends() {
    if (!ACCT.on) return;
    /* 用 acct 而不是 friends：friends 是「取走即清」，面板一刷新就把服务端的加入申请队列清空了
       （房主关掉面板再打开就看不到刚才那条申请）。 */
    acctApi({ a: 'acct', tok: ACCT.tok, pid: ACCT.pid, nick: ACCT.nick, code: (window.NET && window.NET.code) || '',
              pworld: (window.NET && NET.active) ? NET.code : mpCurrentCode() })
      .then(d => { if (d && d.ok) { this.setFriends(d); this.render(); } }).catch(() => {});
  },
  act(k, v, btn) {
    const NET = window.NET;
    if (k === 'tab') { this.tab = (v === 'list' || v === 'direct') ? 'friend' : v; this.render(); if (this.tab === 'friend') this.pullFriends(); return; }
    if (k === 'login' || k === 'reg') return this.doAuth(k);
    if (k === 'logout') { acctLogout(); this.render(); return this.msg2('Signed out (now in single-player mode)'); }
    if (k === 'refresh') return this.pullFriends();
    if (k === 'reload') return this.pullFriends();
    if (k === 'join') return mpJoinRoom(btn.dataset.code);
    if (k === 'joinAcc') return mpEnterAccountWorld(btn.dataset.code);
    if (k === 'direct') return this.doDirect();
    if (k === 'copy') { if (window.__bwMP && window.__bwMP.copy) return window.__bwMP.copy(); return this.msg2('Join a room first to get an invite link'); }
    if (k === 'leave') { if (window.__bwMP && window.__bwMP.leave) return window.__bwMP.leave(); return this.msg2('You are not in a room right now'); }
    if (k === 'tp') { if (window.__bwMP && window.__bwMP.tp) window.__bwMP.tp(btn.dataset.id); return; }
    if (k === 'fadd') return this.doAddFriend();
    /* ★ 申请加入：唯一进别人的世界的入口。等好友点「同意」，他那边会自动开房，我这边自动进。 */
    if (k === 'jreq') {
      const pid = btn.dataset.pid, nick = btn.dataset.nick || '';
      this.setWait({ pid, nick, at: Date.now() });
      this.render();
      acctApi({ a: 'jreq', tok: ACCT.tok, pid: ACCT.pid, nick: ACCT.nick, to: pid }).then(d => {
        if (d && d.ok) return this.msg2('Sent a join request to ' + (nick || 'your friend') + ' — once they click Accept, you will join automatically');
        this.setWait(null); this.render();
        this.msg2({ offline: 'They are offline (ask again while they are in the game)', not_friend: 'Not friends yet', need_login: 'Please sign in first' }[d && d.e] || ('Request failed: ' + (d && d.e)));
      }).catch(() => { this.setWait(null); this.render(); this.msg2('Network error'); });
      return;
    }
    if (k === 'waitcancel') {
      const w = this.waiting;
      this.setWait(null); this.render();
      if (w && w.pid) acctApi({ a: 'jcancel', tok: ACCT.tok, pid: ACCT.pid, nick: ACCT.nick, to: w.pid }).catch(() => {});
      return this.msg2('Waiting cancelled' + (w && w.nick ? '（' + w.nick + ' the request there was withdrawn too)' : ''));
    }
    if (k === 'jres') {
      const ok = btn.dataset.ok === '1', from = btn.dataset.from;
      if (!ok) return this.soc({ a: 'jres', from, ok: false }, 'Denied');
      /* ★ 同意 = 自动开房：先把「要开成房间的世界码」告诉服务端（= 给申请人发通行证），
         再把自己切进联机房主模式。对方那边收到推送/轮询到通行证就自动进来，全程不用点「开房」。 */
      const NET0 = window.NET;
      if (NET0 && NET0.active && !NET0.isHost) return this.msg2('You are in someone else\'s room: click Leave Multiplayer first, then Accept');
      const code = mpCurrentCode() || mpHostTargetCode();
      acctApi({ a: 'jres', tok: ACCT.tok, pid: ACCT.pid, nick: ACCT.nick, from, ok: true, code }).then(d => {
        if (!d || !d.ok) {
          return this.msg2({ no_world: 'Enter a world first, then Accept (My Worlds → Enter)', need_login: 'Please sign in first' }[d && d.e] || ('Action failed: ' + (d && d.e)));
        }
        this.msg2('Accepted — opening this world as a room ' + code + ' …');
        setTimeout(() => mpAutoHost(code), 200);
      }).catch(() => this.msg2('Network error'));
      return;
    }
    if (k === 'invite') {
      const code = (NET && NET.active) ? NET.code : '';
      if (!code) return this.msg2('Join a room before inviting people');
      return this.soc({ a: 'invite', to: btn.dataset.pid, code }, 'Invite sent, they will join automatically');
    }
  },
  doAuth(kind) {
    const q = id => (this.root.querySelector('#' + id).value || '').trim();
    const user = q('mpUser'), pass = q('mpPass'), nick = q('mpNick');
    if (!user || !pass) return this.msg2('Enter both username and password');
    this.msg2(kind === 'reg' ? 'Signing up…' : 'Signing in…');
    acctApi({ a: kind, user, pass, nick: nick || '' }).then(d => {
      if (!d || !d.ok) {
        return this.msg2({ bad_user: 'Username must be 3-16 lowercase letters/digits/underscores', bad_pass: 'Password must be at least 4 characters',
          taken: 'That username is already taken', no_user: 'No such account', need_login: 'Please sign in first' }[d && d.e] || ('Failed: ' + (d && d.e)));
      }
      acctApply(d); this.msg2(kind === 'reg' ? 'Signed up and signed in' : 'Signed in'); this.render(); this.pullFriends();
    }).catch(() => this.msg2('Cannot reach the account server'));
  },
  doAddFriend() {
    const el = this.root.querySelector('#mpFriend'); const t = el ? el.value.trim() : '';
    if (!t) return this.msg2('Enter your friend\'s nickname');
    acctApi({ a: 'fadd', tok: ACCT.tok, pid: ACCT.pid, nick: ACCT.nick, target: t }).then(d => {
      if (d && d.ok) { this.msg2('Friend added: ' + d.friend.nick + (d.friend.online ? '(online)' : '(offline)')); if (el) el.value = ''; this.pullFriends(); }
      else this.msg2({ no_user: 'No such nickname', self: 'You cannot add yourself', need_login: 'Please sign in first' }[d && d.e] || 'Failed to add friend');
    }).catch(() => this.msg2('Network error'));
  },
  soc(body, okText) {
    acctApi(Object.assign({ tok: ACCT.tok, pid: ACCT.pid, nick: ACCT.nick, code: (window.NET && window.NET.code) || '' }, body)).then(d => {
      this.msg2(d && d.ok ? okText : ({ not_friend: 'Not friends yet', offline: 'They are offline', need_login: 'Please sign in first', no_room: 'Open a room before inviting' }[d && d.e] || 'Action failed: ' + (d && d.e)));
      if (d && d.ok) setTimeout(() => this.pullFriends(), 400);
    }).catch(() => this.msg2('Network error'));
  },
  doDirect() {
    const el = this.root.querySelector('#mpCode2');
    const code = (el ? el.value : '').trim();
    if (!code) return this.msg2('Enter the room code first');
    mpJoinRoom(code);
  },
  render() {
    if (!this.root) return;
    /* ★ 轮询（5s）也会 render，而 render 会重建 #mpBody —— 用户正在输入的好友昵称/房间码
       就被擦掉了（"输一半字就没了"）。重建前先记下所有输入框的值，重建后补回去。 */
    const keep = {};
    for (const id of ['mpFriend', 'mpCode2', 'mpAddr', 'mpUser', 'mpPass', 'mpNick']) {
      const el = this.root.querySelector('#' + id);
      if (el) keep[id] = el.value;
    }
    const NET = window.NET;
    const on = ACCT.on;
    const acctLine = this.root.querySelector('#mpAcctLine');
    if (acctLine) acctLine.innerHTML = on ? '<b style="color:#7ef0a0">● ' + escHtml(ACCT.nick || ACCT.user) + '</b>'
                                          : '<span style="color:#ffcf6b">Not signed in · single-player only</span>';
    // 账号区
    const box = this.root.querySelector('#mpAcctBox');
    /* ★ 只在「登录状态变了」的时候重建这一块：每次 render 都重建会把用户正在输入的用户名/密码清空
       （列表刷新、切页签都会 render，表现就是点了登录提示"用户名和密码都要填"）。 */
    if (box && this._acctMode !== (on ? 'in' : 'out')) {
      this._acctMode = on ? 'in' : 'out';
      box.innerHTML = on
        ? '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px">'
          + '<span>Account <b style="color:#8fe3ff">' + escHtml(ACCT.user || ACCT.nick) + '</b> · Nickname ' + escHtml(ACCT.nick)
          + '<span style="color:#7a8b9c"> · Friends/worlds follow your account, so a device change loses nothing</span></span>'
          + '<button class="btn" data-mp="logout" style="padding:3px 8px">Sign out</button></div>'
        : '<div style="font-size:12px;line-height:1.6;margin-bottom:6px;color:#9fb3c8">'
          + 'You can play <b>single-player</b> without signing in, but <b style="color:#ffcf6b">worlds are lost when you change devices and Multiplayer is unavailable</b>. Sign in and your friends and worlds follow your account.</div>'
          + '<div style="display:flex;gap:6px;flex-wrap:wrap">'
          + '<input id="mpUser" placeholder="Username (3-16 lowercase letters/digits)" maxlength="16" style="flex:1;min-width:150px;"' + PCB2 + '">'
          + '<input id="mpPass" type="password" placeholder="Password" maxlength="40" style="flex:1;min-width:120px;"' + PCB2 + '">'
          + '<input id="mpNick" placeholder="Nickname (optional)" maxlength="14" style="width:130px;"' + PCB2 + '">'
          + '<button class="btn gold" data-mp="login" style="padding:4px 10px">Sign in</button>'
          + '<button class="btn" data-mp="reg" style="padding:4px 10px">Sign up</button></div>';
    }
    // 页签高亮
    for (const b of this.root.querySelectorAll('button[data-mp^="tab:"]')) {
      const t = b.dataset.mp.split(':')[1];
      b.style.borderColor = t === this.tab ? '#f5c451' : '';
      b.style.color = t === this.tab ? '#f5c451' : '';
    }
    const body = this.root.querySelector('#mpBody');
    if (!body) return;
    const waitEl = this.root.querySelector('#mpWait');
    if (waitEl) waitEl.textContent = this.waiting ? ('Waiting for ' + (this.waiting.nick || 'your friend') + ' to accept…') : '';
    if (!on) {
      body.innerHTML = '<div style="color:#9fb3c8;line-height:1.7">After signing in you will see here:<br>'
        + '· <b>Friends</b>: add friends, see who is online, click <b>Ask to join</b> → they click <b>Accept</b>, the room opens automatically and you join<br>'
        + '· <b>My Worlds</b>: even mid-game a friend can ask to join (no room code, no need to open a room first)<br>'
        + '<span style="color:#7a8b9c">(not signed in = single-player only: worlds stay on this device and are gone on a device change)</span></div>';
      return;
    }
    if (this.tab === 'mine') body.innerHTML = this.htmlMine(NET);
    else body.innerHTML = this.htmlFriend(NET);
    for (const id in keep) {                          // 把刚输入的内容放回新 DOM
      const el = this.root.querySelector('#' + id);
      if (el && !el.value) el.value = keep[id];
    }
  },
  /* 「我的世界」页签：账号里的世界直接进去玩。这里**没有开房按钮** ——
     房间是好友被同意加入时自动开的，玩家不需要知道房间码。 */
  htmlMine(NET) {
    const inRoom = !!(NET && NET.active);
    const mine = (ACCT.worlds || []).map(w =>
      '<div style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-top:1px solid rgba(120,200,255,.14)">'
      + '<span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'
      + '<b style="color:#f5c451">' + escHtml(w.name || w.code) + '</b></span>'
      + '<span style="width:92px;color:#9fb3c8;font-size:11px">' + (w.players ? w.players + ' players' : 'Saves in the cloud') + '</span>'
      + '<button class="btn" data-mp="joinAcc" data-code="' + escHtml(w.code) + '" style="padding:2px 9px">'
      +   (w.players ? 'Continue (in Multiplayer)' : 'Enter') + '</button></div>').join('');
    return '<div style="color:#9fb3c8;font-size:12px;line-height:1.65;margin-bottom:8px">'
      + 'Worlds in your account — <b style="color:#8fe3ff">click Enter to play</b>. While you play, a friend can ask to join from the Friends tab,'
      + 'you click <b>Accept</b> and this world becomes a room automatically, they join — no room code, no "open room" step.</div>'
      + (mine || '<div style="color:#7a8b9c;padding:6px 4px">No worlds yet. Go back to the start screen, make a world and play a bit — it will be saved to your account automatically.</div>')
      + (inRoom ? '<div style="margin-top:12px;color:#7ef0a0;font-size:12px">● In a room now <b>' + escHtml(NET.code) + '</b>'
        + ' <button class="btn" data-mp="leave" style="padding:2px 9px;color:#ffb0b0;border-color:#5a2b2b">Leave Multiplayer</button></div>' : '');
  },
  htmlFriend(NET) {
    const q = PCB2;
    const inRoom = !!(NET && NET.active);
    const isHost = !!(NET && NET.isHost);
    const nlive = inRoom ? (1 + ((NET.remotes && NET.remotes.size) || 0)) : 0;
    const wait = this.waiting;
    const status = inRoom
      ? '<div style="background:rgba(126,240,160,.08);border:1px solid rgba(126,240,160,.3);border-radius:9px;padding:7px 9px;margin-bottom:9px;display:flex;justify-content:space-between;align-items:center;gap:8px">'
        + '<span>● You are in a room <b style="color:#8fe3ff">' + escHtml(NET.code) + '</b> · ' + nlive + ' players'
        + (isHost ? ' · <b style="color:#f5c451">You are the host</b> (a friend\'s request opens it automatically)' : '') + '</span>'
        + '<button class="btn" data-mp="leave" style="padding:3px 9px;color:#ffb0b0;border-color:#5a2b2b">Leave Multiplayer</button></div>'
      : '<div style="background:rgba(120,200,255,.07);border:1px solid rgba(120,200,255,.22);border-radius:9px;padding:7px 9px;margin-bottom:9px;font-size:12px;color:#9fb3c8">'
        + 'Not in a room. Click <b style="color:#8fe3ff">Ask to join</b> next to a friend; once they accept, the room opens automatically and you join.</div>';
    const reqRows = (this.req || []).map(r =>
      '<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:4px">'
      + '<span>' + escHtml(r.nick) + ' wants to join your World</span>'
      + '<span><button class="btn gold" data-mp="jres" data-from="' + escHtml(r.from) + '" data-ok="1" style="padding:2px 7px">Accept</button>'
      + '<button class="btn" data-mp="jres" data-from="' + escHtml(r.from) + '" data-ok="0" style="padding:2px 7px">Deny</button></span></div>').join('');
    const waitRow = wait
      ? '<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:4px;color:#ffcf6b">'
      + '<span>Asked <b>' + escHtml(wait.nick || 'your friend') + '</b> to join — waiting for them to tap "Accept"… (the Room opens automatically)</span>'
      + '<button class="btn" data-mp="waitcancel" style="padding:2px 7px">Cancel</button></div>'
      : '';
    const invRows = (this.inv || []).map(v =>
      '<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:4px;color:#ffcf6b">'
      + '<span>' + escHtml(v.nick) + ' invited you to their World</span>'
      + '<button class="btn gold" data-mp="join" data-code="' + escHtml(v.code) + '" style="padding:2px 7px">Join</button></div>').join('');
    const fs = (this.friends || []).map(f => {
      let btn;
      if (inRoom) btn = isHost
        ? '<button class="btn" data-mp="invite" data-pid="' + escHtml(f.pid) + '" style="padding:2px 7px">Invite to Room</button>'
        : '<span style="color:#7a8b9c;font-size:11px">Only the host can invite</span>';
      else if (!f.online) btn = '<span style="color:#7a8b9c;font-size:11px">Offline</span>';
      else if (wait && wait.pid === f.pid) btn = '<button class="btn" data-mp="waitcancel" style="padding:2px 7px">Waiting for Accept… (tap to cancel)</button>';
      else btn = '<button class="btn gold" data-mp="jreq" data-pid="' + escHtml(f.pid) + '" data-nick="' + escHtml(f.nick) + '" style="padding:2px 7px">Ask to join</button>';
      return '<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;padding:4px 0;border-top:1px solid rgba(120,200,255,.12)">'
        + '<span><b style="color:' + (f.online ? '#7ef0a0' : '#7a8b9c') + '">' + (f.online ? '●' : '○') + '</b> ' + escHtml(f.nick)
        + '<span style="color:#7a8b9c;font-size:11px">' + (f.online ? (f.world ? ' · Playing ' + escHtml(f.world) : ' · Online') : ' · Offline') + '</span></span>'
        + btn + '</div>';
    }).join('');
    return status
      + (reqRows ? '<div style="color:#ffcf6b;margin-bottom:3px">Join request (tap Accept → the Room opens and they come in)</div>' + reqRows : '')
      + waitRow
      + (invRows ? '<div style="color:#ffcf6b;margin:6px 0 3px">Room invite</div>' + invRows : '')
      + '<div style="display:flex;gap:6px;margin:8px 0">'
      + '<input id="mpFriend" placeholder="Friend\'s in-game name" maxlength="14" style="flex:1;' + q + '">'
      + '<button class="btn" data-mp="fadd" style="padding:4px 10px">Add friend</button>'
      + '<button class="btn" data-mp="reload" style="padding:4px 8px">Refresh</button></div>'
      + '<div style="color:#9fb3c8;font-size:12px;margin-top:6px">Friends (' + (this.friends || []).length + '）</div>'
      + (fs || '<div style="color:#7a8b9c;padding:6px 0">No friends yet — enter their name above to add one</div>')
      + '<details style="margin-top:12px"><summary style="color:#7a8b9c;font-size:11px;cursor:pointer">Advanced: join by Room code / invite link</summary>'
      + '<div style="display:flex;gap:6px;margin-top:6px"><input id="mpCode2" placeholder="Room code" maxlength="12" style="flex:1;' + q + '">'
      + '<button class="btn" data-mp="direct" style="padding:4px 10px">Ask to join</button></div>'
      + '<div style="color:#7a8b9c;font-size:11px;line-height:1.6;margin-top:4px">A Room code still needs the host\'s Accept (it sends them a request automatically).</div>'
      + (inRoom ? '<div style="margin-top:6px"><button class="btn" data-mp="copy">Copy invite link</button></div>' : '')
      + '</details>';
  },
};
const PCB2 = 'background:#0e1a28;color:#d8ecff;border:1px solid #2a4a66;border-radius:6px;padding:4px 6px;font:12px ui-monospace,monospace';

/* 验收/排障用探针（控制台可读，和 GAME.debug 一样只是"看"，不提供改档能力） */
window.BW = { ACCT, MPUI, acctApi, acctEP, mpJoinRoom, mpEnterAccountWorld, mpSaveWorld, mpRoomCodeOf };

/* 世界 → 房间码（同一个世界永远是同一个码）。存档、开房、账号世界都用这一个公式。 */
function mpRoomCodeOf(w) {
  if (!w) return '';
  if (!w.mpCode) {
    w.mpCode = 'R' + (Math.abs(hashString('room:' + w.id)) % 1679616).toString(36).toUpperCase().padStart(4, '0');
    const m = worldMeta(w.id);
    if (m) { m.mpCode = w.mpCode; saveIndex(); }
  }
  return w.mpCode;
}
/* 把世界登记到账号下面（换设备登录后能在「我的世界」里看到它）。
   存档很频繁 → 30 秒节流，失败静默（联机/账号服务器没开也不影响单机存档）。 */
let mpWsaveT = 0;
function mpSaveWorld(meta) {
  if (!ACCT.on || !meta) return;
  const now = Date.now();
  if (now - mpWsaveT < 30000) return;
  mpWsaveT = now;
  const code = mpRoomCodeOf(meta);
  if (!code) return;
  acctApi({ a: 'wsave', tok: ACCT.tok, world: {
    id: meta.id, code, name: meta.name || '', seed: meta.seed | 0, mode: meta.mode || 'survival',
  } }).then(d => { if (d && d.ok) { ACCT.worlds = d.worlds || ACCT.worlds; acctSave(); } }).catch(() => {});
}

/* 单机进世界时，把「云端房间里好友改过」的方块补到本机（只补本机没有的格子 → 不吃掉自己的离线改动）*/
function mpPullWorldEdits(world) {
  if (!ACCT.on || !world || !world.id || String(world.id).indexOf('mp_') === 0) return;
  if (window.NET && NET.active) return;                 // 联机里由 join/region 负责
  const code = mpRoomCodeOf(world);
  if (!code) return;
  acctApi({ a: 'edits', code }).then(d => {
    if (!d || !d.ok || !started || currentId !== world.id) return;
    if (!(d.edits || []).length) return;
    let add = 0;
    for (const e of d.edits) {
      const k = String(e[0]);
      if (!/^-?\d+,-?\d+,-?\d+$/.test(k)) continue;
      if (edits.has(k)) continue;                       // 本机已有这格 → 本机为准
      const p = k.split(',').map(Number);
      edits.set(k, e[1] | 0); indexEdit(p[0], p[1], p[2], e[1] | 0);
      add++;
    }
    if (!add) return;
    for (const [k2, cc] of Array.from(chunks)) {        // 已生成的区块要重建才看得见
      if (cc.mesh) scene.remove(cc.mesh);
      if (cc.glass) scene.remove(cc.glass);
      if (cc.water) scene.remove(cc.water);
      if (cc.plant) scene.remove(cc.plant);
      chunks.delete(k2);
    }
    const c0x = Math.floor(player.p.x / CFG.CH), c0z = Math.floor(player.p.z / CFG.CH);
    for (let dx = -2; dx <= 2; dx++) for (let dz = -2; dz <= 2; dz++) dirty.add(getChunk(c0x + dx, c0z + dz));
    toast('Synced ' + add + ' blocks changed by friends in the cloud Room', 5);
    saveSoon();
  }).catch(() => {});
}

/* 加入别人的世界。
 * 联机现在只有一条路：**房主同意过**才进得去（服务端 join 只认这张通行证），
 * 所以这里没有「先进房间列表挑一个」的玩法：
 *   · 已经被同意、房间也开好了 → 直接跳进去
 *   · 还没同意 → 自动给对方发一条加入申请，然后每 1.5 秒问一次「能进了吗」
 *   · 对方点「同意」的瞬间，他那边自动开房，我这边下一次轮询就自动继续进（全程不用再点）
 */
function mpGoRoom(code) {
  MPUI.setWait(null);
  /* 进房前把「已同意」这张一次性通知用掉：不然刷新/重开网站时它还在账号里，
     又会被自动消费一次 → 用户看到「打开网站就自动进房间」。
     用 sendBeacon（页面马上要跳走，普通 fetch 会被取消）。 */
  try {
    const body = JSON.stringify({ a: 'ivdone', tok: ACCT.tok, code });
    if (navigator.sendBeacon) navigator.sendBeacon(acctEP(), new Blob([body], { type: 'text/plain' }));
    else acctApi({ a: 'ivdone', tok: ACCT.tok, code }).catch(() => {});
  } catch (e) {}
  mpNavTo(location.pathname + '?mp=1&go=1&world=' + encodeURIComponent(code)
    + '&nick=' + encodeURIComponent(ACCT.nick || LOOK.name));
}
/* 跳去联机前打一个「本标签页刚点过加入」的一次性令牌。
   ★ 只靠 URL 里的 go=1 判断「要不要自动进服」有两个坑：
     ① 地址栏留着 go=1（联机失败/被切后台时 replaceState 没跑到）→ 刷新、浏览器恢复标签页又自动进一次；
     ② 有人把带 go=1 的地址存成书签/收藏 → 每次打开都当「刚点了加入」。
   令牌存在 sessionStorage（只在本标签页、只生效一次），书签和老地址都不会带。 */
function mpNavTo(href) {
  try { sessionStorage.setItem('bw_go', '1'); } catch (e) {}
  location.href = href;
}
function mpJoinRoom(code, tries) {
  if (!ACCT.on) { MPUI.show('friend'); return MPUI.msg2('Sign in to play Multiplayer'); }
  const c = String(code || '').trim().replace(/[^\w-]/g, '').toUpperCase();
  if (!c) return MPUI.msg2('Enter the room code first');
  const n = tries | 0;
  acctApi({ a: 'canjoin', tok: ACCT.tok, code: c }).then(d => {
    if (!d || !d.ok) { MPUI.msg2((d && d.e === 'need_login') ? 'Sign in to play Multiplayer' : 'Cannot reach the server'); return; }
    if (d.mine) { mpEnterAccountWorld(c); return; }            // 自己的房间：以房主身份进去
    if (d.pass && d.exists) { MPUI.msg2('Accepted — entering ' + c + ' …'); mpGoRoom(c); return; }
    if (d.pass && !d.exists) {                                 // 已同意，房主还在开房（他要上传世界）
      if (n >= 20) { MPUI.setWait(null); MPUI.render(); MPUI.msg2('Timed out: the Room never opened. Ask them to tap "Accept" again'); return; }
      MPUI.msg2('They accepted — waiting for the Room to open… (' + n + '/20）');
      return setTimeout(() => mpJoinRoom(c, n + 1), 1500);
    }
    const host = d.host;                                       // 没人同意过我
    if (n === 0) {
      if (!host) { MPUI.msg2('This Room isn\'t open yet: ask the host to enter their World first'); return; }
      if (!host.online) { MPUI.msg2('Host ' + (host.nick || '') + ' is offline — ask again when they\'re in game'); return; }
      acctApi({ a: 'jreq', tok: ACCT.tok, pid: ACCT.pid, nick: ACCT.nick, to: host.pid }).then(r => {
        if (r && r.ok) { MPUI.setWait({ pid: host.pid, nick: host.nick, at: Date.now() }); MPUI.show('friend'); MPUI.render(); }
        else MPUI.msg2({ not_friend: 'You\'re not friends yet: add them in the Friends list below', offline: 'Host is offline' }[r && r.e] || 'Request failed: ' + (r && r.e));
      });
    }
    if (n >= 20) { MPUI.setWait(null); MPUI.render(); MPUI.msg2('Timed out: ' + ((host && host.nick) || 'Host') + ' hasn\'t accepted (you can ask again)'); return; }
    MPUI.msg2('Asked to join ' + ((host && host.nick) || 'They') + '\'s World — waiting for them to tap "Accept"… (' + n + '/20）');
    setTimeout(() => mpJoinRoom(c, n + 1), 1500);
  }).catch(() => MPUI.msg2('Cannot reach the server'));
}

/* 当前正在玩的世界 → 房间码（没进世界就是空）*/
function mpCurrentCode() {
  const m = currentId ? worldMeta(currentId) : null;
  return m ? mpRoomCodeOf(m) : '';
}
/* 「同意好友加入」时要开哪个世界：正在玩的 → 最近玩过的 → 一个都没有就新建。
   ★ 这一步就是「房间自动创建」—— 房主不需要先开一个房间、也不需要有房间码。 */
function mpHostTarget() {
  let m = (started && currentId) ? worldMeta(currentId) : null;
  if (!m && currentId) m = worldMeta(currentId);
  if (!m) m = worlds[0] || null;
  if (!m) m = createWorld({ name: 'My World', mode: 'survival', seed: (Math.random() * 1e6) | 0 });
  return m;
}
function mpHostTargetCode() { const m = mpHostTarget(); return m ? mpRoomCodeOf(m) : ''; }
/* 自动开房：房主点了「同意」之后走这里（不用再点「开房」按钮）*/
function mpAutoHost(code) {
  if (!ACCT.on) return MPUI.msg2('Sign in to play Multiplayer');
  if (window.NET && NET.active) return;                    // 已经在房间里了
  const m = mpHostTarget();
  if (!m) return MPUI.msg2('Couldn\'t find the Save to host');
  const c = code || mpRoomCodeOf(m);
  try { save(); } catch (e) {}                            // 跳转前存一次，别丢这几秒的进度
  MPUI.msg2('Opening "' + (m.name || 'My World') + '" as a Room ' + c + ' …');
  setTimeout(() => {
    mpNavTo(location.pathname + '?mp=1&go=1&host=1&lid=' + encodeURIComponent(m.id)
      + '&world=' + encodeURIComponent(c) + '&nick=' + encodeURIComponent(ACCT.nick || LOOK.name));
  }, 200);
}

/* 单机也在线的「社交心跳」：每 5 秒把「我在哪个世界」报给服务端，
 * 顺便收好友申请/加入申请，以及**「对方同意了我」的通知 → 自动进房间**。
 * 以前只有进了联机房间才跟服务端说话 → 单机时好友看不到你在玩什么。 */
let mpSocialBusy = false;
const mpAutoJoinSeen = new Set();      // 同一张通行证只自动进一次（轮询每 5s 会重复回同一批 inv）
function mpSocialTick() {
  if (!ACCT.on || (window.NET && NET.active) || mpSocialBusy) return;   // 联机里由 bootNet 自己的心跳负责
  mpSocialBusy = true;
  const pw = (started && currentId) ? mpCurrentCode() : '';
  acctApi({ a: 'acct', tok: ACCT.tok, pid: ACCT.pid, nick: ACCT.nick, code: '', pworld: pw })
    .then(d => {
      mpSocialBusy = false;
      if (!d || !d.ok) return;
      MPUI.setFriends(d);
      /* 等待超时：对方没看到 / 下线了 → 2 分钟后自动撤回，别让「等待同意」永久挂着 */
      const w0 = MPUI.waiting;
      if (w0 && Date.now() - (w0.at || 0) > 120000) {
        MPUI.setWait(null); MPUI.render();
        toast('Waiting for ' + (w0.nick || 'They') + ' accepted over 2 minutes ago — request withdrawn (you can ask again)', 5);
      }
      const reqs = d.req || [];
      MPUI._reqN = reqs.length;
      const btn = document.getElementById('btnFriendsHud');
      if (btn) btn.textContent = reqs.length ? ('Friends (' + reqs.length + ')') : 'your friend';
      /* ★ 我申请加入的好友点了「同意」→ 这边自动进，不用再点「加入」。
         两个前提，缺一个就会变成「每次打开网站都自动进这个房间」：
         · 只认 3 分钟内的同意（旧通知不该再拉人）
         · 进房成功后立刻让服务端把这张「已同意」用掉（ivdone），否则刷新/重开页面又会自动进一次 */
      const okInv = (d.inv || []).find(v => v && v.j === 1 && (Date.now() - (v.at || 0)) < 180000
        && !mpAutoJoinSeen.has(v.code + ':' + (v.at || 0)));
      if (okInv) {
        mpAutoJoinSeen.add(okInv.code + ':' + (okInv.at || 0));
        MPUI.setWait(null);
        toast((okInv.nick || 'your friend') + ' accepted — entering their World…', 4);
        setTimeout(() => { if (!(window.NET && NET.active)) mpJoinRoom(okInv.code, 1); }, 150);
        return;
      }
      /* 去重按「人」：同一个好友反复申请（服务端每次 join 都排一条新的时间戳）以前每 5 秒
         都把面板弹开一次 → 用户点了返回又自己弹回来，看着就是「关不掉」。 */
      const fresh = reqs.filter(r => !MPUI._seenReq.has(r.from));
      for (const r of reqs) MPUI._seenReq.add(r.from);
      if (fresh.length) {
        toast(fresh[0].nick + ' wants to join your World — tap "Accept" and the Room opens automatically', 6);
        MPUI.autoShow();                     // 刚关过面板就先只提示，不硬弹
      } else if (MPUI.ready && MPUI.root && !MPUI.root.classList.contains('hide')) {
        MPUI.render();
      }
    }).catch(() => { mpSocialBusy = false; });
}
setInterval(mpSocialTick, 5000);
setTimeout(mpSocialTick, 1200);
/* 一键加入链接：已登录 → 直接进；没登录 → 打开面板让他登录（登录成功后 acctApply 会接着进） */
setTimeout(() => {
  if (!PENDING_JOIN) return;
  if (ACCT.on) { const c = PENDING_JOIN; PENDING_JOIN = ''; mpJoinRoom(c); }
  else { MPUI.show('list'); MPUI.msg2('Join the Room automatically after signing in ' + PENDING_JOIN); }
}, 900);
/* 进入账号里的世界：本地有同 seed 的世界就直接开，没有就用云端 seed 造一个，然后以房主身份开房（改动从服务端拉）*/
function mpEnterAccountWorld(code) {
  if (!ACCT.on) return MPUI.show('list');
  const w = (ACCT.worlds || []).find(x => x.code === code);
  if (!w) return MPUI.msg2('This World isn\'t on the account');
  let m = worlds.find(x => x.mpCode === code) || worlds.find(x => x.seed === w.seed && x.name === w.name);
  if (!m) {
    m = createWorld({ name: w.name || ('Account World ' + code), mode: w.mode || 'survival', seed: w.seed, mpCode: code });
  } else if (!m.mpCode) { m.mpCode = code; saveIndex(); }
  MPUI.msg2('Opening "' + (m.name || code) + '」…');
  setTimeout(() => {
    mpNavTo(location.pathname + '?mp=1&go=1&host=1&lid=' + encodeURIComponent(m.id)
      + '&world=' + encodeURIComponent(code) + '&nick=' + encodeURIComponent(ACCT.nick || LOOK.name));
  }, 200);
}

/* ============================================================ 联机层（P0 spike）
 * 开启方式（不加参数 = 单机，行为与之前完全一致）：
 *   /blockwild/?net=http://192.168.50.3:9103&world=W1&nick=KA
 * 世界模型：服务端只存 seed + 方块改动，客户端用同一个 seed 自己生成地形，
 *           所以进服同步是「几十 KB 的编辑表」而不是「8MB 的区块」。
 * 权威划分：位置=客户端（服务端只做距离/速率校验），方块=服务端（拒绝就回滚），
 *           液体/怪物=主机客户端（别的客户端不模拟，避免编辑流互相打架）。
 */
(function bootNet() {
  const q = new URLSearchParams(location.search);
  // ?net=http://host:port 显式指定守护进程；?mp=1 走默认路径（局域网直连 :9203 / 公网同源 PHP 桥）
  let base = q.get('net');
  const host = location.hostname;
  const LAN = /^(localhost|127\.|192\.168\.|10\.|172\.(1[6-9]|2\d|3[01])\.)/.test(host);
  if (!base && q.has('mp')) {
    // https 页面无法直连 ws://host:9203（混合内容 + 端口未暴露）
    // http 的公网域名同样连不到 :9203（端口没映射到外网）——以前这里只按 https 判断，
    // 于是「http 打开、点联机」永远 Failed to fetch。现在只有局域网 IP / localhost 才直连 WS。
    base = (location.protocol === 'https:' || !LAN)
      ? (location.pathname.replace(/[^/]*$/, '') + 'bwmp.php')
      : ('http://' + host + ':9203');
  }
  if (!base) return;                                   // 没带 ?net= / ?mp → 纯单机
  let nick = (q.get('nick') || loadLook().name || localStorage.getItem('bw_nick') || ('P' + Math.random().toString(36).slice(2, 5))).slice(0, 14);
  if (nick) { try { localStorage.setItem('bw_nick', nick); } catch (e) {} }
  // ★ 世界代码：URL 指定 > 上次自己选过的 > 按昵称算出来的「我的世界」。
  //   以前默认写死 'W1'：所有人点「进入联机」都被塞进同一个公共 W1 世界（别人的存档）。
  const myWorld = () => 'W' + (Math.abs(hashString('bw:' + nick)) % 1679616).toString(36).toUpperCase().padStart(4, '0');
  let savedWorld = ''; try { savedWorld = localStorage.getItem('bw_world') || ''; } catch (e) {}
  let world = String(q.get('world') || savedWorld || myWorld()).replace(/[^\w-]/g, '').slice(0, 12) || myWorld();
  // ★ 身份（pid）跟昵称走，不跟世界走：以前 pid = 世界码-昵称，换个世界就成了另一个账号，
  //   好友关系/申请全部失效（"明明是好友却提示还不是好友"）。
  const pid = (q.get('pid') || ('u-' + nick)).slice(0, 24);
  // ★ 「刚进去就被拉到联机世界」的根因就在这里：只要 URL 上带着 ?mp=1（一次联机后地址栏就一直带着，
  //   刷新 / 点「世界」/ iOS 恢复标签页都会再进一次），bootNet 就无条件 join。
  //   现在只有明确意图（?net= 调试入口，或客户端自己跳转时带的 go=1）才自动进服；
  //   裸链接（手输/书签/分享）一律不自动进，退回单机开始界面并打开联机面板预填这个世界码。
  /* ★ 「打开网站就自动进房间、刷新也没用」的两个根因都在这里，一次解决：
     ① 地址栏里的 ?mp=1&go=1&world=XXX 以前只在 join **成功之后**才被 replaceState 洗掉；
        这次联机失败/卡住/页面被切后台 → 脏 URL 留在地址栏，刷新、浏览器恢复标签页都会再自动进一次；
     ② 带 go=1 的地址被存成书签/收藏 → 每次打开都当「刚点了加入」。
     现在：一进页面先把地址栏洗干净（不管后面成不成功），并且 go=1 必须配一个
     「本标签页刚点过加入」的一次性令牌（mpNavTo 打的）。 */
  let goTok = '';
  try { goTok = sessionStorage.getItem('bw_go') || ''; } catch (e) {}
  try { sessionStorage.removeItem('bw_go'); } catch (e) {}      // 一次性：用完就丢
  try { history.replaceState(null, '', location.pathname); } catch (e) {}
  /* ?net= 是调试入口：只有**明确写了 world=（或带一次性令牌的 go=1）**才自动进服；
     光有 ?net= 只打开面板挑，不再「进去再说」—— 那个默认世界码是按昵称算的，
     常常正好撞上某个人开着的房间，看起来就是「莫名其妙自己进了别人的房」。 */
  const wantGo = q.has('net')
    ? (q.has('world') || q.get('go') === '1' || goTok === '1')
    : (q.get('go') === '1' && goTok === '1');
  if (!wantGo) {
    window.__bwPrefillMP = { code: world, nick, why: q.get('go') === '1' ? 'stale' : 'link' };
    return;
  }
  const API = base.replace(/\/+$/, '');
  const IS_BRIDGE = /\.php(\?|$)/.test(API);          // 同源 PHP 桥 → 只能轮询
  const EP = IS_BRIDGE ? API : (API + '/api');   // 所有 HTTP 动作的实际地址（桥模式就是 bwmp.php 本身）
  const WSURL = API.replace(/^http/, 'ws') + '/';
  const net = {
    active: true, applying: false, isHost: false, id: pid, code: world, nick,
    ws: null, connected: false, rtt: 0, snapHz: 0, snaps: 0, hzT: 0, mode: IS_BRIDGE ? 'poll' : 'ws', pollT: 0, syncs: 0,
    pending: new Map(), pendingKey: new Map(), seq: 0, serverSeq: 0, mobSeq: 0, mobT: 0, sendT: 0, hudT: 0, pingT: 0,
    ghosts: new Map(), devOk: false,
    remotes: new Map(), lastSnap: 0, err: '', editOut: 0, rejCount: 0, netBytes: 0,
    skinSent: '',                                             // 上次成功上报的皮肤哈希（变了才重传 PNG 数据）
    lid: q.get('lid') || '',                                  // 房主：自己哪个本地世界开的房
    wname: '',                                                // 世界显示名（房间列表用）
  };
  NET = net;

  /* ---------- 退出联机（必须有个出口）
   * 以前进了联机就没有任何按钮能出来：「世界」按钮 reload 回来又自动 join（URL 粘着 ?mp），
   * 只能自己在地址栏删参数。现在「世界」按钮和好友面板里都能退出。 */
  net.leave = (ask) => {
    if (ask !== false && !confirm(ask || `Leave Multiplayer "${net.code}" and return to the World list?`)) return false;
    net.active = false; net.connected = false;
    try { if (net.ws) net.ws.close(); } catch (e) {}
    // 房主的房间就是他自己的存档：退出前先存一次，别把联机里盖的东西弄丢
    if (net.lid) { try { save(); } catch (e) {} }
    else { try { net.beaconInv(); } catch (e) {} }      // 客人：最后一次把背包存回服务端（beacon 不会被 reload 掐掉）
    try { history.replaceState(null, '', location.pathname); } catch (e) {}
    location.reload();
    return true;
  };

  /* ---------- 远端玩家形象 ---------- */
  function nameTag(text, y) {
    const cv = document.createElement('canvas');
    cv.width = 256; cv.height = 64;
    const g = cv.getContext('2d');
    g.font = 'bold 34px system-ui, sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillStyle = 'rgba(8,16,26,.72)';
    g.fillRect(0, 12, 256, 40);
    g.fillStyle = '#dff0ff';
    g.fillText(text.slice(0, 12), 128, 33);
    const tex = new THREE.CanvasTexture(cv);
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
    sp.scale.set(1.7, 0.42, 1);
    // ★ 默认高度跟着模型头顶走（32 px = 1.78 格），别再写死 —— 写死的 2.15 是旧盒体模型的高度，
    //   换成贴图模型后头顶只有 1.78，名字就飘在头顶 0.37 格的半空里。
    sp.position.y = (typeof y === 'number') ? y : (32 * MOB_PX + 0.17);
    return sp;
  }
  function avatar(id, name, look) {
    // 远端形象的头/手方向（用 GAME.debug.remoteAxes() 实测出来的基准，模型正面 = -Z）：
    //   脸在 -Z；armR.rotation.x 正 = 手往前甩；head.rotation.x 正 = 抬头（下巴抬高、头顶往后）。
    // 如果哪天看着反了，只需要把 HEAD_PITCH_SIGN 改成 -1（定义在 bootNet 作用域里）。
    // 固定调色板（避开草绿/天空蓝，否则人在草地上几乎看不见）：没设置外观的老玩家按 id 哈希取色
    const PAL = [0xd9534f, 0x9b59b6, 0xf0ad4e, 0xe67e22, 0x1abc9c, 0xff6fa8, 0xc0392b, 0x8e6bff];
    let hsh = 0;
    for (let i = 0; i < id.length; i++) hsh = (hsh * 31 + id.charCodeAt(i)) | 0;
    const base = PAL[Math.abs(hsh) % PAL.length];
    const lk = look || {};
    // 皮肤源：对方上传的 PNG > 按配色生成的皮肤
    const rskin = lk.skd || lk.skinSrc || ('gen:' + ((typeof lk.sk === 'number') ? lk.sk : 0xd8b48a) + ':'
      + ((typeof lk.cl === 'number') ? lk.cl : base) + ':' + ((typeof lk.hr === 'number' && lk.hr > 0) ? lk.hr : 0x33251a) + ':' + (lk.hs | 0));
    const A = buildSkinAvatar({ skinSrc: rskin });
    const g = A.g, torso = A.torso, head = A.head, face = A.face;
    const tank = makeBackTank(); tank.visible = false; g.add(tank);   // ★ v339 背上的氧气罐
    const armL = A.armL, armR = A.armR, legL = A.legL, legR = A.legR, foreR = A.foreR;
    g.add(nameTag(name));
    g.userData = {
      tx: 0, ty: 0, tz: 0, yaw: 0,
      walk: 0, spd: 0, swing: 0, swingType: '', airK: 0, sprintK: 0, mineK: 0, landK: 0,
      buf: [], airPrev: 0,              // 快照缓冲（渲染延迟插值用）+ 上一帧腾空位（判落地）
      swimK: 0,                         // ★ v335 游泳权重（0 站立 → 1 俯冲）
      /* ★ 骨骼基准高度：模型自带的正确定位（躯干中心 18 px / 颈根 24 px / 肩 24 px）。
       *   动画只能在这个基准上「加偏移」，不能改成写死的格数 —— 旧盒体模型的 1.06 / 1.62
       *   套到 32 px 贴图模型上 = 头底比躯干顶高 4 px（头悬空）、肩线比躯干顶低 1 px（肩不平）。 */
      base: { torso: torso.position.y, head: head.position.y, armL: armL.position.y, armR: armR.position.y },
      armL, armR, legL, legR, foreR, torso, head, face, tank, flags: 0, phase: Math.random() * 6.28,
    };
    scene.add(g);
    return g;
  }
  /* 皮肤：PNG 皮肤按哈希缓存，没见过就向服务端要一次（快照里只带哈希，不撑包） */
  const netSkins = new Map();      // png key → dataURL
  const netSkinAsk = new Set();
  function remoteSkinSrcOf(p) {
    const k = String(p.skn || '');
    if (k.indexOf('png:') === 0) return netSkins.get(k) || null;
    if (k.indexOf('gen:') === 0) return k;
    return 'gen:' + (p.sk | 0) + ':' + (p.cl | 0) + ':' + (p.hr | 0) + ':' + (p.hs | 0);
  }
  function rebuildRemoteSkin(id, r) {
    const ud = r.obj.userData || {};
    const pp = { i: id, n: r.name, x: r.obj.position.x, y: r.obj.position.y, z: r.obj.position.z, w: ud.yaw || 0,
      sk: r.sk, cl: r.cl, hr: r.hr, hs: r.hs, skn: r.skn };
    try { scene.remove(r.obj); } catch (e) {}
    net.remotes.delete(id);
    try { ensureRemote(pp); } catch (e) {}
  }
  function askSkin(p) {
    const k = String(p.skn || '');
    if (k.indexOf('png:') !== 0 || netSkins.has(k) || netSkinAsk.has(k)) return;
    netSkinAsk.add(k);
    try {
      apiCall({ a: 'getskin', hash: k }).then((d) => {
        netSkinAsk.delete(k);
        if (d && d.ok && d.skd) {
          preloadSkin(d.skd).then(() => {
            skinTexCache.delete(k); skinOverlayCache.delete(k);
            netSkins.set(k, d.skd);
            for (const [id, r] of Array.from(net.remotes)) if (r.skn === k) rebuildRemoteSkin(id, r);
          }).catch(() => {});
        }
      }).catch(() => netSkinAsk.delete(k));
    } catch (e) { netSkinAsk.delete(k); }
  }
  function ensureRemote(p) {
    let r = net.remotes.get(p.i);
    if (r) {
      /* ★ 对方中途换了外观（肤色/衣服/发色/发型）或换了 PNG 皮肤 → 当场重建模型。
         以前只在「第一次见到这个人」时建一次模型，之后快照里带来的新外观被完全忽略，
         表现就是「他改了皮肤，我这边一直还是旧的」。 */
      const sknNew = String(p.skn || '');
      if (sknNew !== String(r.skn || '') || (p.sk | 0) !== (r.sk | 0) || (p.cl | 0) !== (r.cl | 0)
          || (p.hr | 0) !== (r.hr | 0) || (p.hs | 0) !== (r.hs | 0)) {
        rebuildRemoteSkin(p.i, { name: p.n || r.name, sk: p.sk | 0, cl: p.cl | 0, hr: p.hr | 0, hs: p.hs | 0,
                                 skn: sknNew, obj: r.obj });
        r = net.remotes.get(p.i);
      }
      if (r && p.n && p.n !== r.name) r.name = p.n;
      if (r) {
        r.oh = p.oh | 0;
        if (r.obj && r.obj.userData && r.obj.userData.tank) r.obj.userData.tank.visible = (p.oh | 0) === OXY_TANK_ID;
        return r;
      }
    }
    if (!r) {
      const skSrc = remoteSkinSrcOf(p);
      r = { obj: avatar(p.i, p.n, { sk: p.sk, cl: p.cl, hr: p.hr, hs: p.hs, skd: skSrc }), name: p.n || p.i,
            sk: p.sk, cl: p.cl, hr: p.hr, hs: p.hs, skn: p.skn, oh: p.oh | 0 };
      if (r.obj.userData.tank) r.obj.userData.tank.visible = (p.oh | 0) === OXY_TANK_ID;   // ★ v339
      if (skSrc === null) askSkin(p);
      r.obj.position.set(p.x, p.y, p.z);
      r.obj.userData.tx = p.x; r.obj.userData.ty = p.y; r.obj.userData.tz = p.z; r.obj.userData.yaw = p.w;
      net.remotes.set(p.i, r);
      toast(`${r.name} joined the Room`, 2.5);            // 有人进来必须看得见（这是"联机到底通没通"最直接的反馈）
    }
    return r;
  }
  function dropRemote(id) {
    const r = net.remotes.get(id);
    if (!r) return;
    scene.remove(r.obj);
    r.obj.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); });
    net.remotes.delete(id);
  }

  /* ---------- 兴趣管理：走远了分块补改动（进服只发 ±128 格） ---------- */
  net.lastPull = { x: 1e9, z: 1e9 };
  net.pullT = 0;
  /* ★ v362：远端改动不再在 fetch 回调里一次性同步应用（那片区域可能有几千条改动，
     一次 .then 里全改完 = 一两百毫秒的整屏卡顿，玩家看到的是「走着走着一顿」）。
     现在只入队，由 net.drainEditQ() 在每帧的流式阶段按时间预算摊开应用。 */
  net.editQ = [];
  net.editQn = 0;
  net.drainEditQ = (budgetMs = 2) => {
    const q = net.editQ;
    if (!q.length) return 0;
    const t0 = performance.now();
    let n = 0;
    while (q.length) {
      if ((n & 63) === 0 && performance.now() - t0 > budgetMs) break;
      const e = q.pop();
      const k = e[0];
      const id = e[1], mm = e[2];
      n++;
      if (edits.has(k) && edits.get(k) === id) {                 // 方块已经一致：只补 meta
        if (typeof mm === 'number') { const a = k.split(','); setMeta(+a[0], +a[1], +a[2], mm, false); }
        continue;
      }
      const a = k.split(',');
      applyServerBlock(+a[0], +a[1], +a[2], id, mm);
    }
    return n;
  };
  net.pullRegion = () => {
    const x = Math.floor(player.p.x), z = Math.floor(player.p.z);
    net.lastPull = { x, z };
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'region', code: net.code, x, z, r: 112 }) })
      .then(r => r.json()).then(d => {
        if (!d.ok || !d.edits) return;
        for (const e of d.edits) net.editQ.push(e);
        if (d.edits.length > 120) toast(`Caught up on ${d.edits.length} changes nearby`, 2);
      }).catch(() => {});
  };

  /* ---------- 非主机打幽灵怪：本地判定 + 上报给主机扣血 ---------- */
  net.hitGhost = (dmg) => {
    if (net.isHost) return false;                     // 主机打的是真怪，不走这条路
    const dir = cameraDir(), eye = eyePos();
    let best = null, bestT = 1e9;
    /* 命中判定对「两个位置」都试一遍：
       · 主机快照的目标位置（tx/ty/tz）—— 这是怪真身现在的位置
       · 本机插值后的可见位置（obj.position）—— 玩家眼睛瞄准的是这个
       以前只用其中一个：怪朝你冲/背你跑时两者能差一格多，于是「明明砍到了却没反应」。 */
    const tryHit = (g, px, py, pz) => {
      const dx = px - eye.x, dz = pz - eye.z;
      /* 竖直方向按「胶囊」算：脚 +0.35 ~ 头 +1.55 这一段都算打中，
         矮的（鸡/蜘蛛）和高低差一点的不再擦身而过。 */
      for (const yOff of [0.55, 0.95, 1.35]) {
        const dy = (py + yOff) - eye.y;
        const t = dx * dir.x + dy * dir.y + dz * dir.z;
        if (t < 0.1 || t > CFG.REACH) continue;
        const qx = dx - dir.x * t, qy = dy - dir.y * t, qz = dz - dir.z * t;
        if (qx * qx + qy * qy + qz * qz > 2.2) continue;      // 半径 ~1.48
        if (t < bestT) { bestT = t; best = g; }
        return true;
      }
      return false;
    };
    for (const [id, g] of net.ghosts) {
      if (g.dying) continue;                                // 已经倒地的别再打（白耗耐久）
      g.nid = id;
      const lx = g.obj.position.x, ly = g.obj.position.y, lz = g.obj.position.z;
      if (tryHit(g, (typeof g.tx === 'number' ? g.tx : lx), (typeof g.ty === 'number' ? g.ty : ly),
                    (typeof g.tz === 'number' ? g.tz : lz))) continue;
      tryHit(g, lx, ly, lz);
    }
    if (!best) return false;
    const g = best;
    const gp = g.obj.position;
    const kx = gp.x - eye.x, kz = gp.z - eye.z;             // 击退方向：我 → 怪
    net.send('hit', { i: best.nid, d: dmg, kx, kz });
    g.hitAt = performance.now(); g.flash = 0.24;             // 本地立刻闪红，不等 150ms 后的快照
    return true;
  };

  /* ---------- 非主机端的「幽灵怪」：只按主机快照摆模型，不跑 AI、不参与战斗 ----------
   * ★ 以前这里只保存 obj + 目标位置：客人看到的动物是「滑行的木头人」——
   *   腿不迈、头不转、挨打不闪红、血条永远满格而且只朝一个固定方向（侧看变成一条线）。
   *   现在把 makeMobModel 的 parts 留下来，并让幽灵怪本身长得像宿主循环里的 m：
   *   animateMob() 只要 m.parts / m.kind / m.obj / m.p / m.v / m.onGround / m.flash，
   *   所以**同一个动画函数**在两边跑，动作不会再走样。 */
  /* ★ v349：客人端的「幽灵箭」—— 只做视觉（伤害全在房主那边结算），
     用 performance.now 算位置，所以每帧多调用几次也不会跑快。 */
  const gArrowMat = new THREE.MeshBasicMaterial({ color: 0xe8e4d6 });
  const gArrows = [];
  function spawnGhostArrow(fx, fy, fz, tx, ty, tz) {
    const from = new THREE.Vector3(fx, fy, fz), to = new THREE.Vector3(tx, ty, tz);
    const len = from.distanceTo(to) || 1;
    const m = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.07, Math.min(1.8, len)), gArrowMat);
    m.position.copy(from); m.lookAt(to);
    scene.add(m);
    gArrows.push({ m, from, to, t0: performance.now(), dur: Math.max(120, len / 32 * 1000) });
    if (gArrows.length > 24) { const old = gArrows.shift(); scene.remove(old.m); old.m.geometry.dispose(); }
  }
  function updateGhostArrows() {
    const now = performance.now();
    for (let i = gArrows.length - 1; i >= 0; i--) {
      const a = gArrows[i];
      const k = Math.min(1, (now - a.t0) / a.dur);
      a.m.position.lerpVectors(a.from, a.to, k);
      if (k >= 1) { scene.remove(a.m); a.m.geometry.dispose(); gArrows.splice(i, 1); }
    }
  }
  function syncGhosts(list) {
    const alive = new Set();
    for (const e of list) {
      const [id, kind, x, y, z, rot, hp, spd, dk, an] = e;
      const rc = e[10];                                     // 村民招募状态（只有村民带）
      const dead = (typeof dk === 'number' && dk > 0);
      if (typeof hp === 'number' && hp <= 0 && !dead) continue;   // 真没了又没带死亡Progress → 直接丢掉
      alive.add(id);
      let g = net.ghosts.get(id);
      if (!g) {
        const parts = (typeof makeMobModel === 'function') ? makeMobModel(kind) : null;
        if (!parts) continue;
        parts.g.position.set(x, y, z);
        scene.add(parts.g);
        g = {
          obj: parts.g, parts, kind,
          nid: id, remote: true, recruit: null,          // nid：客人右键/打怪时用来告诉房主「是哪一只」
          p: parts.g.position,                       // 和 obj.position 是同一个 Vector3：动画里读 m.p 直接对
          v: { x: 0, y: 0, z: 0 }, onGround: true,
          anim: { walk: Math.random() * 6, k: 0, idle: 0, land: 0 },
          flash: 0, lunge: 0, headYaw: 0, headPitch: 0, atkN: null,
          dying: false, dieT: 0,
          hp: (typeof hp === 'number' ? hp : null),
          maxHp: (MOB_DEFS[kind] && MOB_DEFS[kind].hp) || 20,
          spd: 0, tx: x, ty: y, tz: z, rot,
        };
        net.ghosts.set(id, g);
      }
      // 血量下降 = 挨了一下（主人打、别的客人打、太阳烧、岩浆都算）→ 本地播 0.24s 红闪
      if (typeof hp === 'number') {
        if (g.hp !== null && hp < g.hp) g.flash = 0.24;
        g.hp = hp;
      }
      // ★ 死亡进度：主机送 dieT 秒数，客人拿同一个 applyMobDeathPose 播倒地 → 躺尸 → 缩小
      if (dead) { g.dying = true; g.dieT = Math.max(g.dieT || 0, dk); }   // 只进不退，避免快照往返让倒地动画回抽
      else if (g.dying && typeof hp === 'number' && hp > 0) {             // 又活了（复活/回档）→ 复位，别留一具隐形的尸体
        g.dying = false; g.dieT = 0; g.obj.scale.setScalar(1);
        if (g.parts.core) { g.parts.core.rotation.set(0, 0, 0); g.parts.core.position.z = 0; }
      }
      // ★ 攻击计数器变了 = 主机那边刚挥了一下 → 本地播前扑（巨像还额外抬臂投掷）
      const an2 = an | 0;
      if (g.atkN === null) g.atkN = an2;
      else if (an2 !== g.atkN) {
        g.atkN = an2; g.lunge = 0.3; g.throwAnim = 0.45;
        /* ★ v349：远程怪（荆棘射手 / 骷髅 / 烈焰）在**别人屏幕上**也要看得见「举弓 + 放箭」；
           伤害仍然由房主结算，这支箭只是视觉。 */
        const md = MOB_DEFS[g.kind] || {};
        if (md.ranged) {
          g.bowT = 0.55;
          spawnGhostArrow(g.p.x, g.p.y + 1.1, g.p.z, player.p.x, player.p.y + 1.15, player.p.z);
        }
      }
      g.spd = (typeof spd === 'number' && spd > 0) ? spd : 0;
      g.tx = x; g.ty = y; g.tz = z; g.rot = rot;
      /* ★ 村民的招募状态（房主那边是真身）：客人靠这一份镜像画头顶 ! / ★、
         判断「他想要什么 / 还差多少 / 是不是已经在跟着你」。没有它客人右键只能干瞪眼。 */
      if (Array.isArray(rc)) {
        const wasHired = g.recruit ? g.recruit.hired : null;
        g.recruit = { hired: !!rc[0], follow: !!rc[1], want: { id: rc[2] | 0, need: rc[3] | 0, got: rc[4] | 0 } };
        if (wasHired !== g.recruit.hired || g.markKey !== (g.recruit.hired ? 'hired' : 'ask')) {
          g.markKey = g.recruit.hired ? 'hired' : 'ask';
          try { refreshVillagerMark(g); } catch (e) {}
        }
      }
    }
    for (const [id, g] of Array.from(net.ghosts)) {
      if (alive.has(id)) continue;
      scene.remove(g.obj);
      g.obj.traverse(o => { if (o.geometry && !o.geometry.userData.shared) o.geometry.dispose(); });
      net.ghosts.delete(id);
    }
  }

  /* ---------- 箱子：服务端是唯一权威（两人开同一个箱子看到同一批东西） ---------- */
  net.pullChest = (x, y, z) => {
    const k = x + ',' + y + ',' + z;
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'chest', code: net.code, pid: net.id, k }) })
      .then(r => r.json()).then(d => {
        if (!d.ok || !Array.isArray(d.slots)) return;
        chestInv.set(k, d.slots);
        if (openChestPos && (openChestPos.x + ',' + openChestPos.y + ',' + openChestPos.z) === k) renderChest();
      }).catch(() => {});
  };
  net.pushChest = () => {
    if (!openChestPos) return;
    const k = openChestPos.x + ',' + openChestPos.y + ',' + openChestPos.z;
    const slots = chestInv.get(k);
    if (!slots) return;
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'chest', code: net.code, pid: net.id, k, slots }) }).catch(() => {});
  };

  /* ---------- 客人背包：存服务端，退出/换设备都拿得回来（房主用自己的本地存档） ---------- */
  net.pullInv = () => {
    if (net.lid) return;
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'inv', code: net.code, pid: net.id }) })
      .then(r => r.json()).then(d => {
        const s = d && d.data;
        if (!d.ok || !s) return;
        inv = new Array(SLOTS).fill(null);
        (s.inv || []).filter(x => x && isItem(x.id) && x.n > 0).forEach((x, i) => { if (i < SLOTS) inv[i] = { id: x.id, n: x.n, d: x.d }; });
        if (s.armor) for (const k of ARMOR_SLOTS) if (ITEMS[s.armor[k]]) player.armor[k] = s.armor[k];
        /* ★ v346：`s.hp | 0` 会把 0.4 截成 0（回血后正好不到半颗心）→ 进房瞬间变成「0 血活着」。
           改成保留小数、并且至少 1 点。 */
        const h1 = +s.hp;
        if (isFinite(h1) && h1 > 0) player.hp = Math.min(20, Math.max(1, h1));
        if (s.hunger) player.hunger = Math.min(20, +s.hunger || 0);
        renderHotbar(); refreshHeld(); renderHearts();
        toast('Restored your Inventory from last time in this Room (' + (s.inv || []).filter(Boolean).length + ' slots)', 3.5);
      }).catch(() => {});
  };
  net.pushInv = () => {
    if (net.lid || !net.active) return;
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'inv', code: net.code, pid: net.id,
        set: { inv, armor: player.armor, hp: player.hp, hunger: player.hunger } }) }).catch(() => {});
  };
  // 关标签页/切后台时 fetch 会被浏览器掐掉，用 sendBeacon 兜底（不然最后 5 秒的收获白拿）
  net.beaconInv = () => {
    if (net.lid || !net.active) return false;
    try {
      const body = JSON.stringify({ a: 'inv', code: net.code, pid: net.id,
        set: { inv, armor: player.armor, hp: player.hp, hunger: player.hunger } });
      if (navigator.sendBeacon) {
        navigator.sendBeacon(EP, new Blob([body], { type: 'text/plain' }));
        return true;
      }
    } catch (e) {}
    try { net.pushInv(); } catch (e) {}
    return false;
  };
  try { window.addEventListener('pagehide', () => net.beaconInv()); } catch (e) {}

  /* ---------- 掉落物：主机广播快照，客人只画幽灵；谁捡走就上报 ---------- */
  net.dropGhosts = new Map();
  net.picked = new Set();                        // 已经捡走的掉落物 nid（防过期快照重建 → 重复捡）
  /* 上行消息统一出口：有 ws 走 ws，轮询模式走同名 HTTP action（服务端两个通道都认） */
  net.send = (kind, obj) => {
    if (net.ws && net.ws.readyState === 1) {
      try { net.ws.send(JSON.stringify(Object.assign({ t: kind }, obj))); return; } catch (e) {}
    }
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify(Object.assign({ a: kind, code: net.code, pid: net.id, tok: acctTok() }, obj)) }).catch(() => {});
  };
  net.sendPick = (nid) => net.send('pick', { i: nid });
  /* 掉落物归属：先问服务端「这件归谁」（先到先得），拿到 ok 才真正 addItem。
     以前是「本地先加进背包、再互相通知」→ 两个人抢同一件时各拿一份（一人一次）。 */
  net.claimDrop = (nid, cb) => {
    if (!net.active || nid === undefined || nid === null || String(nid).indexOf('g') === 0) { cb(true); return; }
    if (net.ws && net.ws.readyState === 1) {
      net.claimCb = net.claimCb || new Map();
      net.claimCb.set(String(nid), cb);
      try { net.ws.send(JSON.stringify({ t: 'claim', i: nid })); return; } catch (e) {}
    }
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'claim', code: net.code, pid: net.id, i: nid }) })
      .then(r => r.json()).then(d => cb(!!(d && d.ok))).catch(() => cb(true));
  };
  net.castAct = (type) => net.send('act', { act: type });
  /* 机器作业状态（熔炉）：整房间一份，存服务端 —— 房主也看得到、客人退出后那一炉还在 */
  net.machGet = (kind, cb) => {
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'mach', code: net.code, pid: net.id, kind }) })
      .then(r => r.json()).then(d => cb(d && d.ok ? d.v : null)).catch(() => cb(null));
  };
  net.machSet = (kind, v) => {
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'mach', code: net.code, pid: net.id, kind, set: v }) }).catch(() => {});
  };
  /* 地图共用：上报新揭开的格子 / 拉整张图 */
  net.mmPush = (blob) => {
    if (!blob) return;
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'mm', code: net.code, pid: net.id, push: blob }) }).catch(() => {});
  };
  net.mmPull = () => {
    fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
      body: JSON.stringify({ a: 'mm', code: net.code, pid: net.id, pull: 1 }) })
      .then(r => r.json()).then(d => {
        if (d && d.ok && d.v) { const n = mmMergeBlob(d.v); if (n) toast('Shared map: +' + n + ' slots', 3); }
      }).catch(() => {});
  };
  /* 客人对村民的操作（交物资 / 给道具 / 跟随待命）→ 房主那边结算 */
  net.vact = (i, act, extra) => net.send('vact', Object.assign({ i, act }, extra || {}));
  // 状态位：1=挖掘 2=疾跑 4=腾空 —— 远端形象靠它播动作（1 个字节，跟位置一起发）
  net.myFlags = () => {
    const spd = Math.hypot(player.v.x, player.v.z);
    return (mineHeld && player.mineTarget && player.alive ? 1 : 0)
         | (spd > CFG.WALK * 0.95 ? 2 : 0)
         | (!player.onGround && !player.inWater && !player.inLava ? 4 : 0)
         | (player.swimming ? 8 : 0);            // ★ v335 bit3：在游泳（别人据此播划水动画）
  };
  net.dropSeqLocal = 0;
  /* ★ v337 船的快照：房主权威，只发 [id, 木头, x, y, z, yaw] */
  net.pushBoats = () => {
    if (!net.ws || net.ws.readyState !== 1) return;
    const u = boats.map(b => [b.id | 0, b.wi | 0, +b.x.toFixed(2), +b.y.toFixed(2), +b.z.toFixed(2), +b.yaw.toFixed(2)]);
    try { net.ws.send(JSON.stringify({ t: 'b', u })); } catch (e) {}
  };
  net.gBoats = new Map();                     // 客人侧：别人放的船
  net.addDropGhost = (nid, id, n, x, y, z) => {
    // 客人本地的「预演掉落物」必须和主机的真实掉落物同款（物品=薄板、方块=立方体）
    const mesh = BLOCKS[id]
      ? new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.38, 0.38), new THREE.MeshBasicMaterial({ map: dropTexture(id) }))
      : itemDropMesh(id);
    mesh.position.set(x, y, z);
    scene.add(mesh);
    const g = { obj: mesh, id, n, p: new THREE.Vector3(x, y, z), t: 0, synced: false, vy: 0, thin: !BLOCKS[id] };
    net.dropGhosts.set(nid, g);
    return g;
  };
  // 客人挖出方块 → 不本地模拟，只上报给主机（主机 spawn 真掉落物，再广播回来接管这个幽灵）
  net.remoteDrop = (id, n, x, y, z) => {
    const nid = 'g' + net.id + ':' + (++net.dropSeqLocal);
    net.addDropGhost(nid, id, n, x, y + 0.2, z);
    net.send('drop', { u: [nid, id, n, +x.toFixed(2), +y.toFixed(2), +z.toFixed(2)] });
    return null;
  };
  net.syncDropGhosts = (list) => {
    const alive = new Set();
    for (const e of list) {
      const [nid, id, n, x, y, z] = e;
      if (!isItem(id)) continue;
      if (net.picked.has(String(nid))) continue;        // 已经捡走的：别被过期快照重建出来
      alive.add(nid);
      let g = net.dropGhosts.get(nid) || net.addDropGhost(nid, id, n, x, y, z);
      g.id = id; g.n = n; g.p.set(x, y, z); g.synced = true;
    }
    for (const [nid, g] of Array.from(net.dropGhosts)) {
      if (alive.has(nid)) continue;
      if (g.t < 2 || !g.synced) continue;       // 刚上报、主机还没回的快照：别立刻删掉（否则自己挖的东西闪一下就没）
      scene.remove(g.obj);
      if (!g.obj.userData.sharedGeo) {              // 薄板用共享几何/材质，不能释放
        if (g.obj.geometry) g.obj.geometry.dispose();
        if (g.obj.material && g.obj.material.dispose) g.obj.material.dispose();
      }
      net.dropGhosts.delete(nid);
    }
    net.checkDropPick();                        // 收到快照就顺手判一次（不依赖 rAF，手机切后台也捡得到）
  };
  /* 拾取判定单独拎出来：既在每帧跑，也在收到主机快照时跑一次。
   * 只跑在 rAF 里的话，后台/被节流的页面（手机切出去、iframe）就永远捡不到东西。 */
  net.checkDropPick = () => {
    for (const [nid, g] of Array.from(net.dropGhosts)) {
      if (g.t < 0.3) continue;
      if (net.picked.has(String(nid))) { scene.remove(g.obj); net.dropGhosts.delete(nid); continue; }
      const dx = player.p.x - g.p.x, dz = player.p.z - g.p.z;
      // 客人看到的掉落物坐标是主机 8Hz 同步 + 插值来的，别用主机的贴脸判定（0.95），用水平 1.8m
      if (dx * dx + dz * dz > 3.24) continue;
      if (g.claiming) continue;                       // 已经问过服务端了，等结果
      g.claiming = true;
      /* ★ 先问服务端「这件归谁」，拿到 ok 才进背包 —— 以前本地先加、再互相通知，
         两个人同时抢同一件时各得一份（「掉落物被捡起两次，一人一次」）。 */
      net.claimDrop(nid, (ok) => {
        scene.remove(g.obj);
        net.dropGhosts.delete(nid);
        net.picked.add(String(nid));
        if (net.picked.size > 400) net.picked.clear();
        if (!ok) return;                              // 别人先拿到了：只收掉幽灵
        addItem(g.id, g.n);
        renderHotbar(); sfx('dig');
        if (g.n > 1) toast(`Picked up ${nameOf(g.id)} ×${g.n}`, 1.1);
        net.sendPick(nid);
        if (!net.lid) net.pushInv();
      });
      continue;
    }
  };
  net.updateDropGhosts = (dt) => {
    const k = Math.min(1, dt * 12);
    for (const [nid, g] of Array.from(net.dropGhosts)) {
      g.t += dt;
      if (!g.synced) {                          // 还没拿到主机的坐标：本地先自由落体，别悬在半空
        g.vy -= 17 * dt;
        g.p.y += g.vy * dt;
        const below = getBlock(Math.floor(g.p.x), Math.floor(g.p.y - 0.17), Math.floor(g.p.z));
        if (g.vy < 0 && isSolid(below)) { g.p.y = Math.floor(g.p.y - 0.17) + 1.17; g.vy = 0; }
      }
      // 主机 8Hz 的快照直接 set 会一卡一卡，这里插值
      g.obj.position.x += (g.p.x - g.obj.position.x) * k;
      g.obj.position.y += (g.p.y + Math.sin(g.t * 3.2) * 0.05 - g.obj.position.y) * k;
      g.obj.position.z += (g.p.z - g.obj.position.z) * k;
      if (g.thin) orientDropCard(g.obj, g.p.x, g.p.z, g.t);
      else g.obj.rotation.y += dt * 2.4;
    }
    net.checkDropPick();
  };
  net.dropList = () => {
    const u = [];
    for (const d of drops) {
      u.push([d.nid, d.id, d.n, +d.p.x.toFixed(2), +d.p.y.toFixed(2), +d.p.z.toFixed(2)]);
      if (u.length >= 30) break;
    }
    return u;
  };
  net.pushDrops = () => {                       // WS 模式直接发；轮询模式走 sync 附带（见 net.tick）
    const u = net.dropList();
    net.dropCache = u;
    if (net.ws && net.ws.readyState === 1) { try { net.ws.send(JSON.stringify({ t: 'd', u })); } catch (e) {} }
  };

  /* ---------- 应用服务端方块 ---------- */
  function applyServerBlock(x, y, z, b, m) {
    /* ★ v370：房主收到客人改方块 → 陨石坑的触手传感器照样能听见 */
    if (net.isHost) mtNoteNoise(x, y, z);
    net.applying = true;
    try {
      setBlock(x, y, z, b, false);
      if (typeof m === 'number') {
        setMeta(x, y, z, m | 0, false);   // 门的开合/朝向、床朝向随之落地
        /* ★ 门 = 两格方块 + 一份状态：收到的这半格直接对齐整扇门。
           上下两格本来是两条独立编辑，丢一条/被拒一条就会「下格开着、上格关着」→
           门看着开了却过不去。这里收到任意一半就把另一半补齐（在 applying 里，不会回声上行）。 */
        if (BLOCKS[b] && BLOCKS[b].door) syncDoorMeta(x, y, z);
      }
    } finally { net.applying = false; }
    edits.set(x + ',' + y + ',' + z, b);        // 内存编辑表：区块卸载再加载不会退回天然地形
    indexEdit(x, y, z, b);                       // 不写 localStorage —— 服务端才是权威
  }

  /* ---------- 本地编辑上行（乐观 + 失败回滚） ---------- */
  /* 同一条上行通道：id 和 meta 一起发（服务端 applyEdit 认 msg.m） */
  net.pushEdit = (x, y, z, b, m, prev, prevM) => {
    const wsOk = !!(net.ws && net.ws.readyState === 1);
    if (!wsOk && !IS_BRIDGE) return;                  // 桥模式没有 ws，靠 sync 轮询把 pending 带上去
    /* ★ v322：同一格只留一条在飞的编辑。以前「挖 → 放 → 挖」三刀会三条一起飞，先发的那条
       被服务端拒掉后客户端拿它回滚 → 把**后**改好的方块盖回去 = 「过一秒又变回去了」。 */
    const ck = x + ',' + y + ',' + z;
    const oldSeq = net.pendingKey.get(ck);
    if (oldSeq !== undefined) net.pending.delete(oldSeq);
    const seq = ++net.seq;
    net.pendingKey.set(ck, seq);
    net.pending.set(seq, { x, y, z, prev, prevM, id: b, m, ck });
    if (net.pending.size > 400) { const k = net.pending.keys().next().value; const q0 = net.pending.get(k); net.pending.delete(k); if (q0 && q0.ck && net.pendingKey.get(q0.ck) === k) net.pendingKey.delete(q0.ck); }
    net.editOut++;
    const msg = { t: 'e', seq, x, y, z, b };
    if (typeof m === 'number') msg.m = m;
    if (wsOk) { try { net.ws.send(JSON.stringify(msg)); } catch (e) {} }
  };
  net.onLocalEdit = (x, y, z, id, prevId) => net.pushEdit(x, y, z, id, null, prevId, null);
  net.onLocalMeta = (x, y, z, m, prevM) => {
    const b = getBlock(x, y, z);
    net.pushEdit(x, y, z, b, m, b, prevM);
  };
  /* 一条 ack / rej 到达：清掉 pending，并在「这一格没有更新的编辑在飞」时才回滚 */
  net.settleEdit = (seq, ok) => {
    const p0 = net.pending.get(seq);
    net.pending.delete(seq);
    if (!p0) return;
    const newest = net.pendingKey.get(p0.ck) === seq;
    if (newest) net.pendingKey.delete(p0.ck);
    if (ok) return;
    net.rejCount++;
    if (newest && !net.pendingKey.has(p0.ck)) applyServerBlock(p0.x, p0.y, p0.z, p0.prev, p0.prevM);
  };

  /* ---------- 网络 ---------- */
  function connect() {
    net.onMsg = (m) => {
      /* ★ v332 多人：客人躺下 / 站起来 —— 只影响那个客人，房主和其他客人的怪照常刷 */
      if (m.t === 'pdie' && m.from)  { guestDead.add(m.from); guestGuard.set(m.from, 1e9); return; }
      if (m.t === 'palive' && m.from) { guestDead.delete(m.from); guestGuard.set(m.from, 20); return; }
      if (m.t === 'ok') {
        net.isHost = !!m.host; net.err = '';
        // 断线期间漏掉的编辑：补上（resync=true 时服务端给的是整表）
        /* ★ 一条都别丢 meta：以前这里只传 e[0..3]，重连后门的开合全部回到「关着」，
           而自己这端看起来是开着的 —— 「联机时门显示的不一样」的一大来源。 */
        for (const e of (m.missed || [])) applyServerBlock(e[0], e[1], e[2], e[3], e[4]);
        if (typeof m.seq === 'number') net.serverSeq = m.seq;
        if (typeof m.time === 'number' && !net.isHost) netTimeApply(m.time);
        // 断线时还在 pending 的编辑重新推一遍（否则这几刀永久丢失）
        const again = Array.from(net.pending.values());
        net.pending.clear(); net.pendingKey.clear();
        for (const p0 of again) {
          const seq2 = ++net.seq;
          net.pending.set(seq2, p0);
          if (p0.ck) net.pendingKey.set(p0.ck, seq2);
          const msg2 = { t: 'e', seq: seq2, x: p0.x, y: p0.y, z: p0.z, b: p0.id };
          if (typeof p0.m === 'number') msg2.m = p0.m;
          try { net.ws.send(JSON.stringify(msg2)); } catch (e) {}
        }
        if (again.length) toast(`Reconnected: resent ${again.length} unconfirmed changes`, 2.2);
      }
      else if (m.t === 'b') {                 // ★ v337 房主广播的船
        const seen = new Set();
        for (const e of (m.u || [])) {
          const gid = e[0] | 0;
          seen.add(gid);
          let g = net.gBoats.get(gid);
          if (!g) {
            const obj = makeBoatModel(e[1] | 0);
            obj.position.set(+e[2], +e[3], +e[4]);
            obj.rotation.y = +e[5];
            scene.add(obj);
            g = { id: gid, wi: e[1] | 0, obj, tx: +e[2], ty: +e[3], tz: +e[4], yaw: +e[5] };
            net.gBoats.set(gid, g);
          }
          g.tx = +e[2]; g.ty = +e[3]; g.tz = +e[4]; g.yaw = +e[5];
        }
        for (const [gid, g] of Array.from(net.gBoats)) {
          if (seen.has(gid)) continue;
          scene.remove(g.obj);
          net.gBoats.delete(gid);
          if (player.riding === g) player.riding = null;
        }
      }
      else if (m.t === 'bi') {                // ★ v337 客人的划船输入（房主结算）
        const b = boats.find(x => x.id === (m.i | 0));
        if (b) b.gst = { fwd: m.fwd | 0, turn: m.turn | 0, t: performance.now() };
      }
      else if (m.t === 'p') {
        net.snaps++; net.lastSnap = performance.now();
        for (const p of (m.u || [])) {
          if (p.i === net.id) continue;
          mtRemoteFoot(p.x, p.y, p.z, p.f | 0, p.i);      // ★ v373 客人的脚步声（客人端调用无害：噪声在本地会被丢掉）
          const r = ensureRemote(p);
          const u = r.obj.userData;
          u.flags = p.f | 0; u.pitch = +p.q || 0;      // 挖掘/疾跑/腾空 状态位 + 俯仰
          // ★ 快照进缓冲，不直接当目标位置：渲染时往回退一段（按实测间隔自适应）在两帧之间插值，
          //   这样 8~12Hz 的网络数据也能变成 60fps 连续运动（A&S 那种顺滑的关键）
          const tNow = performance.now();
          const lastSnap = u.buf[u.buf.length - 1];
          if (lastSnap) {
            const gap = tNow - lastSnap.t;
            if (gap > 10 && gap < 600) u.gap = u.gap ? u.gap * 0.75 + gap * 0.25 : gap;   // 快照间隔 EMA
          }
          u.lastSnapT = tNow;
          u.buf.push({ t: tNow, x: p.x, y: p.y, z: p.z, yaw: p.w, pitch: +p.q || 0, f: p.f | 0 });
          if (u.buf.length > 10) u.buf.shift();
        }
        const alive = new Set((m.u || []).map(x => x.i));
        for (const id of Array.from(net.remotes.keys())) {
          if (alive.has(id)) continue;
          const nm = (net.remotes.get(id) || {}).name || id;
          dropRemote(id);
          toast(`${nm} left the Room`, 2.5);
        }
        if (frOpen) renderLobby();
        /* 房主的时间：只做渐进校正（房主自己不跟自己的回声，避免和自己打起来） */
        if (typeof m.time === 'number' && !net.isHost) netTimeApply(m.time);
        const wasHost = net.isHost;
        net.isHost = (m.host === net.id);
        // ★ 主机迁移：原主机掉线后本端接管，必须清掉手里的「幽灵怪」——
        //   否则它们会和本端新模拟的真怪叠在一起（实测迁移后 B 端同时有 5 个幽灵 + 自己的真怪）。
        if (net.isHost && !wasHost) {
          /* ★ 接管时把幽灵怪「转正」：以前直接清掉 → 房主一退，客人眼前的怪全没了、
             世界立刻安静。现在按 kind/坐标在本地重建真怪（血量也带过来）。 */
          let conv = 0;
          for (const [, g] of Array.from(net.ghosts)) {
            try {
              const mo = spawnMobAt(g.kind, Math.round(g.p.x), Math.round(g.p.y), Math.round(g.p.z), { force: true });
              if (mo) { mo.p.set(g.p.x, g.p.y, g.p.z); if (typeof g.hp === 'number') mo.hp = g.hp; conv++; }
            } catch (e) {}
            scene.remove(g.obj);
          }
          net.ghosts.clear();
          // 掉落物幽灵同样要清：否则接管瞬间「旧幽灵 + 新真掉落物」叠在一起（和怪是同一族 bug）
          for (const [, g] of Array.from(net.dropGhosts)) { scene.remove(g.obj); }
          net.dropGhosts.clear();
          toast(conv ? ('You took over the World host: ' + conv + ' mobs are now simulated by you') : 'You took over the World host: mobs are now simulated by you', 3);
        }
      } else if (m.t === 'e') {
        if (typeof m.q === 'number') net.serverSeq = m.q;
        applyServerBlock(m.x, m.y, m.z, m.b, m.m);
      } else if (m.t === 'vact') {                // 客人操作村民 → 只有房主结算（真身在这边）
        if (net.isHost) applyVact(m);
      } else if (m.t === 'hit') {
        if (net.isHost) {                          // 只有主机的怪是真的
          for (const mo of (typeof mobs !== 'undefined' ? mobs : [])) {
            if (mo.nid === m.i && !mo.dying) {
              mtNoteNoise(mo.p.x, mo.p.y, mo.p.z);   // ★ v370：客人在坑里打怪也是声响
              mo.hp -= (m.d || 1); mo.flash = 0.24; mo.aggro = 16;
              /* ★ 客人打怪也要有击退：以前这里只扣血，主机的本地挥砍却推 7.4 格/秒，
                 客人看到的动物就"打不动"。方向用客人报来的 kx/kz（我 → 怪）。 */
              const kxk = Number(m.kx), kzk = Number(m.kz);
              const kd = Math.hypot(kxk || 0, kzk || 0);
              const knK = MOB_DEFS[mo.kind] && MOB_DEFS[mo.kind].noKnock ? 0.12 : 1;   // ★ v347 霜灵几乎推不动
              if (kd > 0.01) {
                mo.v.x = (kxk / kd) * 7.4 * knK; mo.v.z = (kzk / kd) * 7.4 * knK; mo.v.y = 5.2 * knK; mo.knockT = 0.34;
              } else {                                       // 老客户端没带方向：按「房主 → 怪」推
                const ax = mo.p.x - player.p.x, az = mo.p.z - player.p.z, ad = Math.hypot(ax, az) || 1;
                mo.v.x = (ax / ad) * 7.4 * knK; mo.v.z = (az / ad) * 7.4 * knK; mo.v.y = 5.2 * knK; mo.knockT = 0.34;
              }
              if (mo.hp <= 0) startMobDeath(mo);
              break;
            }
          }
        }
      } else if (m.t === 'claimres') {            // 服务端裁决：这件掉落物归不归我
        const cb = net.claimCb && net.claimCb.get(String(m.i));
        if (cb) { net.claimCb.delete(String(m.i)); cb(!!m.ok); }
      } else if (m.t === 'taken') {               // 别人先抢到了：把幽灵/真掉落物都收掉
        const g = net.dropGhosts.get(m.i);
        if (g) { scene.remove(g.obj); net.dropGhosts.delete(m.i); }
        net.picked.add(String(m.i));
        if (net.picked.size > 400) net.picked.clear();
        if (net.isHost) {
          const di = drops.findIndex(x => String(x.nid) === String(m.i));
          if (di >= 0) { scene.remove(drops[di].obj); try { drops[di].obj.geometry.dispose(); } catch (e) {} drops.splice(di, 1); }
        }
      } else if (m.t === 'hurt') {                // 房主那边替你结算的「怪打了你」
        if (typeof m.d === 'number' && m.d > 0) {
          hurtPlayerFrom(Number(m.sx) || player.p.x, Number(m.sz) || player.p.z, Math.min(20, m.d));
        }
      } else if (m.t === 'mm') {                  // 别人解开的地图格子 → 并进本地小地图
        const n = mmMergeBlob(m.v);
        if (n > 40) toast('Map update: +' + n + ' slots', 1.5);
      } else if (m.t === 'mach') {                // 别人点了炉子：我这边没在烧就接上（同一台共享的炉）
        if (m.kind === 'furnace' && !furnaceJob && m.v && m.v.out) adoptFurnaceJob(m.v);
      } else if (m.t === 'mtst') {                // ★ v370 房主广播的陨石坑预警状态
        mtApplyRemote(m);
      } else if (m.t === 'time') {                // 房主的昼夜时间
        /* ★ 老守护进程发 {v}、新的发 {time}：两个都收 —— 以前只认 v，
           而服务端发的是 {t:'time', time:...} → 这条分支等于从来没生效过（客人时间永远不同步）。 */
        netTimeApply(typeof m.v === 'number' ? m.v : m.time);
      } else if (m.t === 'm') {
        syncGhosts(m.u || []);
      } else if (m.t === 'ch') {                  // 别人改了这个箱子：同表覆盖
        if (m.k) {
          chestInv.set(m.k, m.slots);
          const openK = openChestPos ? (openChestPos.x + ',' + openChestPos.y + ',' + openChestPos.z) : '';
          if (openK === m.k) { renderChest(); toast('Chest contents synced', 1.4); }
        }
      } else if (m.t === 'd') {
        net.syncDropGhosts(m.u || []);
      } else if (m.t === 'drop') {                // 客人挖出的掉落物：主机这里生成真的（沿用他上报的 nid）
        const [nid, id, n, x, y, z] = m.u || [];
        if (net.isHost && nid && isItem(id) && n > 0 && !drops.some(d => d.nid === nid)) {
          spawnDrop(id, n, x, y + 0.2, z, { nid, fromHost: true });
        }
      } else if (m.t === 'pick') {
        const g = net.dropGhosts.get(m.i);
        if (g) { scene.remove(g.obj); net.dropGhosts.delete(m.i); }
        if (net.isHost) {                         // 主机手里那个掉落物真的删掉
          // 用字符串比较：客人上报的 nid 是 "g<pid>:<n>"，主机自己的是数字，类型不一致会漏删
          const di = drops.findIndex(x => String(x.nid) === String(m.i));
          if (di >= 0) { scene.remove(drops[di].obj); drops.splice(di, 1); }
          if (net.devOk) console.log('[bw] pick', m.i, 'di=', di, 'left=', drops.length);
        } else if (net.devOk) console.log('[bw] pick(guest)', m.i, 'ghost=', !!g);
      } else if (m.t === 'act') {                 // 别人的挥砍/放置：远端形象播一下
        const r = net.remotes.get(m.i);
        if (r && r.obj.userData) {
          r.obj.userData.swing = 0.4;
          r.obj.userData.swingType = m.a || 'attack';
        }
      } else if (m.t === 'ack') {
        net.settleEdit(m.seq, true);
      } else if (m.t === 'rej') {
        net.settleEdit(m.seq, false);
        net.rejLast = m.e || '';
        if (net.rejCount <= 3 || net.rejCount % 50 === 0) toast('Server rejected this change: ' + (m.e || ''), 1.6);
      } else if (m.t === 'req' || m.t === 'acc' || m.t === 'deny' || m.t === 'f' || m.t === 'inv') {
        net.onSocial(m);
      } else if (m.t === 'left') {
        dropRemote(m.i);
      } else if (m.t === 'err') {
        if (m.e === 'no_seat') { net.err = 'no_seat'; fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
          body: JSON.stringify({ a: 'join', code: net.code, pid: net.id, name: net.nick, tok: acctTok() }) })
          .then(r => r.json()).then(d2 => { if (d2.ok) { net.err = ''; reconnect(); } }).catch(() => {}); }
      }
    };
    if (IS_BRIDGE) { net.connected = true; net.err = ''; return; }   // 桥模式：靠 sync 轮询，不开 ws
    let ws;
    try { ws = new WebSocket(WSURL); } catch (e) { net.err = 'ws_bad_url'; return; }
    net.ws = ws;
    ws.onopen = () => {
      net.connected = true; net.err = '';
      ws.send(JSON.stringify({ t: 'hello', code: net.code, id: net.id, name: net.nick, since: net.serverSeq, sk: LOOK.skin, cl: LOOK.cloth, hr: LOOK.hair, hs: LOOK.hs, oh: (player.off ? player.off.id : 0), skn: skinHash(LOOK.skinSrc), skd: (LOOK.skinSrc === 'custom' ? skinPngData() : '') }));
    };
    ws.onclose = () => { net.connected = false; setTimeout(() => { if (net.active) connect(); }, 1500); };
    net.reconnect = () => { try { ws.close(); } catch (e) {} };
    ws.onerror = () => { net.err = 'ws_error'; };
    ws.onmessage = ev => {
      net.netBytes += ev.data.length;
      let mm; try { mm = JSON.parse(ev.data); } catch (e) { return; }
      net.onMsg(mm);
    };
  }

  /* ---------- HUD：数字长在界面上 ---------- */
  let hud = null;
  function drawHud() {
    if (!hud) {
      hud = document.createElement('div');
      hud.id = 'netHud';
      hud.style.cssText = 'position:fixed;left:50%;top:8px;transform:translateX(-50%);z-index:30;'
        + 'font:12px/1.5 ui-monospace,monospace;color:#cfe8ff;background:rgba(8,18,30,.72);'
        + 'border:1px solid rgba(120,200,255,.28);border-radius:8px;padding:4px 10px;pointer-events:none;white-space:nowrap';
      document.body.appendChild(hud);
    }
    // 远端渲染滞后（实测）：快照间隔 × 1.12，说明这一局"别人动起来有多跟手"
    let lagMax = 0;
    for (const r of net.remotes.values()) lagMax = Math.max(lagMax, r.obj.userData.lag || 0);
    hud.innerHTML = `<b style="color:${net.connected ? '#7ef0a0' : '#ff7a7a'}">${net.connected ? '●' : '○'}</b> `
      + `Multiplayer ${net.code}${net.isHost ? ' · Host' : ''} · <b>${net.rtt.toFixed(0)}ms</b> · snapshot ${net.snapHz.toFixed(0)}Hz · `
      + `Pending <b style="color:${net.pending.size ? '#ffcf6b' : '#7ef0a0'}">${net.pending.size}</b> · `
      + `${net.mode === 'poll' ? ' · Polling ' + Math.round((net.pollEvery || 0.09) * 1000) + 'ms' : ' · WS'} remote ${net.remotes.size}${net.isHost ? '' : ' · Ghosts ' + net.ghosts.size}`
      + ` · lag ${Math.round(lagMax)}ms · seq ${net.serverSeq} · upstream edits ${net.editOut} · rejected ${net.rejCount}${net.rejCount && net.rejLast ? '(' + net.rejLast + ')' : ''}`
      + (net.err ? ` · <span style="color:#ff9a6b">${net.err}</span>` : '');
  }

  /* ---------- 每帧 ---------- */
  /* 远端渲染延迟插值：把 8~10Hz 的快照缓冲起来，渲染时间往回退 130ms 在两帧之间取插值。
   * 这一条是「丝滑」的最大来源 —— 位置/朝向变成连续函数，网络抖动不会传到画面上。 */
  const REM_LAG = 130;
  const HEAD_PITCH_SIGN = 1;   // 远端抬头/低头方向：实测（模型正面 -Z）正号 = 抬头；看着反了就改成 -1
  net.sampleRemote = (u, nowMs) => {
    const b = u.buf;
    if (!b || !b.length) return null;
    if (b.length === 1) {
      const q0 = b[0];
      return { x: q0.x, y: q0.y, z: q0.z, yaw: q0.yaw, pitch: q0.pitch, f: q0.f, spd: 0 };
    }
    // 渲染滞后按「实测快照间隔」自适应：间隔大（网络慢）就多等一点保证有插值帧，间隔小就少等，直接降延迟
    const lag = u.lag = Math.min(190, Math.max(70, (u.gap || 110) * 1.12));
    const tgt = nowMs - lag;
    let i = b.length - 1;
    while (i > 0 && b[i].t > tgt) i--;
    const a = b[i], c = b[Math.min(b.length - 1, i + 1)];
    const span = Math.max(1, c.t - a.t);
    let f = (tgt - a.t) / span;
    if (!isFinite(f)) f = 1;
    // 丢包时最多外推 30%；如果渲染时刻已经超出最后一条快照太多（>220ms），冻结在最后一条，
    // 否则外推久了会"冲出去再被拉回来"，就是玩家说的「像传送」。
    const hole = tgt - c.t;
    f = hole > 220 ? 1 : Math.max(0, Math.min(1.3, f));
    let dyw = c.yaw - a.yaw;
    while (dyw > Math.PI) dyw -= Math.PI * 2;
    while (dyw < -Math.PI) dyw += Math.PI * 2;
    return {
      x: a.x + (c.x - a.x) * f, y: a.y + (c.y - a.y) * f, z: a.z + (c.z - a.z) * f,
      yaw: a.yaw + dyw * f, pitch: a.pitch + (c.pitch - a.pitch) * f, f: a.f,
      spd: Math.hypot(c.x - a.x, c.z - a.z) / (span / 1000),
    };
  };

  net.tick = (dt) => {
    const nowMs = performance.now();
    /* ★ v362：房间里只有自己时不生成/不广播怪快照、掉落物、船。房主最常见的使用场景就是
       「先自己进去建一会儿，等朋友来」—— 以前这期间仍然每 0.15s 把 24 只怪序列化 + JSON.stringify
       发一遍、每 0.2s 打包一次掉落物和船，纯属白烧 CPU（而且这段工作正好抢在地形流式加载前面）。 */
    const alone = net.remotes.size === 0;
    net.sendT += dt;
    if (!IS_BRIDGE && net.sendT >= 0.1 && net.ws && net.ws.readyState === 1) {
      net.sendT = 0;
      try {
        net.ws.send(JSON.stringify({ t: 'p', x: +player.p.x.toFixed(2), y: +player.p.y.toFixed(2), z: +player.p.z.toFixed(2), w: +player.yaw.toFixed(2), q: +player.pitch.toFixed(2), f: net.myFlags(), sk: LOOK.skin, cl: LOOK.cloth, hr: LOOK.hair, hs: LOOK.hs, oh: (player.off ? player.off.id : 0) }));
      } catch (e) {}
    }
    // ── 公网轮询模式：一个请求同时上传位置/编辑、取回消息（~8Hz）
    if (IS_BRIDGE) {
      net.pollT += dt;
      if (net.inFlight && performance.now() - (net.inFlightAt || 0) > 800) net.inFlight = false;   // 兜底：卡死的请求别把整条链路堵住
      if (net.pollT >= (net.pollEvery || 0.09) && !net.inFlight) {   // 节拍自适应：桥慢就别堆请求，桥快就压到 60ms 降延迟
        net.pollT = 0;
        net.inFlight = true; net.inFlightAt = performance.now();
        const reqT0 = net.inFlightAt;
        // ★ 只发「还没发过 / 超过 1.5s 没被 ack」的编辑。以前每个 tick 把全部 pending 原样重发一遍，
        //   8Hz × 在飞的编辑数 很容易顶到服务端 25 次/秒的上限（applyEdit 按**调用次数**计数）→ 被拒 → 客户端回滚，
        //   表现就是公网模式下「挖掉/放下的方块自己弹回来」。
        const nowMs = Date.now();
        const pend = [];
        for (const [seq, p0] of net.pending) {
          if (p0.nextAt && nowMs < p0.nextAt) continue;
          p0.nextAt = nowMs + 1500;
          const pe = { seq, x: p0.x, y: p0.y, z: p0.z, b: p0.id };
          if (typeof p0.m === 'number') pe.m = p0.m;
          pend.push(pe);
          if (pend.length >= 20) break;
        }
        // 桥请求必须有超时：偶尔一次 PHP 卡 2 秒会把整条链路堵住（表现就是"位置停一下再瞬移"）
        const ctl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
        const toT = setTimeout(() => { try { if (ctl) ctl.abort(); } catch (e) {} }, 2000);
        fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' }, signal: ctl ? ctl.signal : undefined, body: JSON.stringify(Object.assign({
          a: 'sync', code: net.code, pid: net.id, name: net.nick, tok: acctTok(), sk: LOOK.skin, cl: LOOK.cloth, hr: LOOK.hair, hs: LOOK.hs, oh: (player.off ? player.off.id : 0),
          /* ★ 皮肤变了（换了 PNG / 新颜色）必须把 skd 一起传上去，否则服务端只有新哈希没有数据，
             别人 getskin 拿到空 → 只能画一张"按颜色生成的假皮肤"（这就是"联机皮肤不对"）。
             只在上报哈希变化时带一次，别每 100ms 塞 30KB。 */
          skn: (net._skh = skinHash(LOOK.skinSrc)),
          ...(net._skh !== net.skinSent ? { skd: (LOOK.skinSrc === 'custom' ? skinPngData() : '') } : {}),
          x: +player.p.x.toFixed(2), y: +player.p.y.toFixed(2), z: +player.p.z.toFixed(2),
          w: +player.yaw.toFixed(2), q: +player.pitch.toFixed(2), edits: pend, f: net.myFlags(),
        }, net.isHost
          /* ★ 轮询模式没有 ws：房主的时间必须挂在这条 sync 上上行，否则服务端的时间永远停在开房那一刻 */
          ? { mobs: net.mobCache || [], drops: net.dropCache || [], time: +worldTime.toFixed(2) }
          : {})) }).then(r => r.json()).then(d => {
          if (!d.ok) { net.err = d.e || 'sync'; net.connected = false; return; }
          net.connected = true; net.err = ''; net.syncs++;
          if (net._skh) net.skinSent = net._skh;      // 皮肤数据已随这次同步送达服务端（下次变了才重传）
          if (typeof d.seq === 'number') net.serverSeq = d.seq;
          net.isHost = (d.host === net.id);
          if (typeof d.time === 'number' && !net.isHost) netTimeApply(d.time);   // 房间时间（服务端已按墙钟推算）
          for (const s of (d.ack || [])) net.settleEdit(s > 0 ? s : -s, s > 0);
          for (const m of (d.out || [])) net.onMsg(m);
        }).catch((e2) => {
          if (!(e2 && e2.name === 'AbortError')) { net.connected = false; net.err = 'net'; }
        }).finally(() => {
          clearTimeout(toT);
          net.inFlight = false;
          // ★ 别用 performance.now() 前后差算 RTT：无头页面里那测到的是「事件循环 + 渲染帧」，
          //   实测 10ms 的请求会被量成 1800ms。取 Resource Timing 的 duration 才是真实耗时。
          try {
            const es = performance.getEntriesByType('resource').filter(en => en.name.indexOf(EP) >= 0 && en.name.indexOf('?t=') < 0);
            const last = es[es.length - 1];
            if (last && last.duration > 0) {
              net.pollRtt = net.pollRtt ? net.pollRtt * 0.7 + last.duration * 0.3 : last.duration;
              // 节拍 = RTT 的 0.9 倍，夹在 60~200ms：桥快就多问几次（降延迟），桥慢就少问（不加剧拥塞）
              net.pollEvery = Math.min(0.2, Math.max(0.06, (net.pollRtt * 0.9) / 1000));
            }
          } catch (e3) {}
        });
      }
    }

    // 主机每 0.15s 生成一次怪快照（WS 直接发；轮询模式挂在 sync 请求上，见下方 poll 分支）
    // 外观/皮肤变了就推一次（换肤色、换发型、上传新 PNG 都算）
    net.lookT = (net.lookT || 0) + dt;
    if (net.lookT > 0.5) {
      net.lookT = 0;
      const sig = LOOK.skin + ':' + LOOK.cloth + ':' + LOOK.hair + ':' + LOOK.hs + ':' + skinHash(LOOK.skinSrc);
      if (sig !== (net.lookSig || '')) net.pushLook();
    }

    if (net.isHost && !alone) {
      net.mobT += dt;
      if (net.mobT >= 0.15) {
        net.mobT = 0;
        const u = [];
        const cand = [];                       // {d, row}：按「离最近玩家」排序，房间再挤也能看到身边的怪
        for (const m of (typeof mobs !== 'undefined' ? mobs : [])) {
          if (m.hp <= 0 && !m.dying) continue;
          if (!m.obj) continue;
          m.nid = m.nid || (net.mobSeq = (net.mobSeq || ((Math.floor(Math.random() * 90000) + 1000) * 10)) + 1);
          // 字段含义：nid, kind, x, y, z, 朝向, hp, 水平速度,
          //           dk = 死亡进度秒数（0=活着的；有值=正在倒地/躺尸，客人照着播同一套死亡姿势）,
          //           an = 攻击计数器（每次挥击/投掷 +1，客人看到变了就播一次前扑/抬臂）,
          //           rc = 村民招募状态 [已入队, 跟随中, 需求物品 id, 需要数量, 已交数量]（只有村民才有）
          const row = [m.nid, m.kind, +m.p.x.toFixed(2), +m.p.y.toFixed(2), +m.p.z.toFixed(2),
                       +m.obj.rotation.y.toFixed(2), Math.round(m.hp), +Math.hypot(m.v.x, m.v.z).toFixed(2),
                       m.dying ? +Math.min(99, m.dieT).toFixed(2) : 0, m.atkN | 0];
          if (m.recruit) row.push([m.recruit.hired ? 1 : 0, m.recruit.follow ? 1 : 0,
                                   m.recruit.want.id | 0, m.recruit.want.need | 0, m.recruit.want.got | 0]);
          let dmin = Math.hypot(m.p.x - player.p.x, m.p.z - player.p.z);
          for (const [, r] of net.remotes) {
            const dd = Math.hypot(m.p.x - r.obj.position.x, m.p.z - r.obj.position.z);
            if (dd < dmin) dmin = dd;
          }
          cand.push({ d: dmin, row });
          if (cand.length >= 64) break;
        }
        cand.sort((a, b) => a.d - b.d);        // ★ 先按距离排，再取前 24 —— 以前按数组顺序截断，靠后的怪客人根本看不到
        for (let i = 0; i < cand.length && i < 24; i++) u.push(cand[i].row);
        net.mobCache = u;
        if (net.ws && net.ws.readyState === 1) { try { net.ws.send(JSON.stringify({ t: 'm', u })); } catch (e) {} }
      }
      /* 每 5 秒把昼夜时间发给其他人：以前两端各走各的 worldTime → 一边黑天一边白天 */
      net.timeT = (net.timeT || 0) + dt;
      if (net.timeT > 5) {
        net.timeT = 0;
        if (net.ws && net.ws.readyState === 1) { try { net.ws.send(JSON.stringify({ t: 'time', time: worldTime })); } catch (e) {} }
      }
    }
    const kG = Math.min(1, dt * 10);
    for (const g of net.ghosts.values()) {
      g.obj.position.x += (g.tx - g.obj.position.x) * kG;
      g.obj.position.y += (g.ty - g.obj.position.y) * kG;
      g.obj.position.z += (g.tz - g.obj.position.z) * kG;
      let dg = g.rot - g.obj.rotation.y;
      while (dg > Math.PI) dg -= Math.PI * 2;
      while (dg < -Math.PI) dg += Math.PI * 2;
      g.obj.rotation.y += dg * kG;
      /* ★ 客人端补上「动作 / 受伤 / 血条」三件事（以前全缺，只有平移+转身）：
       *   ① 迈腿摆臂 + 身体起伏 + 头盯人 → 直接复用 animateMob（和房主同一份动画代码）
       *   ② 挨打闪红 → hp 掉了就在本地播 0.24s 红色自发光
       *   ③ 血条 → 朝向镜头 + 按血量缩短变色（updateMobBar 和房主共用） */
      const P = g.parts;
      if (!P) continue;
      const dx = camera.position.x - g.obj.position.x, dz = camera.position.z - g.obj.position.z;
      const dist = Math.hypot(dx, dz);
      /* ★ 死亡：主机只说「我这边这只死了几秒」，客人拿同一个 applyMobDeathPose 播倒地→躺尸→缩小。
       *   以前快照直接过滤掉 hp<=0 的怪，客人看到的是「啪一下消失」，看不到倒地。 */
      if (g.dying) {
        g.dieT += dt;                                   // 本地继续走，15Hz 快照之间也不会卡顿
        applyMobDeathPose(P, g.dieT, g.obj, g.obj.position.y);
        continue;
      }
      g.v.z = g.spd || 0;                       // animateMob 只看水平速度的模长
      g.flash = Math.max(0, (g.flash || 0) - dt);
      try { animateMob(g, dt, dx, dz, dist); } catch (e) {}
      /* ★ v349：远程怪放箭后 0.55 秒内举弓（animateMob 之后再覆盖手臂，才不会被走路摆臂冲掉） */
      if (g.bowT > 0) {
        g.bowT -= dt;
        if (P.arm1) P.arm1.rotation.x = -1.45 + (1 - Math.min(1, g.bowT / 0.55)) * 1.2;
      }
      updateGhostArrows();                      // 视觉箭矢（时间驱动，重复调用无副作用）
      const em = g.flash > 0 ? 0xa03030 : 0x000000;
      if (P.bodyMat && P.bodyMat.emissive) P.bodyMat.emissive.setHex(em);
      if (P.headMat && P.headMat.emissive) P.headMat.emissive.setHex(em);
      updateMobBar(P, (typeof g.hp === 'number' ? g.hp : g.maxHp), g.maxHp, dist);
    }
    for (const r of net.remotes.values()) {
      const u = r.obj.userData;
      const s = net.sampleRemote(u, nowMs);
      if (!s) continue;
      /* ★ v335 游泳：状态位 bit3 → 整个人前倾成「俯冲」姿态，身体整体抬高 0.55 格
         （不然绕脚底转 66° 会半个身子插进地里）。 */
      u.swimK += (((s.f & 8) ? 1 : 0) - u.swimK) * Math.min(1, dt * 5);
      const swimK = u.swimK;
      // 位置直接用缓冲插值结果（它本身已经连续，再 lerp 只是白加延迟）
      r.obj.position.set(s.x, s.y + swimK * 0.55, s.z);
      r.obj.rotation.x = swimK * 1.15;                 // 俯冲角：66°
      let dy = s.yaw - r.obj.rotation.y;
      while (dy > Math.PI) dy -= Math.PI * 2;
      while (dy < -Math.PI) dy += Math.PI * 2;
      r.obj.rotation.y += dy * Math.min(1, dt * 22);
      const yawRate = dy / Math.max(dt, 1e-3);

      /* ── 远端玩家的动作（别人能看到的动画）
       * 只有位置/朝向是网络同步的，四肢的动作全部由「位移速度 + 状态位 + 一次性能量」本地推算：
       *   走路/疾跑 → 摆臂甩腿 + 身体起伏；挖掘位 → 前臂连续凿；挥砍事件 → 整条胳膊抡一下；
       *   腾空位 → 收腿抬臂。这样只多 1 个字节的状态位，不用为每个动作都发消息。 */
      // 速度用「两帧快照」算，而不是逐帧位置差 —— 网络抖一下不会让腿抽
      u.spd += (s.spd - u.spd) * Math.min(1, dt * 12);
      const walkAmt = clamp01(u.spd / CFG.WALK);
      u.sprintK += (clamp01((u.spd - CFG.WALK * 0.9) / Math.max(0.1, CFG.SPRINT - CFG.WALK * 0.9)) - u.sprintK) * Math.min(1, dt * 6);
      const airNow = (s.f & 4) ? 1 : 0;
      if (u.airPrev === 1 && airNow === 0) u.landK = 1;      // 「腾空→着地」→ 落地缓冲
      u.airPrev = airNow;
      u.airK += (airNow - u.airK) * Math.min(1, dt * 9);
      u.mineK += (((s.f & 1) ? 1 : 0) - u.mineK) * Math.min(1, dt * 12);
      u.landK = Math.max(0, u.landK - dt * 3.4);
      u.walk += dt * (6 + 9 * u.sprintK) * (walkAmt > 0.04 ? 1 : 0);
      const stride = Math.sin(u.walk);
      const airK = u.airK, landK = u.landK;

      /* 所有动作先「叠加成目标角度」，再用阻尼追上去。
       * 直接赋值的话，动作切换/丢包那一帧肢体就会硬跳；阻尼追随让每根骨头都是有质量的。 */
      /* ★ v335 游泳：双臂交替「自由泳划水」（相位差 π），双腿小幅打水，节奏和手部动画同源 */
      const swPho = nowMs / 1000;
      const armSwimL = Math.sin(swPho * 2.6) * 1.45 - 0.55;
      const armSwimR = Math.sin(swPho * 2.6 + Math.PI) * 1.45 - 0.55;
      const legSwim = Math.sin(swPho * 5.2) * 0.42;
      const legLT = stride * 0.62 * walkAmt * (1 - airK * 0.7) - airK * 0.35 + landK * 0.25 + swimK * (legSwim - 0.28);
      const legRT = -stride * 0.62 * walkAmt * (1 - airK * 0.7) + airK * 0.20 + landK * 0.25 - swimK * (legSwim + 0.28);
      const armSwing = stride * (0.50 + 0.35 * u.sprintK) * walkAmt;
      const armLT = -armSwing - airK * 0.45 - landK * 0.20 + swimK * armSwimL;
      let armRT = armSwing - airK * 0.30 - landK * 0.25 + swimK * armSwimR;
      let foreRT = 0;
      if (u.swing > 0) {
        u.swing = Math.max(0, u.swing - dt);
        const a = Math.sin(clamp01(1 - u.swing / 0.4) * Math.PI);
        // ★ 符号：armR.rotation.x 为正是「手往前甩」（模型正面是 -Z，实测 hand.z 从 0 → -0.25）。
        //   以前这里写成负号，等于整条胳膊往背后抡 —— 玩家看到的就是"动作全反了"。
        armRT += a * (u.swingType === 'place' ? 0.55 : 1.25);
        foreRT += a * (u.swingType === 'place' ? 0.30 : 0.75);
      }
      if (u.mineK > 0.02) {
        const a = Math.sin((((nowMs / 1000) * 2.2) % 1) * Math.PI);
        armRT += a * 0.95 * u.mineK;
        foreRT += a * 0.85 * u.mineK;
      }
      if (walkAmt < 0.04 && u.mineK < 0.02 && u.swing <= 0) armRT += Math.sin(nowMs / 900 + u.phase) * 0.03;
      // 阻尼频率：前臂最快、腿最慢 —— 看起来有质量差
      const dampA = 1 - Math.exp(-30 * dt), dampF = 1 - Math.exp(-36 * dt), dampL = 1 - Math.exp(-24 * dt);
      u.armL.rotation.x += (armLT - u.armL.rotation.x) * dampA;
      u.armR.rotation.x += (armRT - u.armR.rotation.x) * dampA;
      u.foreR.rotation.x += (foreRT - u.foreR.rotation.x) * dampF;
      u.legL.rotation.x += (legLT - u.legL.rotation.x) * dampL;
      u.legR.rotation.x += (legRT - u.legR.rotation.x) * dampL;
      // 转身惯性：快速左右转身时身体轻微侧倾（A&S 里很明显的一个细节）
      const rollT = clamp(-yawRate * 0.05, -0.07, 0.07);
      r.obj.rotation.z += (rollT - r.obj.rotation.z) * Math.min(1, dt * 10);
      // 身体：疾跑前倾 + 走路起伏 + 落地屈膝压身 + 头随俯仰点头
      // ★ 基准高度一律取模型自带值（u.base），不再写死 1.06 / 1.62：
      //   base.torso = 18 px（躯干中心，躯干顶 = 24 px = 颈部）
      //   base.head  = 24 px（颈根，正好贴住躯干顶）
      //   base.arm*  = 24 px（肩点，和躯干顶同高）
      //   这三者原本就是对齐的；旧代码把它们顶到 1.06 / 1.62，才出现「头悬空 4 px、肩线低 1 px」。
      u.torso.rotation.x = u.sprintK * 0.12 + landK * 0.10 - swimK * 0.10;   // 游泳时腰略反弓
      const bobY = Math.abs(stride) * 0.02 * walkAmt - landK * 0.05;
      const bY = u.base || (u.base = { torso: 18 * MOB_PX, head: 24 * MOB_PX, armL: 24 * MOB_PX, armR: 24 * MOB_PX });
      u.torso.position.y = bY.torso + bobY;
      u.head.position.y = bY.head + bobY * 0.8;
      u.armL.position.y = bY.armL + bobY;          // 肩随躯干一起起伏，肩线始终贴着躯干顶
      u.armR.position.y = bY.armR + bobY;
      /* 游泳时身体前倾 66°，头要反向抬回来才能看前方 */
      u.head.rotation.x = HEAD_PITCH_SIGN * clamp((u.pitch || 0) * 0.45, -0.55, 0.55) - swimK * 1.0;
    }
    // 主机每 0.2s 广播掉落物；客人每 5s 把背包存回服务端
    net.dropT = (net.dropT || 0) + dt;
    if (net.dropT >= 0.2) { net.dropT = 0; if (net.isHost && !alone) { net.pushDrops(); net.pushBoats(); } }
    net.invT = (net.invT || 0) + dt;
    if (net.invT >= 5) { net.invT = 0; if (!net.lid && net.active) net.pushInv(); }
    net.pullT += dt;
    if (net.pullT >= 2) {
      net.pullT = 0;
      if (Math.hypot(player.p.x - net.lastPull.x, player.p.z - net.lastPull.z) > 48) net.pullRegion();
    }
    net.hudT += dt;
    if (net.hudT >= 0.5) {
      net.hudT = 0;
      const now = performance.now();
      const el = Math.max(0.5, (now - (net.hzT || now - 500)) / 1000);
      net.snapHz = Math.min(30, net.snaps / el);      // 夹上限：被节流的后台页会算出 40+ 的假频率
      net.snaps = 0; net.hzT = now;
      drawHud();
    }
    net.pingT += dt;
    if (net.pingT >= 2) {
      net.pingT = 0;
      // ★ RTT 必须取 Resource Timing 的 duration：用 performance.now() 前后差测到的是
      //   「事件循环 + 渲染帧」，实测会把 3ms 的本地往返量成 2399ms（这个坑我在大乱斗里踩过一次）。
      const tag = Date.now();
      fetch(EP + '?t=' + tag, { method: 'POST', headers: { 'content-type': 'text/plain' }, body: JSON.stringify({ a: 'ping' }) })
        .then(r => r.text()).then(() => {
          // 桥模式下 URL 是 bwmp.php?t=…，所以按 ?t= 数字匹配（以前只匹配 /api?t= → 桥模式永远显示 0ms）
          const es = performance.getEntriesByType('resource').filter(e => /[?&]t=\d+/.test(e.name));
          const e = es[es.length - 1];
          net.rtt = e ? e.duration : 0;
        }).catch(() => { net.rtt = -1; });
    }
  };

  /* ---------- 进服 ----------
   * 客人：join 拿 seed → 用同一个 seed 生成同一片地形。
   * 房主：host 把「我现在这个单机世界」的 seed + 已有改动上传成房间，然后 startGame(自己的世界) ——
   *       开房后地形/背包/建筑原样还在，接着玩；房间码跟世界绑死，明天再开还是同一个房间。 */
  const isHostMode = q.get('host') === '1' && !!q.get('lid');
  net.lid = isHostMode ? String(q.get('lid')) : '';
  const hostMeta = net.lid ? worldMeta(net.lid) : null;
  const hostSeed = hostMeta ? (hostMeta.seed | 0) : 0;
  net.wname = (hostMeta && hostMeta.name) || '';
  /* 房主进房时把自己存档里的坐标带上（服务端 full 同步走不通时还能回退到附近 ±128） */
  let hostPos = { x: 0, z: 0 };
  if (hostMeta) {
    try {
      const dd = JSON.parse(localStorage.getItem(worldKey(hostMeta.id)) || 'null');
      if (dd && dd.player) hostPos = { x: Math.round(dd.player.x) | 0, z: Math.round(dd.player.z) | 0 };
    } catch (e) {}
  }

  // 开房后把这个世界的已有改动分批同步进房间（服务端幂等合并，重复开房不会翻倍）
  function uploadMyWorld() {
    const pairs = Array.from(edits.entries());
    let i = 0, added = 0;
    const CH = 800;
    const step = () => {
      if (i >= pairs.length) {
        if (pairs.length) toast(`Room loaded ${pairs.length} changes from your World`, 3.5);
        return;
      }
      const chunk = pairs.slice(i, i + CH); i += CH;
      fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' },
        body: JSON.stringify({ a: 'host', code: net.code, pid: net.id, name: net.nick, tok: acctTok(), chunk: true, edits: chunk }) })
        .then(r => r.json()).then(d => { if (d && d.ok) added += d.added || 0; setTimeout(step, 30); })
        .catch(() => setTimeout(step, 500));
    };
    if (pairs.length) step();
  }

  fetch(EP, {
    method: 'POST', headers: { 'content-type': 'text/plain' },
    body: JSON.stringify(isHostMode
      ? { a: 'host', code: net.code, pid: net.id, name: net.nick, tok: acctTok(), wname: net.wname || '', kind: MODE, lid: net.lid || '', time: +worldTime.toFixed(2), sk: LOOK.skin, cl: LOOK.cloth, hr: LOOK.hair, hs: LOOK.hs, oh: (player.off ? player.off.id : 0), skn: skinHash(LOOK.skinSrc), skd: (LOOK.skinSrc === 'custom' ? skinPngData() : ''), seed: hostSeed, x: hostPos.x, z: hostPos.z, r: 128, full: 1 }
      : { a: 'join', code: net.code, pid: net.id, name: net.nick, tok: acctTok(), sk: LOOK.skin, cl: LOOK.cloth, hr: LOOK.hair, hs: LOOK.hs, oh: (player.off ? player.off.id : 0), skn: skinHash(LOOK.skinSrc), skd: (LOOK.skinSrc === 'custom' ? skinPngData() : ''), x: 0, z: 0, r: 128 }),
  }).then(r => r.json()).then(d => {
    // 进服后把 URL 洗干净：否则「世界」按钮 reload / 刷新 / iOS 恢复标签页都会再自动 join 一次
    const cleanUrl = () => { try { history.replaceState(null, '', location.pathname); } catch (e) {} };
    if (!d.ok) {
      net.active = false; cleanUrl();
      if (d.e === 'need_login') {
        toast('Sign in to play Multiplayer (offline is single player only)', 6);
        MPUI.show('list'); MPUI.msg2('Sign in to play Multiplayer: without signing in it\'s single player only and Worlds live only on this device');
      } else {
        toast(d.e === 'seed_mismatch' ? 'That Room code is taken by another Save — host from a different World' : ('Multiplayer join failed: ' + (d.e || '?')), 6);
      }
      if (window.__bwWireEntry) window.__bwWireEntry();
      return;
    }
    cleanUrl();
    if (d.id && d.id !== net.id) { net.id = d.id; toast('Name taken — in this Room you\'re called ' + d.id, 4); }
    if (!isHostMode) { try { localStorage.setItem('bw_world', net.code); } catch (e) {} }
    net.isHost = !!d.isHost;
    // 房主：开「我自己那个世界」的存档（seed 相同 → 地形/背包/建筑原样带进房间）
    const w = (isHostMode && hostMeta)
      ? hostMeta
      : { id: 'mp_' + net.code, name: 'Multiplayer Room ' + net.code, seed: d.seed | 0, mode: 'survival' };
    /* ★ 房间种子以服务端为准（seedLock）：
       - 客人：本地可能还留着这个房间码上一次的存档（旧种子）。直接删掉，别让旧地形顶掉新房间。
       - 房主：自己的世界种子就是房间种子；万一 meta 被改过，也以这次上传的为准。 */
    w.seedLock = true;
    try {
      const raw0 = localStorage.getItem(worldKey(w.id));
      const old0 = raw0 ? JSON.parse(raw0) : null;
      if (old0 && old0.seed && (old0.seed | 0) !== (d.seed | 0)) {
        localStorage.removeItem(worldKey(w.id));
        toast('The Room Seed changed, so the old local Save is void (terrain regenerated from the Room Seed)', 4);
      }
    } catch (e) {}
    /* ★ v362：房间改动交给 startGame，在**生成第一个区块之前**合并进去。
       以前是「先建好出生点 → 整表合并 → 把自己已加载的区块全删掉、重生成 5×5（25 块）」：
       房主进自己的房间时 d.edits 有几万条，那一刻同步重生成 25 块地形 ≈ 175ms 起，
       表现就是「一进房整屏卡住、地形要等半天才铺开」。 */
    roomEditsPending = (d.edits || []).length ? d.edits : null;
    const roomEditCount = (d.edits || []).length;
    startGame(w);
    if (roomEditsPending) {
      /* startGame 提前返回（已经在世界里）才会走到这儿：改动事后补，只重建带改动的那几块 */
      adoptRoomEdits(roomEditsPending);
      const nBlock = rebuildRoomEditedChunks(roomEditsPending);
      roomEditsPending = null;
      if (nBlock) toast('Rebuilt ' + nBlock + ' nearby chunk(s) with Room changes', 2.5);
    }
    if (roomEditCount && isHostMode) {
      /* 界面上看得见：房主进房时把「房间里全部改动」同步回来了多少（客人只报附近的） */
      toast('Synced ' + roomEditCount + ' changes in the Room (including what friends dug/placed)', 4);
    }
    /* 村民小队：房间里存着、本地没有（换设备 / 清了浏览器缓存 / 换了浏览器）→ 从服务端恢复 */
    if (Array.isArray(d.squad) && d.squad.length && !squadList().length) {
      const n2 = restoreSquad(d.squad);
      if (n2) toast('Restored ' + n2 + ' villager(s) with their gear from the Room', 3.6);
    }
    for (const pl of (d.players || [])) if (pl.i !== net.id) ensureRemote(pl);
    // ★ 客人进房：优先回到「你上次在这个房间里的位置/朝向」；
    //   只有第一次进房（服务端没有你的记录）才落到房主旁边，免得两人叠在出生点互相看不见。
    if (!isHostMode) {
      if (d.pos && typeof d.pos.x === 'number') {
        player.p.set(d.pos.x, d.pos.y, d.pos.z);
        if (typeof d.pos.w === 'number') player.yaw = d.pos.w;
        if (typeof d.pos.q === 'number') player.pitch = d.pos.q;
        /* ★ v359：这个位置后来可能被别人盖了方块/自己站在墙缝里。
           老代码只看格子中心那一列、并且只会往上顶（顶进天花板就出不来）→ 卡进墙里。
           现在按 0.6×1.8 的包围盒判定，就近找合法位置（原地上下 → 一圈圈往外）。 */
        const fixed = unstickPlayer(player.p.x, player.p.y, player.p.z);
        player.v.set(0, 0, 0); player.fallFrom = null;
        toast(fixed ? 'Back to the Room (nudged out of blocks)' : 'Back to your last position in the Room', 2.5);
      } else {
        const others = (d.players || []).filter(p => p.i !== net.id);
        if (others.length) {
          const o = others[0];
          /* ★ v359：房主贴着墙/墙角站着时，+1.8 这一脚会正好落进墙里（"有时"卡墙就是这么来的）。
             现在先试房主四周 4 个方位，再交给 unstickPlayer 兜底。 */
          const spots = [[1.8, 0], [-1.8, 0], [0, 1.8], [0, -1.8], [1.3, 1.3], [-1.3, -1.3]];
          let placed = false;
          for (const [dx, dz] of spots) {
            const tx = o.x + dx, tz = o.z + dz;
            ensureAround(tx, tz, 1);
            if (playerBoxFree(tx, o.y + 0.1, tz)) { player.p.set(tx, o.y + 0.1, tz); placed = true; break; }
          }
          if (!placed) unstickPlayer(o.x + 1.8, o.y + 0.1, o.z + 1.8);
          player.v.set(0, 0, 0); player.fallFrom = null;
          toast('You are now at ' + (o.n || 'Host') + '\'s side', 3);
        }
      }
    }
    /* 房间时间：客人照房间的来；房主以自己为准（他刚把自己的时间送上去，再抄回来只会被房间旧值打回去） */
    if (typeof d.time === 'number' && !isHostMode) worldTime = d.time;
    connect();
    /* 房主：进房后立刻把自己的时间报一次。否则房间从「开房那一刻」开始算，
       客人要等第一次 5 秒上报才对齐（会看到时钟小幅跳一下）。 */
    if (isHostMode) net.timeT = 5;
    if (isHostMode) uploadMyWorld();
    else setTimeout(() => net.pullInv(), 400);        // 客人：把上次在这个房间的背包取回来
    toast(`Multiplayer "${net.code}" · ${net.isHost ? 'You are the host' : 'Joined'} · players ${(d.players || []).length}`, 4);   // join 返回的列表已包含自己
  }).catch(e => {
    net.active = false;
    try { history.replaceState(null, '', location.pathname); } catch (e2) {}
    toast('Can\'t reach the Multiplayer server: ' + e.message, 6);
    if (window.__bwWireEntry) window.__bwWireEntry();       // 连不上 → 退回单机入口，别让按钮点了没反应
  });

  const btnFR = document.getElementById('btnFriends');
  /* ---------------- 好友 / 申请加入 ---------------- */
  const apiCall = (obj) => fetch(EP, { method: 'POST', headers: { 'content-type': 'text/plain' }, body: JSON.stringify(obj) }).then(r => r.json());
  let frPanel = null, frOpen = false, frReq = [], frForceOpen = false, frInv = [];
  const frSeen = new Set();                       // 已提示过的申请：acct 心跳每 20s 重复回同一批 req，不能每次都弹面板
  const PCB = 'background:#0e1a28;color:#d8ecff;border:1px solid #2a4a66;border-radius:6px;padding:4px 6px;font:12px ui-monospace,monospace';

  function ensureFriendsUI() {
    // 新面板（MPUI，模块级）接管全部 UI；下面的旧代码保留作为历史参考，但不再执行。
    MPUI.ensure(); frPanel = MPUI.root;
    return;
    if (frPanel) return;
    const btn = document.getElementById('btnFriends');
    if (btn) {
      btn.style.display = '';
      btn.onclick = () => { frOpen = !frOpen; frPanel.style.display = frOpen ? 'block' : 'none'; if (frOpen) net.friendsPull(); };
    }
    frPanel = document.createElement('div');
    frPanel.id = 'friendPanel';
    frPanel.style.cssText = 'position:fixed;right:10px;top:44px;z-index:40;display:none;width:300px;max-height:70vh;overflow:auto;'
      + 'font:12px/1.6 ui-monospace,monospace;color:#d8ecff;background:rgba(9,20,32,.94);'
      + 'border:1px solid rgba(120,200,255,.35);border-radius:10px;padding:10px 12px;box-shadow:0 8px 24px rgba(0,0,0,.45)';
    frPanel.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'
      + '<b style="color:#8fe3ff">Multiplayer</b><span id="frWho" style="color:#8ea3ba"></span></div>'
      + '<div id="lbState" style="background:rgba(120,200,255,.08);border-radius:8px;padding:6px 8px;margin-bottom:8px;line-height:1.5"></div>'
      + '<div id="lbInv" style="margin-bottom:6px"></div>'
      + '<div id="lbPlayers" style="margin-bottom:8px"></div>'
      + '<div id="lbActions" style="display:flex;gap:6px;margin-bottom:6px"></div>'
      + '<div style="display:flex;gap:6px;margin-bottom:8px">'
      + '<input id="lbCode" maxlength="12" placeholder="Room code (sent by a friend)" style="flex:1;min-width:0;' + PCB + '">'
      + '<button class="btn" data-act="joinCode" style="padding:3px 8px">Join</button></div>'
      + '<div style="display:flex;gap:6px;margin-bottom:8px">'
      + '<input id="frName" maxlength="14" placeholder="Friend\'s name" style="flex:1;min-width:0;' + PCB + '">'
      + '<button class="btn" id="frAdd" style="padding:3px 8px">Add friend</button></div>'
      + '<div id="frMsg" style="color:#ffcf6b;font-size:11px;min-height:14px;margin-bottom:6px"></div>'
      + '<div id="frReq"></div><div id="frList" style="color:#8ea3ba">Loading…</div>';
    document.body.appendChild(frPanel);
    frPanel.querySelector('#frAdd').onclick = () => {
      const el = frPanel.querySelector('#frName');
      const target = (el.value || '').trim();
      if (!target) return;
      apiCall({ a: 'fadd', pid: net.id, nick: net.nick, code: net.code, target }).then(d => {
        frMsg(d.ok ? `Friend added: ${d.friend.nick}${d.friend.online ? ' (online)' : ' (offline)'}` : 'Couldn\'t add friend: ' + d.e);
        if (d.ok) { el.value = ''; net.friendsPull(); }
      }).catch(() => frMsg('Network error'));
    };
    frPanel.addEventListener('click', ev => {
      const b = ev.target.closest('button[data-act]');
      if (!b) return;
      const act = b.dataset.act;
      if (act === 'join') {
        apiCall({ a: 'jreq', pid: net.id, nick: net.nick, code: net.code, to: b.dataset.pid }).then(d => {
          frMsg(d.ok ? 'Request sent — waiting for them to Accept…' : ({ offline: 'They are offline', not_friend: 'Not friends yet' }[d.e] || 'Request failed: ' + d.e));
        }).catch(() => frMsg('Network error'));
      } else if (act === 'acc' || act === 'deny') {
        apiCall({ a: 'jres', pid: net.id, nick: net.nick, code: net.code, from: b.dataset.from, ok: act === 'acc' }).then(d => {
          if (d.ok) { frMsg(act === 'acc' ? 'Accepted — they\'re joining…' : 'Denied'); frReq = frReq.filter(x => x.from !== b.dataset.from); renderReq(); }
        }).catch(() => frMsg('Network error'));
      } else if (act === 'open') {
        frOpen = true; frPanel.style.display = 'block';
      } else if (act === 'leave') {
        net.leave();
      } else if (act === 'host') {
        hostRoom();
      } else if (act === 'copy') {
        copyInvite();
      } else if (act === 'joinCode') {
        const el = frPanel.querySelector('#lbCode');
        joinByCode(el && el.value);
      } else if (act === 'joinInv') {
        joinByCode(b.dataset.code);
      } else if (act === 'tp') {
        net.tpTo(b.dataset.id);
        renderLobby();
      } else if (act === 'invite') {
        apiCall({ a: 'invite', pid: net.id, nick: net.nick, code: net.code, to: b.dataset.pid })
          .then(d => frMsg(d.ok ? (d.pushed ? 'Invite sent — they\'ll see a "Join" button' : 'Invite sent (they\'re not in game; they\'ll see it next time they\'re online)')
                               : ({ not_friend: 'Not friends yet', no_room: 'Open a room before inviting' }[d.e] || ('Invite failed: ' + d.e))))
          .catch(() => frMsg('Network error'));
      }
    });
  }
  function frMsg(t) { MPUI.msg2(t); }                 // 统一走新面板底部的提示行

  /* ---------------- 联机面板：状态 / 玩家（名字+距离+传送）/ 开房·邀请·加入 ----------------
   * 用户要的流程：先在自己的世界里玩 → 点「开房」把这个世界变成房间 → 把房间码/邀请发给好友。
   * 房间码跟世界 id 绑死（存在世界 meta 里），所以同一个世界反复开房永远是同一个房间。 */
  const roomCodeOf = (w) => mpRoomCodeOf(w);          // 公式统一放在模块级（存档登记也用同一份）
  function hostRoom() {
    if (!ACCT.on) { MPUI.show('list'); return MPUI.msg2('Sign in to host a Room (offline is single player only)'); }
    if (net.active) return MPUI.msg2('You\'re already in a Multiplayer Room');
    if (!started) return frMsg('Go back to the World list, enter a World, then host');
    const w = worldMeta(currentId);
    if (!w) return frMsg('Couldn\'t find the Save for the current World');
    const code = roomCodeOf(w);
    try { localStorage.setItem('bw_nick', net.nick); } catch (e) {}
    MPUI.msg2('Hosting Room ' + code + ' … (uploading this World\'s blocks to the Room)');
    location.href = location.pathname + '?mp=1&go=1&host=1&lid=' + encodeURIComponent(w.id)
      + '&world=' + encodeURIComponent(code) + '&nick=' + encodeURIComponent(ACCT.nick || net.nick);
  }
  function joinByCode(code) {
    const c = String(code || '').trim().replace(/[^\w-]/g, '').toUpperCase();
    if (!c) return frMsg('Enter the room code first');
    if (net.active && c === net.code) return frMsg('You\'re already in this Room');
    frMsg('Entering Room ' + c + ' …');
    setTimeout(() => {
      location.href = location.pathname + '?mp=1&go=1&world=' + encodeURIComponent(c) + '&nick=' + encodeURIComponent(net.nick);
    }, 300);
  }
  function copyInvite() {
    if (!net.active) return MPUI.msg2('Host a Room first to get an invite link');
    const link = location.origin + location.pathname + '?mp=1&go=1&world=' + encodeURIComponent(net.code);
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(link);
      else { const ta = document.createElement('textarea'); ta.value = link; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); }
      frMsg('Invite link copied (Room ' + net.code + '）：' + link);
    } catch (e) { frMsg('Copy failed — send this manually: Room code ' + net.code + ' · ' + link); }
  }
  net.tpTo = (id) => {
    const r = net.remotes.get(id);
    if (!r) return false;
    const o = r.obj.position;
    player.p.set(o.x + 1.4, o.y + 0.6, o.z + 1.4);
    toast('Teleported to ' + (r.name || id) + '\'s side', 2);
    return true;
  };
  function renderLobby() {
    MPUI.render();                                  // 新面板负责渲染；下面旧 DOM（#lbState 等）已经不存在，全部是 null 保护的空转
    if (!frPanel) return;
    const st = frPanel.querySelector('#lbState'), ac = frPanel.querySelector('#lbActions');
    if (net.active) {
      if (st) st.innerHTML = '<div>In Multiplayer · Room <b style="color:#8fe3ff;font-size:15px;letter-spacing:2px">' + escHtml(net.code) + '</b>'
        + (net.isHost ? ' <span style="color:#7ef0a0">Host</span>' : '') + '</div>'
        + '<div style="color:#8ea3ba">Players ' + (net.remotes.size + 1) + ' · ' + (net.connected ? 'Connected' : 'Disconnected') + ' · ' + (net.rtt | 0) + 'ms'
        + (net.lid ? ' · the Room is your own World; progress saves as usual' : '') + '</div>';
      if (ac) ac.innerHTML = '<button class="btn" data-act="copy" style="flex:1;padding:4px 8px">Copy invite link</button>'
        + '<button class="btn" data-act="leave" style="padding:4px 8px;color:#ffb0b0;border-color:#5a2b2b">Leave Multiplayer</button>';
    } else {
      const w = currentId ? worldMeta(currentId) : null;
      if (st) st.innerHTML = '<div>Now: single player' + (w ? ' · World "' + escHtml(w.name) + '」' : ' · World list') + '</div>'
        + '<div style="color:#8ea3ba">' + (started
          ? 'Tap "Host" below to turn this World into a Multiplayer Room, then send the Room code or invite to Friends'
          : 'Go back to the World list, enter a World, then host and invite Friends') + '</div>';
      if (ac) ac.innerHTML = started
        ? '<button class="btn gold" data-act="host" style="flex:1;padding:4px 8px">Host: play together in "' + escHtml((w && w.name) || 'this World') + '」</button>'
        : '<span style="color:#7a8b9c;font-size:11px">Enter a World to host / or join a friend with a Room code below</span>';
    }
    const iv = frPanel.querySelector('#lbInv');
    if (iv) iv.innerHTML = frInv.length ? frInv.map(v =>
      '<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:4px;color:#ffcf6b">'
      + '<span>' + escHtml(v.nick) + ' invited you to Room <b>' + escHtml(v.code) + '</b></span>'
      + '<button class="btn" data-act="joinInv" data-code="' + escHtml(v.code) + '" style="padding:2px 7px">Join</button></div>').join('') : '';
    const pl = frPanel.querySelector('#lbPlayers');
    if (pl) {
      if (!net.active) pl.innerHTML = '';
      else {
        const rows = ['<div style="color:#7ef0a0;padding:2px 0">● ' + escHtml(net.nick) + ' · you' + (net.isHost ? '(host)' : '') + '</div>'];
        for (const [id, r] of net.remotes) {
          const o = r.obj.position;
          const d = Math.hypot(o.x - player.p.x, o.z - player.p.z) | 0;
          rows.push('<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;padding:2px 0;border-top:1px solid rgba(120,200,255,.12)">'
            + '<span>● ' + escHtml(r.name || id) + ' · <b style="color:#8fe3ff">' + d + 'm</b></span>'
            + '<button class="btn" data-act="tp" data-id="' + escHtml(id) + '" style="padding:2px 7px">Teleport there</button></div>');
        }
        pl.innerHTML = rows.join('');
      }
    }
    const who = frPanel.querySelector('#frWho');
    if (who) who.textContent = net.active ? (net.nick + ' · ' + net.code) : (net.nick || '');
  }
  function renderReq() {
    const el = frPanel && frPanel.querySelector('#frReq');
    if (!el) return;
    el.innerHTML = frReq.length
      ? '<div style="color:#ffcf6b;margin-bottom:4px">Join request</div>' + frReq.map(r =>
          `<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:4px">\n             <span>${r.nick} wants to join</span>\n             <span><button class="btn" data-act="acc" data-from="${r.from}" style="padding:2px 7px">Accept</button>\n             <button class="btn" data-act="deny" data-from="${r.from}" style="padding:2px 7px">Deny</button></span>\n           </div>`).join('')
      : '';
  }
  function renderFriends(d) {
    ensureFriendsUI();
    MPUI.setFriends(d);                             // 新面板拿数据
    if (Array.isArray(d.inv)) frInv = d.inv;
    renderLobby();
    if (Array.isArray(d.req) && d.req.length) {
      frReq = d.req;
      renderReq();
      /* 去重按「人」而不是「时间」：同一个好友反复发申请（或服务端每次 join 都排一条新的）
         以前每来一条时间戳就 fresh 一次 → 面板被反复自动弹开，看着像关不掉。 */
      const fresh = d.req.some(r => !frSeen.has(r.from));
      for (const r of d.req) frSeen.add(r.from);
      if (fresh || frForceOpen) {                 // 只在「来了新申请」时自动弹出（以前心跳也会重弹）
        frForceOpen = false;
        if (!frOpen) { frOpen = true; MPUI.autoShow(); }   // ★ 不再直接写 frPanel.style.display（内联样式会让「返回」失效）
      }
    } else { renderReq(); }
    const list = frPanel.querySelector('#frList');
    if (!list) return;
    const fs2 = d.friends || [];
    list.innerHTML = fs2.length ? fs2.map(f =>
      `<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;padding:3px 0;border-top:1px solid rgba(120,200,255,.12)">
         <span><b style="color:${f.online ? '#7ef0a0' : '#7a8b9c'}">${f.online ? '●' : '○'}</b> ${escHtml(f.nick)}
         <span style="color:#7a8b9c">${f.online ? (f.world ? '· Room ' + escHtml(f.world) : '· Online') : '· Offline'}</span></span>
         ${net.active
            ? `<button class="btn" data-act="invite" data-pid="${escHtml(f.pid)}" style="padding:2px 7px">Invite</button>`
            : (f.online && f.world ? `<button class="btn" data-act="join" data-pid="${escHtml(f.pid)}" style="padding:2px 7px">Ask to join</button>` : '')}
       </div>`).join('') : '<span style="color:#7a8b9c">No friends yet — enter their name above to add one</span>';
  }
  /* 把当前外观（含 PNG 皮肤数据）推给服务端/其它人。
     ★ WS 模式（局域网）根本没有 HTTP sync，皮肤以前只在 join 时上传一次 →
       中途换皮肤别人永远看不到（"联机皮肤没更新"就是这么来的）。 */
  net.pushLook = () => {
    const skh = skinHash(LOOK.skinSrc);
    const msg = { t: 'look', sk: LOOK.skin, cl: LOOK.cloth, hr: LOOK.hair, hs: LOOK.hs, oh: (player.off ? player.off.id : 0), skn: skh,
                  skd: (LOOK.skinSrc === 'custom') ? skinPngData() : '' };
    if (net.ws && net.ws.readyState === 1) {
      try { net.ws.send(JSON.stringify(msg)); net.skinSent = skh; } catch (e) {}
    } else {
      net.skinSent = '';                 // 轮询模式：清掉标记，让下一次 sync 顺带把 skd 带上
    }
    net.lookSig = LOOK.skin + ':' + LOOK.cloth + ':' + LOOK.hair + ':' + LOOK.hs + ':' + skh;
  };
  net.friendsPull = () => apiCall({ a: 'acct', tok: acctTok(), pid: net.id, nick: net.nick, code: net.code, pworld: net.code })
    .then(d => { if (d.ok) renderFriends(d); }).catch(() => {});
  net.heartbeat = () => apiCall({ a: 'acct', tok: acctTok(), pid: net.id, nick: net.nick, code: net.code, pworld: net.code })
    .then(d => { if (d.ok) renderFriends(d); }).catch(() => {});

  // ws 推送：好友申请 / 对方同意 / 被拒绝 / 好友列表变了
  net.onSocial = (m) => {
    if (m.t === 'req') {
      frSeen.add(m.req.from);
      frReq = [m.req]; frForceOpen = true;
      MPUI.autoShow();                         // 用户刚关过面板就不硬弹（toast + 好友按钮上的数字照样提示）
      MPUI.pullFriends();
      toast(`${m.req.nick} wants to join your World — tap "Accept" and the Room opens automatically`, 5);
    }
    else if (m.t === 'acc') {
      if (m.code === net.code) { toast(`${m.nick} accepted your request to join "${m.code}" — you're already in that World`, 3); return; }
      toast(`${m.nick} accepted your request to join "${m.code}" — entering…`, 3);
      // ★ 不再直接跳：房间可能还在房主那边开着，先问 canjoin（有通行证 + 房间存在）再进
      setTimeout(() => mpJoinRoom(m.code, 1), 400);
    }
    else if (m.t === 'deny') {
      toast(`${m.nick} denied your join request`, 3);
      if (MPUI.waiting) { MPUI.setWait(null); MPUI.render(); }     // 撤掉「等待同意」，不然一直挂着
    }
    else if (m.t === 'inv') {                       // 房主邀请：面板自动弹出来，点「加入」就进他的房间
      frInv = frInv.filter(x => x.code !== m.code).concat([{ code: m.code, nick: m.nick, at: Date.now() }]);
      ensureFriendsUI(); renderLobby();
      if (!frOpen) { frOpen = true; MPUI.autoShow(); }   // 同上：不写内联 display，免得关不掉
      toast(`${m.nick} invited you to Room ${m.code} (tap "Join")`, 6);
    }
    else if (m.t === 'f') { ensureFriendsUI(); net.friendsPull(); toast(`${m.nick} added you as a friend`, 3); }
  };

  ensureFriendsUI();
  net.heartbeat();
  setInterval(() => { net.heartbeat(); }, 20000);              // 在线状态心跳
  setInterval(() => { if (frOpen) net.friendsPull(); }, 4000);  // 面板开着时刷列表
  setInterval(() => { if (frOpen && net.active) renderLobby(); }, 1000);   // 距离每秒刷新

  window.NET = net;
  /* 模块级「多人游戏」面板（MPUI）通过这个口子操作房间：开房/复制邀请/退出/传送 */
  window.__bwMP = {
    host: () => hostRoom(),
    copy: () => copyInvite(),
    leave: () => net.leave(),
    tp: (id) => net.tpTo(id),
  };
  window.__bwMPSync = (open) => { frOpen = !!open; };
  if (btnFR) { btnFR.style.display = ''; btnFR.onclick = () => MPUI.show('list'); }
  // ★ 这里以前是 `mpBtn.style.display = 'none'`，但它在 IIFE 里同步执行 —— 只要 URL 带 ?mp=1
  //   （哪怕联机服务器根本连不上、人还停在开始界面），这个按钮就会「闪一下就消失」。
  //   改成：不隐藏，只在联机失败时让它变成「退回单机」的出口。
  const mpBtn = document.getElementById('btnMP');
  if (mpBtn) {
    mpBtn.onclick = () => {
      if (net.active && !net.connected) { location.href = location.pathname; return; }   // 没连上 → 退回单机（去掉 ?mp）
      MPUI.show('list');                          // 连着 / 单机 → 打开「多人游戏」面板
    };
  }



  // ★ 联机时关掉 GAME.debug：give/tp/setBlock/travel 都能被控制台随手调用，等于开挂按钮。
  //   注意这是「防手滑/防随手作弊」，真正的门槛在服务端（方块编辑校验）。?dev=1 只给我自己验收用。
  net.devOk = q.has('dev');
  if (!net.devOk && window.GAME && window.GAME.debug) {
    const stubbed = new Set(['give', 'tp', 'setBlock', 'travel', 'start', 'startCreative', 'startWorld',
      'createWorld', 'clearInv', 'equip', 'fly', 'setHp', 'steps', 'killMobs', 'spawnKind', 'spawnAt',
      'usePortal', 'openPress', 'pressN', 'processN', 'setTime', 'furnaceTick', 'chipBatch',
      'chargeStart', 'chargerTick', 'setCharge']);
    const kept = {};
    for (const k of Object.keys(window.GAME.debug)) {
      kept[k] = stubbed.has(k) ? (() => 'disabled_in_multiplayer') : window.GAME.debug[k];
    }
    window.GAME.debug = kept;
    console.warn('[bw] Multiplayer: debug API disabled (add ?dev=1 to unlock — acceptance testing only)');
  }
})();

/* ---------------- 多人游戏入口（单机/联机都走同一个面板） ----------------
 * 以前这里是一个「填昵称 + 房间码」的小浮层；现在统一交给模块级的 MPUI：
 *   服务器列表（现在谁在玩）/ 直接连接（房间码或服务器地址）/ 好友 —— 和 MC 的多人游戏一个路子。
 * 未登录时面板里直接给登录/注册表单，并写明「不登录只能单机」。 */
(function wireFriendsEntry() {
  const bind = () => {
    const b = document.getElementById('btnFriends');        // 游戏内右上角「联机」
    if (b) { b.style.display = ''; b.textContent = 'Multiplayer'; b.onclick = () => MPUI.show('list'); }
    const f = document.getElementById('btnFriendsHud');      // 游戏内右上角「好友」
    if (f) f.onclick = () => MPUI.show('friend');
    const m = document.getElementById('btnMP');              // 世界列表「🌐 联机」
    if (m) m.onclick = () => MPUI.show('list');
    const mm = document.getElementById('btnMPMenu');         // 开始界面「多人游戏」
    if (mm) mm.onclick = () => MPUI.show('list');
    // 裸链接带着世界码（?mp=1 但没有 go=1）：不自动进服，只把面板打开让人确认
    if (window.__bwPrefillMP) setTimeout(() => {
      MPUI.show('friend');
      if (window.__bwPrefillMP.why === 'stale') {
        MPUI.msg2('That earlier "Join" already ended (it won\'t enter the Room again): to enter someone\'s World, tap "Ask to join" in Friends');
      }
    }, 350);
  };
  window.__bwWireEntry = bind;
  bind();
})();

freezeInit();                                     // 冻结遮罩先就位（丢上下文时立刻能显示）
requestAnimationFrame(frame);
